INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('0A002', '0', 'A', 'Power generating or propulsion equipment “specially designed” for use with space, marine or mobile “nuclear reactors”. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', 'Power generating or propulsion equipment “specially designed” for use with space, marine or mobile “nuclear reactors”. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A501', '0', 'A', 'Firearms (except 0A502 shotguns, 0A506 semi-automatic rifles, 0A507 semi-automatic pistols, and 0A508 semi-automatic shotguns) and related commodities (except semi-automatic related commodities enumerated or otherwise described in Eccn 0A509 for Eccns 0A506, 0A507, or 0A508) as follows', 'Firearms (except 0A502 shotguns, 0A506 semi-automatic rifles, 0A507 semi-automatic pistols, and 0A508 semi-automatic shotguns) and related commodities (except semi-automatic related commodities enumerated or otherwise described in Eccn 0A509 for Eccns 0A506, 0A507, or 0A508) as follows. Items: a. Non-automatic and non-semi-automatic firearms equal to .50 caliber (12.7 mm) or less. Note 1 to paragraph 0A501.a: ''Combination pistols'' are controlled under ECCN 0A501.a. A ''combination pistol'' (a.k.a., a combination gun) has at least one rifled barrel and at least one smoothbore barrel (generally a shotgun style barrel). Note 2 to paragraph 0A501.a: Semi-automatic firearms equal to .50 caliber (12.7 mm) or less are controlled under ECCNs 0A506 and 0A507. Technical Note to 0A501.a: Firearms described in 0A501.a include those chambered for the .50 BMG cartridge. b. Non-automatic and non-semi-au…', '["NS1?","RS1?","FC1?","UN?","AT1"]', '["LVS"]', 'LVS: $500 for 0A501.c, .d, and .x. $500 for 0A501.c, .d, .e, and .x if the ultimate destination is Canada. | GBS: N/A License Exception STA may not be used for ECCN 0A501.a, .b, .c, .d, or .e, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR). License Exception STA may not be used for any item in this entry to any of the destinations listed in Country Group A:6 (See Supplement No.1 to part 740 of the EAR).', 'NS applies to entire entry except 0A501.y -> NS Column 1.; RS applies to entire entry except 0A501.y -> RS Column 1.; FC applies to entire entry except 0A501.y -> FC Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to entire entry -> AT Column 1.', '(1) See USML Category I for firearms that are fully automatic, and certain related parts, components, accessories, and attachments (including magazines with a capacity of greater than 50 rounds). (2) See ECCN 0A506 for semi-automatic rifles. (3) See ECCN 0A507 for semi-automatic pistols. (4) See ECCN 0A508 for semi-automatic shotguns and ECCN 0A502 for certain “parts” and “components” for semi-automatic shotguns that are not controlled by 0A509.a or .c. (5) See ECCN 0A509 for enumerated or otherwise described “parts,” “components,” devices, “accessories,” and “attachments” for ECCNs 0A506, 0A507, and 0A508. (6) See .d, .x, and .y of this entry for other “parts,” “components,” “accessories,” and “attachments” “specially designed” for 0A506 and 0A507, or 0A508. (7) See ECCN 0A502 for non-automatic shotguns and their “parts” and “components” that are subject to the EAR and for certain “parts” and “components” for semi-automatic shotguns that are not controlled by 0A509.a or .c. (8) See ECCN 0A504 and USML Category XII for controls on optical sighting devices.', '15 CFR Part 774, Supplement No. 1, ECCN 0A501 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A502', '0', 'A', 'Shotguns (except 0A508 semi-automatic shotguns) and related commodities (except semi-automatic related commodities enumerated or otherwise described in ECCN 0A509 for ECCN 0A508) as follows', 'Shotguns (except 0A508 semi-automatic shotguns) and related commodities (except semi-automatic related commodities enumerated or otherwise described in ECCN 0A509 for ECCN 0A508) as follows', '["NS1?","RS1?","FC1","CC1?","CC2?","CC3?","UN?","AT1?"]', '["LVS"]', 'LVS: $500 for 0A502.c, and .d. $500 for 0A502.c, .d, and .e if the ultimate destination is Canada. | GBS: N/A License Exception STA may not be used to ship any shotguns with barrel length less than 18 inches controlled in 0A502, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to shotguns with a barrel length less than 18 inches (45.72 cm) -> NS Column 1.; RS applies to shotguns with a barrel length less than 18 inches (45.72 cm) -> RS Column 1.; FC applies to entire entry -> FC Column 1.; CC applies to shotguns with a barrel length less than 24 in. (60.96 cm) and paragraphs .c, .d, and .e controlled by this entry regardless of end user -> CC Column 1.; CC applies to shotguns with a barrel length greater than or equal to 24 in. (60.96 cm), regardless of end user -> CC Column 2.; CC applies to shotguns with a barrel length greater than or equal to 24 in. (60.96 cm) if for sale or resale to police or law enforcement -> CC Column 3.; UN applies to entire entry -> See § 746.1(b) of the EAR for UN controls.; AT applies to shotguns with a barrel length less than 18 inches (45.72 cm) -> AT Column 1.', '(1) See USML Category I for shotguns described therein. (2) See ECCN 0A508 for semi-automatic shotguns. (3) See ECCN 0A509 for enumerated or otherwise described “parts,” “components,” devices, “accessories,” and “attachments” for ECCN 0A508. (4) See 0A501.d, .x, and .y for other “parts,” “components,” “accessories,” and “attachments” “specially designed” for 0A508. (5) See ECCNs 0A501 for non-semi-automatic firearms, 0A506 for semi-automatic rifles, and 0A507 for semi-automatic pistols.', '15 CFR Part 774, Supplement No. 1, ECCN 0A502 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A503', '0', 'A', 'Discharge type arms; non-lethal or less-lethal grenades and projectiles, and “specially designed” “parts” and “components” of those projectiles; and devices to administer electric shock, for example, stun guns, shock batons, shock shields, electric cattle prods, immobilization guns and projectiles; except equipment used to slaughter domestic animals or used exclusively to treat or tranquilize animals, and except arms designed solely for signal, flare, or saluting use; and “specially designed” “parts” and “components,” n.e.s', 'Discharge type arms; non-lethal or less-lethal grenades and projectiles, and “specially designed” “parts” and “components” of those projectiles; and devices to administer electric shock, for example, stun guns, shock batons, shock shields, electric cattle prods, immobilization guns and projectiles; except equipment used to slaughter domestic animals or used exclusively to treat or tranquilize animals, and except arms designed solely for signal, flare, or saluting use; and “specially designed” “parts” and “components,” n.e.s', '["CC?","UN?"]', '[]', 'LVS: N/A | GBS: N/A', 'CC applies to entire entry -> A license is required for ALL destinations, except Canada, regardless of end use. Accordingly, a column specific to this control does not appear on the Commerce Country Chart. (See part 742 of the EAR for additional information); UN applies to entire entry -> See § 746.1(b) of the EAR for UN controls', 'Law enforcement restraint devices that administer an electric shock are controlled under ECCN 0A982. Electronic devices that monitor and report a person''s location to enforce restrictions on movement for law enforcement or penal reasons are controlled under ECCN 3A981.', '15 CFR Part 774, Supplement No. 1, ECCN 0A503 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A504', '0', 'A', 'Optical sighting devices for firearms (including shotguns controlled by 0A502); and “components” as follows', 'Optical sighting devices for firearms (including shotguns controlled by 0A502); and “components” as follows. Items: a. Telescopic sights. b. Holographic sights. c. Reflex or “red dot” sights. d. Reticle sights. e. Other sighting devices that contain optical elements. f. Laser aiming devices or laser illuminators “specially designed” for use on firearms, and having an operational wavelength exceeding 400 nm but not exceeding 710 nm. Note 1 to 0A504.f: 0A504.f does not control laser boresighting devices that must be placed in the bore or chamber to provide a reference for aligning the firearms sights. g. Lenses, other optical elements and adjustment mechanisms for articles in paragraphs .a, .b, .c, .d, .e, or .i. h. [Reserved] i. Riflescopes that were not “subject to the EAR” as of March 8, 2020 and are “specially designed” for use in firearms that are “subject to the ITAR.” Note 2 to par…', '["RS1?","FC1?","CC1","UN?"]', '["LVS"]', 'LVS: $500 for 0A504.g. | GBS: N/A', 'RS applies to paragraph .i -> RS Column 1.; FC applies to paragraphs .a, .b, .c, .d, .e, .g, and .i of this entry -> FC Column 1.; CC applies to entire entry -> CC Column 1.; UN applies to entire entry -> See § 746.1(b) of the EAR for UN controls.', '(1) See USML Category XII(c) for sighting devices using second generation image intensifier tubes having luminous sensitivity greater than 350 µA/lm, or third generation or higher image intensifier tubes, that are “subject to the ITAR.” (2) See USML Category XII(b) for laser aiming or laser illumination systems “subject to the ITAR.” (3) Section 744.9 of the EAR imposes a license requirement on certain commodities described in 0A504 if being exported, reexported, or transferred (in-country) for use by a military end user or for incorporation into an item controlled by ECCN 0A919.', '15 CFR Part 774, Supplement No. 1, ECCN 0A504 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A505', '0', 'A', 'Ammunition as follows', 'Ammunition as follows. Items: a. Ammunition for firearms controlled by ECCNs 0A501, 0A506, or 0A507 or USML Category I and not enumerated in paragraph .b, .c, or .d of this entry or described in USML Category III. b. Buckshot (No. 4 .24” diameter and larger, any material) shotgun shells and shotgun shells that contain only buckshot, or are for the dispersion of chemical irritants. c. Shotgun shells (including less than lethal rounds) that do not contain buckshot; and “specially designed” “parts” and “components” of shotgun shells. d. Blank ammunition for firearms controlled by ECCNs 0A501, 0A502, 0A506, 0A507, or 0A508 and not described in USML Category III. Technical Note to 0A505.d: Includes ''marking rounds'' that have paint/dye as the projectile. e. through w. [Reserved] x. “Parts” and “components” that are “specially designed” for a commodity subject to control in this ECCN or a defe…', '["NS1?","RS1?","FC1?","CC1?","UN?","AT1?","AT?"]', '["LVS"]', 'LVS: $500 for items in 0A505.x, except $3,000 for items in 0A505.x that, immediately prior to March 9, 2020, were classified under 0A018.b. (i.e., “Specially designed” components and parts for ammunition, except cartridge cases, powder bags, bullets, jackets, cores, shells, projectiles, boosters, fuses and components, primers, and other detonating devices and ammunition belting and linking machines (all of which are “subject to the ITAR”). (See 22 CFR parts 120 through 130)). | GBS: N/A License Exception STA may not be used for ECCN 0A505, to any of the destinations listed in Country Group A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to 0A505.a and .x -> NS Column 1.; RS applies to 0A505.a and .x -> RS Column 1.; FC applies to entire entry except 0A505.d -> FC Column 1.; CC applies to 0A505.b -> CC Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to 0A505.a, .d, and .x -> AT Column 1.; AT applies to 0A505.c -> A license is required for items controlled by paragraph .c of this entry to North Korea for anti-terrorism reasons. The Commerce Country Chart is not designed to determine AT licensing requirements for this entry. See § 742.19 of the EAR for additional information.', '(1) See USML Category III for ammunition for modern heavy weapons such as howitzers, artillery, cannon, mortars and recoilless rifles as well as inherently military ammunition types such as ammunition preassembled into links or belts, caseless ammunition, tracer ammunition, ammunition with a depleted uranium projectile or a projectile with a hardened tip or core and ammunition with an explosive projectile. (2) Percussion caps, and lead balls and bullets, for use with muzzle-loading firearms are EAR99 items. (3) See USML Category III for shotgun projectiles that are flechettes, incendiary, tracer, or explosive.', '15 CFR Part 774, Supplement No. 1, ECCN 0A505 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A506', '0', 'A', 'Semi-Automatic Rifles as follows', 'Semi-Automatic Rifles as follows. Items: a. Semi-automatic centerfire (non-rimfire) rifles equal to .50 caliber (12.7 mm) or less. b. Semi-automatic rimfire rifles equal to .50 caliber (12.7 mm) or less. Note 1 to 0A506.a and .b: “Parts” and “components” that are “specially designed” for a commodity classified under .a or .b of this entry, except those controlled under ECCN 0A509, are controlled under ECCN 0A501.c, .d, .x, or .y. Technical Note 1 to 0A506: Firearms described in 0A506 include those chambered for the .50 BMG cartridge. Technical Note 2 to 0A506: Firearms described in 0A506 include pistols built with, e.g., AR- or AK-style receivers (frames).', '["NS1","RS1","FC1","UN?","AT1"]', '[]', 'LVS: N/A | GBS: N/A License Exception STA may not be used for ECCN 0A506, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 1.; RS applies to entire entry -> RS Column 1.; FC applies to entire entry -> FC Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to entire entry -> AT Column 1.', '(1) See USML Category I for firearms that are fully automatic, and magazines with a capacity of greater than 50 rounds. (2) See ECCN 0A507 for semi-automatic pistols, excluding pistols built with, e.g., AR- or AK-style receivers (frames), which are controlled under ECCN 0A506. (3) See ECCN 0A508 for semi-automatic shotguns and ECCN 0A502 for certain “parts” and “components” for semi-automatic shotguns that are not controlled by 0A509.a or .c. (4) See ECCN 0A509 for enumerated or otherwise described “parts,” “components,” devices, “accessories,” and “attachments” for ECCNs 0A506, 0A507, and 0A508. (5) See 0A501.c, .d, .x, and .y for other “parts,” “components,” “accessories,” and “attachments” “specially designed” for 0A506 and 0A507, or 0A508. (6) See ECCN 0A501 for non-semi-automatic firearms (except 0A502 shotguns) and related commodities that are subject to the EAR. (7) See ECCN 0A502 for non-automatic shotguns and their “parts” and “components” that are subject to the EAR and certain “parts” and “components” for semi-automatic shotguns that are not controlled by 0A509.a or .c. (8) See ECCN 0A504 and USML Category XII for controls on optical sighting devices.', '15 CFR Part 774, Supplement No. 1, ECCN 0A506 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A507', '0', 'A', 'Semi-Automatic Pistols as follows', 'Semi-Automatic Pistols as follows. Items: a. Semi-automatic centerfire (non-rimfire) pistols equal to .50 caliber (12.7 mm) or less. b. Semi-automatic rimfire pistols equal to .50 caliber (12.7 mm) or less. Note 1 to 0A507.a and .b: “Parts” and “components” that are “specially designed” for a commodity classified under .a or .b of this entry, except those controlled under ECCN 0A509, are controlled under ECCN 0A501.c, .d, .x, or .y. Note 2 to 0A507: Firearms, including pistols, built with, e.g., AR- or AK-style receivers (frames) are controlled under ECCN 0A506. Technical Note to 0A507: Firearms described in 0A507 includes those chambered for the .50 BMG cartridge, including revolvers, or that may be developed to fire .50 BMG cartridges.', '["NS1","RS1","FC1","UN?","AT1"]', '[]', 'LVS: N/A | GBS: N/A License Exception STA may not be used for ECCN 0A507, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 1.; RS applies to entire entry -> RS Column 1.; FC applies to entire entry -> FC Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to entire entry -> AT Column 1.', '(1) See USML Category I for firearms that are fully automatic, and magazines with a capacity of greater than 50 rounds. (2) See ECCN 0A506 for semi-automatic rifles. (3) See ECCN 0A508 for semi-automatic shotguns and ECCN 0A502 for certain “parts” and “components” for semi-automatic shotguns that are not controlled by 0A509.a or .c. (4) See ECCN 0A509 for enumerated or otherwise described “parts,” “components,” devices, “accessories,” and “attachments” for ECCNs 0A506, 0A507, and 0A508. (5) See ECCN 0A501.c, .d, .x, and .y for other “parts,” “components,” “accessories,” and “attachments” “specially designed” for 0A506 and 0A507, or 0A508. (6) See ECCN 0A501 for non-semi-automatic firearms (except 0A502 shotguns) and related commodities that are subject to the EAR. (7) See ECCN 0A502 for non-automatic shotguns and their “parts” and “components” that are subject to the EAR and certain “parts” and “components” for semi-automatic shotguns that are not controlled by 0A509.a or .c. (8) See ECCN 0A504 and USML Category XII for controls on optical sighting devices.', '15 CFR Part 774, Supplement No. 1, ECCN 0A507 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A508', '0', 'A', 'Semi-Automatic Shotguns as follows', 'Semi-Automatic Shotguns as follows. Items: a. Semi-automatic centerfire (non-rimfire) shotguns. b. Semi-automatic rimfire shotguns.', '["NS1?","RS1?","FC1","CC1?","CC2?","CC3?","UN?","AT1?"]', '[]', 'LVS: N/A | GBS: N/A License Exception STA may not be used for any shotguns with barrel length less than 18 inches controlled in 0A508, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to semi-automatic shotguns with a barrel length less than 18 inches (45.72 cm) -> NS Column 1.; RS applies to semi-automatic shotguns with a barrel length less than 18 inches (45.72 cm) -> RS Column 1.; FC applies to entire entry -> FC Column 1.; CC applies to shotguns with a barrel length less than 24 in. (60.96 cm) and shotgun “components” controlled by this entry regardless of end user -> CC Column 1.; CC applies to shotguns with a barrel length greater than or equal to 24 in. (60.96 cm), regardless of end user -> CC Column 2.; CC applies to shotguns with a barrel length greater than or equal to 24 in. (60.96 cm) if for sale or resale to police or law enforcement -> CC Column 3.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to semi-automatic shotguns with a barrel length less than 18 inches (45.72 cm) -> AT Column 1.', '(1) See USML Category I for shotguns that are fully automatic. (2) See ECCN 0A502 for non-semi-automatic shotguns. (3) See ECCN 0A509 for enumerated or otherwise described “parts,” “components,” devices, “accessories,” and “attachments” for ECCN 0A508. (4) See 0A501.d, .x, and .y for other “parts,” “components,” “accessories,” and “attachments” “specially designed” for 0A508. (5) See ECCNs 0A501 for non-semi-automatic firearms, 0A506 for semi-automatic rifles, and 0A507 for semi-automatic pistols.', '15 CFR Part 774, Supplement No. 1, ECCN 0A508 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A509', '0', 'A', 'Certain “parts,” “components,” devices, “accessories,” and “attachments” for items controlled under ECCNs 0A506, 0A507, and 0A508 as follows', 'Certain “parts,” “components,” devices, “accessories,” and “attachments” for items controlled under ECCNs 0A506, 0A507, and 0A508 as follows. Items: a. Any “part,” “component,” device, “attachment,” or “accessory” not elsewhere specified on the USML that is designed or functions to convert a non-semi-automatic firearm controlled by 0A501 or 0A502 to semi-automatic or to accelerate the rate of fire of a semi-automatic firearm controlled by 0A506, 0A507, or 0A508. b. Receivers (frames), including castings, forgings, stampings, or machined items thereof, “specially designed” for an item controlled by ECCN 0A506. c. Receivers (frames), including castings, forgings, stampings, or machined items thereof, “specially designed” for an item controlled by ECCN 0A507. d. Receivers (frames) and “specially designed” “complete breech mechanisms” for a commodity controlled by ECCN 0A508. Note 1 to 0A50…', '["NS1?","RS1?","FC1","CC1?","UN?","AT1?"]', '["LVS"]', 'LVS: $500 for 0A509.a, $500 for 0A509.b, .c, and .d if the ultimate destination is Canada | GBS: N/A License Exception STA may not be used for ECCN 0A509, except for 0A509.a for items for ECCN 0A502 or ECCN 0A508, and 0A509.d, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to entire entry except 0A509.a for items for ECCN 0A502 or ECCN 0A508, and 0A509.d -> NS Column 1.; RS applies to entire entry except 0A509.a for items for ECCN 0A502 or ECCN 0A508, and 0A509.d -> RS Column 1.; FC applies to entire entry -> FC Column 1.; CC applies to 0A509.a for items for ECCN 0A502 or ECCN 0A508, and 0A509.d -> CC Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to entire entry except 0A509.a for items for ECCN 0A502 or ECCN 0A508, and 0A509.d -> AT Column 1.', '(1) See USML Category I for firearms that are fully automatic, and magazines with a capacity of greater than 50 rounds. (2) See ECCN 0A506 for semi-automatic rifles. (3) See ECCN 0A507 for semi-automatic pistols. (4) See ECCN 0A508 for semi-automatic shotguns and ECCN 0A502 for certain “parts” and “components” for semi-automatic shotguns that are not controlled by .a or .c of this entry. (5) See ECCN 0A501.c, .d, .x, and .y for other “parts,” “components,” “accessories,” and “attachments” “specially designed” for 0A506 and 0A507, or 0A508. (6) See ECCN 0A501 for non-semi-automatic firearms (except 0A502 shotguns) and related commodities that are subject to the EAR. (7) See ECCN 0A502 for non-automatic shotguns and their “parts” and “components” that are subject to the EAR and certain “parts” and “components” for semi-automatic shotguns that are not controlled by .a or .d of this entry. (8) See ECCN 0A504 and USML Category XII for controls on optical sighting devices. (9) See USML Category I for similar items.', '15 CFR Part 774, Supplement No. 1, ECCN 0A509 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A521', '0', 'A', 'Any commodity subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', 'Any commodity subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A521 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A602', '0', 'A', 'Guns and Armament as follows', 'Guns and Armament as follows. Items: a. Guns and armament manufactured between 1890 and 1919. b. Military flame throwers with an effective range less than 20 meters. c. through w. [Reserved] x. “Parts” and “components” that are “specially designed” for a commodity subject to control in paragraphs .a or .b of this ECCN or a defense article in USML Category II and not elsewhere specified on the USML or the CCL. Note 1 to 0A602.x: Engines that are “specially designed” for a self-propelled gun or howitzer subject to control under paragraph .a of this ECCN or a defense article in USML Category VII are controlled under ECCN 0A606.x. Note 2 to 0A602: “Parts,” “components,” “accessories,” and “attachments” specified in USML subcategory II(j) are subject to the controls of that paragraph. Note 3 to 0A602: Black powder guns and armament manufactured in or prior to 1890 and replicas thereof design…', '["NS1","RS1","UN?","AT1"]', '["LVS"]', 'LVS: $500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0A602.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; UN applies to entire entry -> See § 746.1 of the EAR for UN controls; AT applies to entire entry -> AT Column 1', '(1) Modern heavy weapons such as howitzers, artillery, cannon, mortars, and recoilless rifles are “subject to the ITAR.” (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” items. (3) See ECCN 0A606 for engines that are “specially designed” for a self-propelled gun or howitzer subject to control under paragraph .a of this ECCN or USML Category VII.', '15 CFR Part 774, Supplement No. 1, ECCN 0A602 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A604', '0', 'A', 'Commodities related to military explosive devices and charges', 'Commodities related to military explosive devices and charges. Items: a. Demolition blocks, and detonators designed, modified, or adapted therefor. b. Military explosive excavating devices. Note to 0A604.a and .b: This entry does not control the detonators and other items described in ECCN 1A007 or ECCN 3A232. c. Smoke hand grenades and stun hand grenades (e.g., “flashbangs”) not controlled by ECCN 1A984. d. through w. [Reserved] x. “Parts,” “components,” “accessories,” and “attachments” that are “specially designed” for a commodity subject to control in paragraphs .a through .c of this ECCN, or for a defense article controlled under USML Category IV, and not specified elsewhere on the USML. Note to 0A604.x: “Parts,” “components,” “accessories,” and “attachments” specified in USML Category IV(h) are subject to the controls of that paragraph', '["NS1","RS1","AT1","UN?"]', '[]', 'LVS: N/A | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in this ECCN 0A604.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Torpedoes, bombs, and mines are “subject to the ITAR” (see 22 CFR § 121.1, USML Category IV). (2) Smoke bombs, non-irritant smoke flares, canisters, grenades and charges, and other pyrotechnical articles having both military and commercial applications are controlled by ECCN 1A984. (3) Certain explosive detonator firing sets, electrically driven explosive detonators, and detonators and multipoint initiation systems are controlled by ECCN 1A007 or ECCN 3A232. (4) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0A604 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A606', '0', 'A', 'Ground vehicles and related commodities, as follows', 'Ground vehicles and related commodities, as follows. Items: a. Ground vehicles, whether manned or unmanned, “specially designed” for a military use and not enumerated or otherwise described in USML Category VII. Note 1 to paragraph a: For purposes of paragraph a, “ground vehicles” include (i) tanks and armored vehicles manufactured prior to 1956 that have not been modified since 1955 and that do not contain a functional weapon or a weapon capable of becoming functional through repair; (ii) military railway trains except those that are armed or are “specially designed” to launch missiles; (iii) unarmored military recovery and other support vehicles; (iv) unarmored, unarmed vehicles with mounts or hard points for firearms of .50 caliber or less; and (v) trailers “specially designed” for use with other ground vehicles enumerated in USML Category VII or ECCN 0A606.a, and not separately enum…', '["NS1?","NS2?","RS1?","RS2?","RS?","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: (1) Paragraph (c)(1) of License Exception STA (§ 740.20(c)(1) of the EAR) may not be used for any item in 0A606.a, unless determined by BIS to be eligible for License Exception STA in accordance with § 740.20(g) (License Exception STA eligibility requests for 9x515 and “600 series” items). (2) Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0A606.', 'NS applies to entire entry, except 0A606.b and .y -> NS Column 1; NS applies to 0A606.b -> NS Column 2; RS applies to entire entry, except 0A606.b and .y -> RS Column 1; RS applies to 0A606.b -> RS Column 2; RS applies to 0A606.y -> China, Russia, or Venezuela (see § 742.6(a)(7)); AT applies to entire entry -> AT Column 1; UN applies to entire entry, except 0A606.y -> See § 746.1(b) for UN controls', '(1) The ground vehicles, other articles, technical data (including software) and services described in 22 CFR part 121, Category VII are subject to the jurisdiction of the International Traffic in Arms Regulations. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0A606 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A614', '0', 'A', 'Military training “equipment,” as follows', 'Military training “equipment,” as follows. Items: a. “Equipment” “specially designed” for military training that is not enumerated or otherwise described in USML Category IX. Note 1 to 0A614: This entry includes operational flight trainers, radar target trainers, flight simulators for aircraft classified under ECCN 9A610.a, human-rated centrifuges, radar trainers for radars classified under ECCN 3A611, instrument flight trainers for military aircraft, navigation trainers for military items, target equipment, armament trainers, military pilotless aircraft trainers, mobile training units and training “equipment” for ground military operations. Note 2 to 0A614: This entry does not apply to “equipment” “specially designed” for training in the use of hunting or sporting weapons. b. through w. [Reserved] x. “Parts,” “components,” “accessories” “attachments” that are “specially designed” for a…', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2)) of the EAR may not be used for any item in 0A614.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Defense articles that are enumerated or otherwise described in USML Category IX and “technical data” (including “software”) directly related thereto are “subject to the ITAR”. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis of US-origin “600 series” items. (3) “Parts,” “components,” “accessories” and “attachments” that are common to a simulator controlled by ECCN 0A614.a and to a simulated system or an end item that is controlled on the USML or elsewhere on the CCL are controlled under the same USML Category or ECCN as the “parts,” “components,” “accessories” and “attachments” of the simulated system or end item.', '15 CFR Part 774, Supplement No. 1, ECCN 0A614 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A617', '0', 'A', 'Miscellaneous “Equipment,” Materials, and Related Commodities', 'Miscellaneous “Equipment,” Materials, and Related Commodities. Items: a. [Reserved] b. Concealment and deception equipment “specially designed” for military application, including special paints, decoys, smoke or obscuration equipment and simulators, and “parts,” “components,” “accessories,” and “attachments” “specially designed” therefor, not controlled by USML Category XIII. c. Ferries, bridges not described in ECCN 0A606 or USML Category VII, and pontoons, “specially designed” for military use. d. Test models “specially designed” for the “development” of defense articles controlled by USML Categories IV, VI, VII and VIII. e. [Reserved] f. “Metal embrittlement agents.” g. through x. [Reserved] y. Other commodities as follows, and “parts,” “components,” “accessories,” and “attachments” “specially designed” therefore: y.1. Construction equipment “specially designed” for military use, in…', '["NS1?","RS1?","RS?","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0A617.', 'NS applies to entire entry, except 0A617.y -> NS Column 1; RS applies to entire entry, except 0A617.y -> RS Column 1; RS applies to 0A617.y -> China, Russia, or Venezuela (see § 742.6(a)(7)); AT applies to entire entry -> AT Column 1; UN applies to entire entry, except 0A617.y. -> See § 764.1(b) for UN controls', '(1) Defense articles, such as materials made from classified information, that are controlled by USML Category XIII, and technical data (including software) directly related thereto, are subject to the ITAR. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content. (3) For controls on self-contained diving and underwater swimming apparatus and related commodities, see ECCN 8A620.f. (4) For controls on robots, robot controllers, and robot end-effectors, see USML Category VII and ECCNs 0A606 and 2B007. (5) “Libraries,” i.e., parametric technical databases, “specially designed” for military use with equipment controlled by the USML or a “600 series” ECCN are controlled by the technical data and technology controls pertaining to such items. (6) For controls on nuclear power generating equipment or propulsion equipment, including “nuclear reactors,” “specially designed” for military use, and “parts” and “components” “specially designed” therefor, see USML Categories VI, XIII, XV, and XX. (7) Simulators “specially designed” for military “nuclear reactors” are controlled by USML Category IX(b). (8) See USML Categories X, XI and XII for “laser” protection equipment (e.g., eye and sensor protection) “specially designed” for military use. (9) “Fuel cells” “specially designed” for a defense article on the USML or a commodity controlled by a “600 series” ECCN are controlled according to the c…', '15 CFR Part 774, Supplement No. 1, ECCN 0A617 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A919', '0', 'A', '“Military commodities” located and produced outside the United States as follows', '“Military commodities” located and produced outside the United States as follows. Items: a. “Military commodities” produced and located outside the United States that are not subject to the International Traffic in Arms Regulations (22 CFR parts 120-130) and having any of the following characteristics: a.1. Incorporate more than a de minimis amount of U.S.-origin controlled content classified under ECCNs 6A002, 6A003, or 6A993.a (having a maximum frame rate equal to or less than 9 Hz and thus meeting the criterion of Note 3.a to 6A003.b.4); a.2. Incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content (see § 734.4 of the EAR); or a.3. Are direct products of U.S.-origin “600 series” technology or software (see § 734.9(d) of the EAR). b. [Reserved]', '["RS1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'RS applies to entire entry -> RS Column 1, See § 742.6(a)(3) for license requirements.; AT applies to entire entry -> AT Column 1.', '(1) “Military commodities” are subject to the export licensing jurisdiction of the Department of State if they incorporate items that are subject to the International Traffic in Arms Regulations (ITAR) (22 CFR parts 120-130). (2) “Military commodities” described in this paragraph are subject to the export licensing jurisdiction of the Department of State if such commodities are described on the U.S. Munitions List (22 CFR part 121) and are in the United States. (3) The furnishing of assistance (including training) to foreign persons, whether in the United States or abroad, in the design, development, engineering, manufacture, production, assembly, testing, repair, maintenance, modification, operation, demilitarization, destruction, processing, or use of defense articles that are subject to the ITAR; or the furnishing to foreign persons of any technical data controlled under 22 CFR 121.1 whether in the United States or abroad are under the licensing jurisdiction of the Department of State. (4) Brokering activities (as defined in 22 CFR 129) of “military commodities” that are subject to the ITAR are under the licensing jurisdiction of the Department of State.', '15 CFR Part 774, Supplement No. 1, ECCN 0A919 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A977', '0', 'A', 'Water cannon systems for riot or crowd control, and “parts” and “components” “specially designed” therefor', 'Water cannon systems for riot or crowd control, and “parts” and “components” “specially designed” therefor', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A | STA: License Exception STA may not be used for 0A977.', 'CC applies to entire entry -> CC Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A977 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A978', '0', 'A', 'Law enforcement striking weapons, including saps, police batons, side handle batons, tonfas, sjamboks, and whips', 'Law enforcement striking weapons, including saps, police batons, side handle batons, tonfas, sjamboks, and whips', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A', 'CC applies to entire entry -> CC Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A978 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A979', '0', 'A', 'Police helmets and shields; and “specially designed” “components,” n.e.s', 'Police helmets and shields; and “specially designed” “components,” n.e.s', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A', 'CC applies to entire entry -> CC Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A979 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A980', '0', 'A', 'Horses by sea', 'Horses by sea', '["SS?"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A980 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A981', '0', 'A', 'Equipment designed for the execution of human beings as follows', 'Equipment designed for the execution of human beings as follows. Items: a. Gallows and guillotines. b. Electric chairs for the purpose of executing human beings. c. Air tight vaults designed for the execution of human beings by the administration of a lethal gas or substance. d. Automatic drug injection systems designed for the execution of human beings by administration of a lethal substance.', '["CC?"]', '[]', 'LVS: N/A | GBS: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A981 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A982', '0', 'A', 'Law enforcement restraint devices, including leg irons, shackles, and handcuffs; straight jackets; stun cuffs; shock belts; shock sleeves; multipoint restraint devices such as restraint chairs; and “specially designed” “parts,” “components” and “accessories,” n.e.s', 'Law enforcement restraint devices, including leg irons, shackles, and handcuffs; straight jackets; stun cuffs; shock belts; shock sleeves; multipoint restraint devices such as restraint chairs; and “specially designed” “parts,” “components” and “accessories,” n.e.s', '["CC?"]', '[]', 'LVS: N/A | GBS: N/A', '', 'Thumbcuffs and fingercuffs are classified under ECCN 0A983, “specially designed” implements of torture. Restraint devices that electronically monitor or report the location of confined persons for law enforcement or penal reasons are controlled under ECCN 3A981.', '15 CFR Part 774, Supplement No. 1, ECCN 0A982 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A983', '0', 'A', '“Specially designed” implements of torture, including thumbscrews, thumbcuffs, fingercuffs, spiked batons, and “specially designed” “parts,” “components” and “accessories,” n.e.s', '“Specially designed” implements of torture, including thumbscrews, thumbcuffs, fingercuffs, spiked batons, and “specially designed” “parts,” “components” and “accessories,” n.e.s', '["CC?"]', '[]', 'LVS: N/A | GBS: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A983 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A998', '0', 'A', 'Oil and gas exploration equipment, software, and data, as follows', 'Oil and gas exploration equipment, software, and data, as follows. Items: a. Oil and gas exploration data, e.g., seismic analysis data. b. Hydraulic fracturing items, as follows: b.1. Hydraulic fracturing design and analysis software and data. b.2. Hydraulic fracturing ''proppant,'' ''fracking fluid,'' and chemical additives therefor. Technical Note: A ''proppant'' is a solid material, typically treated sand or man-made ceramic materials, designed to keep an induced hydraulic fracture open, during or following a fracturing treatment. It is added to a ''fracking fluid'' which may vary in composition depending on the type of fracturing used, and can be gel, foam or slickwater-based. b.3. High pressure pumps.', '["VERIFY"]', '[]', 'LVS: N/A | GBS: N/A', 'Russian industry sector sanction applies to entire entry -> See § 746.8 for specific license requirements and license review policy.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A998 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0A999', '0', 'A', 'Specific Processing Equipment, as Follows', 'Specific Processing Equipment, as Follows. Items: a. Ring Magnets; b. Reserved.', '["AT?"]', '[]', 'LVS: N/A | GBS: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0A999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B501', '0', 'B', 'Test, inspection, and production “equipment” and related commodities for the “development” or “production” of commodities enumerated or otherwise described in ECCNs 0A501, 0A506, 0A507, or 0A509 or USML Category I as follows', 'Test, inspection, and production “equipment” and related commodities for the “development” or “production” of commodities enumerated or otherwise described in ECCNs 0A501, 0A506, 0A507, or 0A509 or USML Category I as follows. Items: a. Small arms chambering machines. b. Small arms deep hole drilling machines and drills therefor. c. Small arms rifling machines. d. Small arms boring/reaming machines. e. Production equipment (including dies, fixtures, and other tooling) “specially designed” for the “production” of the items controlled in 0A501.a through .x., 0A506, 0A507, 0A509, or USML Category I.', '["NS1?","RS1?","UN?","AT1"]', '["LVS"]', 'LVS: $3000 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used to ship any item in this entry.', 'NS applies to entire entry except equipment for ECCN 0A501.y -> NS Column 1; RS applies to entire entry except equipment for ECCN 0A501.y -> RS Column 1; UN applies to entire entry -> See § 746.1 of the EAR for UN controls; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 0B501 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B505', '0', 'B', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development” or “production” of commodities enumerated or otherwise described in ECCN 0A505 or USML Category III, except equipment for the hand loading of cartridges and shotgun shells, as follows', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development” or “production” of commodities enumerated or otherwise described in ECCN 0A505 or USML Category III, except equipment for the hand loading of cartridges and shotgun shells, as follows. Items: a. Production equipment (including tooling, templates, jigs, mandrels, molds, dies, fixtures, alignment mechanisms, and test equipment), not enumerated in USML Category III that are “specially designed” for the “production” of commodities controlled by ECCN 0A505.a or .x or USML Category III. b. Equipment “specially designed” for the “production” of commodities in ECCN 0A505.b. c. Equipment “specially designed” for the “production” of commodities in ECCN 0A505.c. d. Equipment “specially designed” for the “production” of commodities in ECCN 0A505.d. e. through .w [Reserved] x. “Parts” and…', '["NS1?","RS1?","UN?","AT1?","AT?"]', '["LVS"]', 'LVS: $3000 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0B505.', 'NS applies to paragraphs .a and .x -> NS Column 1; RS applies to paragraphs .a and .x -> RS Column 1; UN applies to entire entry -> See § 746.1 of the EAR for UN controls; AT applies to paragraphs .a, .d, and .x -> AT Column 1; AT applies to paragraph .c -> A license is required for export or reexport of these items to North Korea for anti-terrorism reasons', '', '15 CFR Part 774, Supplement No. 1, ECCN 0B505 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B521', '0', 'B', 'Any commodity subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', 'Any commodity subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0B521 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B602', '0', 'B', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development” or “production” of commodities enumerated or otherwise described in ECCN 0A602 or USML Category II as follows', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development” or “production” of commodities enumerated or otherwise described in ECCN 0A602 or USML Category II as follows. Items: a. The following commodities if “specially designed” for the “development” or “production” of commodities enumerated in ECCN 0A602.a or USML Category II: a.1. Gun barrel rifling and broaching machines and tools therefor; a.2. Gun barrel rifling machines; a.3. Gun barrel trepanning machines; a.4. Gun boring and turning machines; a.5. Gun honing machines of 6 feet (183 cm) stroke or more; a.6. Gun jump screw lathes; a.7. Gun rifling machines; and a.8. Barrel straightening presses. b. Jigs and fixtures and other metal-working implements or accessories of the kinds exclusively designed for use in the manufacture of items in ECCN 0A602 or USML Category II. c. Other…', '["NS1","RS1","UN?","AT1"]', '["LVS"]', 'LVS: $3000 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0B602.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; UN applies to entire entry -> See § 746.1 of the EAR for UN controls; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 0B602 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B604', '0', 'B', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities in ECCN 0A604 or related defense articles in USML Category IV', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities in ECCN 0A604 or related defense articles in USML Category IV. Items: a. Test, inspection, and other production “equipment” that are “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities controlled by ECCN 0A604 or for bombs, torpedoes, depth charges, mines and hand grenades, and parts, components, accessories and attachments therefor, controlled under USML Category IV. b. through w. [Reserved] x. “Parts,” “components,” “accessories,” and “attachments” that are “specially designed” for a commodity subject to control in paragraph .a of this ECCN.', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in this ECCN 0B604.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) See ECCN 9B604, which controls test, inspection, and production “equipment” and related commodities “specially designed” for the “development” or “production” of commodities in ECCN 9A604 or related defense articles in USML Category IV. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0B604 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B606', '0', 'B', 'Test, inspection, and production “equipment” and related commodities, not enumerated on the USML, “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A606 or USML Category VII', 'Test, inspection, and production “equipment” and related commodities, not enumerated on the USML, “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A606 or USML Category VII. Items: a. Test, inspection, and production “equipment” “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A606 (except for 0A606.b or 0A606.y) or in USML Category VII, and “parts,” “components,” “accessories,” and “attachments” “specially designed” therefor. Note 1: ECCN 0B606 includes (i) armor plate drilling machines, other than radial drilling machines, (ii) armor plate planing machines, (iii) armor plate quenching presses; and (iv) tank turret bearing grinding machines. b. Environmental test facilities “specially de…', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0B606.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Ground vehicles, other articles, technical data (including software) and services described in 22 CFR part 121, Category VII are subject to the jurisdiction of the International Traffic in Arms Regulations. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0B606 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B614', '0', 'B', 'Test, inspection, and production “equipment” for military training “equipment” and “specially designed” “parts,” “components,” “accessories” and “attachments” therefor, as follows', 'Test, inspection, and production “equipment” for military training “equipment” and “specially designed” “parts,” “components,” “accessories” and “attachments” therefor, as follows. Items: a. Test, inspection, and other production “equipment” “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities controlled by ECCN 0A614 or articles enumerated or otherwise described in USML Category IX. b. through .w [Reserved] x. “Parts,” “components,” “accessories” and “attachments” that are “specially designed” for a commodity controlled by ECCN 0B614.', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0B614.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', 'See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0B614 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse');
INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('0B617', '0', 'B', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A617 or USML Category XIII, and “parts,” “components,” “accessories,” and “attachments” “specially designed” therefor', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A617 or USML Category XIII, and “parts,” “components,” “accessories,” and “attachments” “specially designed” therefor. Items: a. Test, inspection, and production “equipment” not controlled by USML Category XIII(k) “specially designed” for the “production,” “development,” repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A617, (except for 0A617.y) or USML Category XIII, and “parts,” “components,” “accessories,” and “attachments” “specially designed” therefor. b. [Reserved] Note: Field engineer equipment “specially designed” for use in a combat zone, identified in the Wassenaar Arrangement Munitions List 17.d, and mobile repair shop…', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0B617.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', 'See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0B617 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0B999', '0', 'B', 'Specific Processing Equipment, as Follows', 'Specific Processing Equipment, as Follows. Items: a. Hot cells; b. Glove boxes suitable for use with radioactive materials.', '["AT?","RS?"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry. -> A license is required for items controlled by this entry to North Korea for anti-terrorism reasons. The Commerce Country Chart is not designed to determine AT license requirements for this entry. See § 742.19 of the EAR for additional information.; RS applies to entire entry. -> A license is required for items controlled by this entry for export or reexport to Iraq or transfer within Iraq for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0B999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0C521', '0', 'C', 'Any material subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', 'Any material subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0C521 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0C606', '0', 'C', 'Materials “specially designed” for commodities controlled by ECCN 0A606 not elsewhere specified in the USML', 'Materials “specially designed” for commodities controlled by ECCN 0A606 not elsewhere specified in the USML. Items: Materials “specially designed” for commodities enumerated or otherwise described in ECCN 0A606 (other than 0A606.b or 0A606.y) or USML Category VII, not elsewhere specified in the USML or the CCL. Note: Materials “specially designed” for both ground vehicles enumerated or otherwise described in USML Category VII and ground vehicles enumerated or otherwise described in ECCN 0A606 are subject to the controls of this ECCN unless identified in USML Category VII(g) as being subject to the controls of that paragraph.', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0C606.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Materials that are subject to the jurisdiction of the ITAR are described in USML Category XIII. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0C606 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0C617', '0', 'C', 'Miscellaneous Materials “Specially Designed” for Military Use', 'Miscellaneous Materials “Specially Designed” for Military Use. Items: a. Materials, coatings and treatments for signature suppression, “specially designed” for military use to reduce detectability or observability and that are not controlled by USML Category XIII or ECCNs 1C001 or 1C101. b. [Reserved]', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0C617.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) For controls on other signature suppression materials, see USML Category XIII and ECCNs 1C001 and 1C101. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0C617 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D001', '0', 'D', '“Software” “specially designed” or modified for the “development,” “production,” or “use” of commodities described in 0A002. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', '“Software” “specially designed” or modified for the “development,” “production,” or “use” of commodities described in 0A002. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', '["VERIFY"]', '[]', 'TSR: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0D001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D501', '0', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 0A501, 0A506, 0A507, 0A509 or 0B501', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 0A501, 0A506, 0A507, 0A509 or 0B501. Items: The list of items controlled is contained in this ECCN heading.', '["NS1?","RS1?","UN?","AT1"]', '[]', 'TSR: N/A License Exception STA may not be used for any “software” in ECCN 0D501, to any of the destinations listed in Country Group A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to entire entry except “software” for commodities in ECCN 0A501.y or equipment in ECCN 0B501 for commodities in ECCN 0A501.y -> NS Column 1.; RS applies to entire entry except “software” for commodities in ECCN 0A501.y or equipment in ECCN 0B501 for commodities in ECCN 0A501.y -> RS Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to entire entry -> AT Column 1.', 'See USML Category I for “software” directly related to articles described in USML Category I.', '15 CFR Part 774, Supplement No. 1, ECCN 0D501 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D505', '0', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 0A505 or 0B505', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 0A505 or 0B505. Items: The list of items controlled is contained in this ECCN heading.', '["NS1?","RS1?","UN?","AT1?"]', '[]', 'TSR: N/A License Exception STA may not be used for any “software” in ECCN 0D505, to any of the destinations listed in Country Group A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to “software” for commodities in ECCN 0A505.a and .x and equipment in ECCN 0B505.a .and .x -> NS Column 1.; RS applies to “software” for commodities in ECCN 0A505.a and .x and equipment in ECCN 0B505.a and .x -> RS Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to “software” for commodities in ECCN 0A505.a, .d, or .x and equipment in ECCN 0B505.a, .d, or .x -> AT Column 1.', 'See USML Category III for “software” directly related to articles described in USML Category III.', '15 CFR Part 774, Supplement No. 1, ECCN 0D505 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D521', '0', 'D', 'Any software subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', 'Any software subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0D521 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D602', '0', 'D', '“Software” “specially designed” for the “development,” “production,” operation or maintenance of commodities controlled by 0A602 or 0B602 as follows', '“Software” “specially designed” for the “development,” “production,” operation or maintenance of commodities controlled by 0A602 or 0B602 as follows. Items: “Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCN 0A602 and ECCN 0B602.', '["NS1","RS1","UN?","AT1"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0D602.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; UN applies to entire entry -> See § 746.1 of the EAR for UN controls; AT applies to entire entry -> AT Column 1', '(1) “Software” required for and directly related to articles enumerated in USML Category II is “subject to the ITAR”. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” items.', '15 CFR Part 774, Supplement No. 1, ECCN 0D602 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D604', '0', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCN 0A604 or 0B604', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCN 0A604 or 0B604. Items: a. “Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCN 0A604 or 0B604. b. [Reserved]', '["NS1","RS1","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in this ECCN 0D604.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) “Software” directly related to articles enumerated in USML Category IV is controlled under USML Category IV(i). (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0D604 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D606', '0', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of ground vehicles and related commodities controlled by 0A606, 0B606, or 0C606', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of ground vehicles and related commodities controlled by 0A606, 0B606, or 0C606. Items: a. “Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCNs 0A606 (except for ECCNs 0A606.b or 0A606.y), 0B606, or 0C606. b. through x. [Reserved] y. “Specific software” “specially designed” for the “production,” “development,” operation, or maintenance of commodities described in ECCN 0A606.y.', '["NS1?","RS1?","RS?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any software in 0D606.', 'NS applies to entire entry, except 0D606.y -> NS Column 1.; RS applies to entire entry, except 0D606.y -> RS Column 1.; RS applies to 0D606.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 0D606.y -> See § 746.1(b) for UN controls.', '(1) Software directly related to articles enumerated or otherwise described in USML Category VII are subject to the controls of USML paragraph VII(h). (2) See ECCN 0A919 for foreign made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0D606 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D614', '0', 'D', '“Software” related to military training “equipment,” as follows', '“Software” related to military training “equipment,” as follows. Items: a. “Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCNs 0A614 or 0B614. b. [Reserved]', '["NS1","RS1","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any “software” in 0D614.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) “Software” directly related to articles enumerated in USML Category IX is subject to the control of USML paragraph IX(e). (2) See ECCN 0A919 for foreign made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” items.', '15 CFR Part 774, Supplement No. 1, ECCN 0D614 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D617', '0', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 0A617, “equipment” controlled by 0B617, or materials controlled by 0C617', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 0A617, “equipment” controlled by 0B617, or materials controlled by 0C617. Items: a. “Software” (other than “software” controlled in paragraph .y of this entry) “specially designed” for the “development,” “production,” operation or maintenance of commodities controlled by ECCNs 0A617 (except 0A617.y), 0B617, or 0C617. b. to x. [Reserved]. y. Specific “software” “specially designed” for the “production,” “development,” operation or maintenance of commodities controlled by ECCN 0A617.y.', '["NS1?","RS1?","RS?","AT1","UN?"]', '[]', 'TSR: N/A', 'NS applies to entire entry, except 0D617.y -> NS Column 1.; RS applies to entire entry, except 0D617.y -> RS Column 1.; RS applies to 0D617.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 0D617.y -> See § 746.1(b) for UN controls.', '(1) “Software” directly related to articles controlled by USML Category XIII is subject to the control of USML paragraph XIII(l). (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 0D617 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D977', '0', 'D', '“Software” “specially designed” for the “development,” “production” or “use” of commodities controlled by 0A977', '“Software” “specially designed” for the “development,” “production” or “use” of commodities controlled by 0A977', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A | STA: License Exception STA may not be used for 0D977.', 'CC applies to entire entry -> CC Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0D977 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0D999', '0', 'D', 'Specific Software, as Follows', 'Specific Software, as Follows. Items: a. Software for neutronic calculations/modeling; b. Software for radiation transport calculations/modeling; c. Software for hydrodynamic calculations/modeling.', '["AT?","RS?"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> A license is required for items controlled by this entry to North Korea for anti-terrorism reasons. The Commerce Country Chart is not designed to determine AT license requirements for this entry. See § 742.19 of the EAR for additional information.; RS applies to entire entry. -> A license is required for items controlled by this entry for export or reexport to Iraq or transfer within Iraq for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0D999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E001', '0', 'E', '“Technology,” according to the Nuclear Technology Note, for the “development,” “production,” or “use” of items described in 0A002, or 0D001', '“Technology,” according to the Nuclear Technology Note, for the “development,” “production,” or “use” of items described in 0A002, or 0D001', '["VERIFY"]', '[]', 'TSR: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0E001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E501', '0', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, or overhaul of commodities controlled by 0A501, 0A506, 0A507, 0A509, or 0B501 as follows', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, or overhaul of commodities controlled by 0A501, 0A506, 0A507, 0A509, or 0B501 as follows. Items: a. “Technology” “required” for the “development” or “production” of commodities controlled by ECCN 0A501 (other than 0A501.y), 0A506, 0A507, 0A509, or 0B501. b. “Technology” “required” for the operation, installation, maintenance, repair, or overhaul of commodities controlled by ECCN 0A501 (other than 0A501.y), 0A506, 0A507, 0A509, or 0B501.', '["NS1","RS1","UN?","AT1"]', '[]', 'TSR: N/A License Exception STA may not be used for any “technology” in ECCN 0E501, to any of the destinations listed in Country Group A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 1.; RS applies to entire entry -> RS Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; AT applies to entire entry -> AT Column 1.', 'See USML Category I for technical data directly related to articles described in USML Category I.', '15 CFR Part 774, Supplement No. 1, ECCN 0E501 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E502', '0', 'E', '“Technology” “required” for the “development” or “production” of commodities controlled by 0A502, 0A508, or 0A509.a or .d', '“Technology” “required” for the “development” or “production” of commodities controlled by 0A502, 0A508, or 0A509.a or .d', '["CC1","UN?"]', '[]', 'TSR: N/A', 'CC applies to entire entry -> CC Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.', 'See USML Category I for technical data directly related to articles described in USML Category I.', '15 CFR Part 774, Supplement No. 1, ECCN 0E502 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E504', '0', 'E', '“Technology” “required” for the “development” or “production” of commodities controlled by 0A504 that incorporate a focal plane array or image intensifier tube', '“Technology” “required” for the “development” or “production” of commodities controlled by 0A504 that incorporate a focal plane array or image intensifier tube', '["RS1","UN?","AT1"]', '[]', 'TSR: N/A License Exception STA may not be used for “technology” in ECCN 0E504, to any of the destinations listed in Country Group A:5 or A:6 (See supplement no.1 to part 740 of the EAR).', 'RS applies to entire entry -> RS Column 1.; UN applies to entire entry -> See § 746.1(b) of the EAR for UN controls.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0E504 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E505', '0', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by 0A505', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by 0A505. Items: The list of items controlled is contained in this ECCN heading.', '["NS1?","RS1?","UN?","CC1?","AT1?"]', '[]', 'TSR: N/A License Exception STA may not be used for any “technology” in ECCN 0E505, to any of the destinations listed in Country Group A:6 (See supplement no.1 to part 740 of the EAR).', 'NS applies to “technology” for “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing commodities in 0A505.a and .x; for “equipment” for those commodities in 0B505; and for “software” for that “equipment” and those commodities in 0D505 -> NS Column 1.; RS applies to “technology” for “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing commodities in 0A505.a and .x; for “equipment” for those commodities in 0B505 and for “software” for those commodities and that equipment in 0D505 -> RS Column 1.; UN applies to entire entry -> See § 746.1 of the EAR for UN controls.; CC applies to “technology” for the “development” or “production” of commodities in 0A505.b -> CC Column 1.; AT applies to “technology” for “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing commodities in 0A505.a, .d, and .x -> AT Column 1.', 'See USML Category III for technical data directly related to articles described in USML Category III.', '15 CFR Part 774, Supplement No. 1, ECCN 0E505 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E521', '0', 'E', 'Any technology subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', 'Any technology subject to the EAR that is not listed elsewhere in the CCL, but which is controlled for export because it provides at least a significant military or intelligence advantage to the United States or for foreign policy reasons', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 0E521 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E602', '0', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by 0A602 or 0B602, or “software” controlled by 0D602 as follows', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by 0A602 or 0B602, or “software” controlled by 0D602 as follows. Items: “Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, or overhaul of commodities controlled by ECCN 0A602 or 0B602, or “software” controlled by ECCN 0D602.', '["NS1","RS1","UN?","AT1"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 0E602.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; UN applies to entire entry -> See § 746.1 of the EAR for UN controls; AT applies to entire entry -> AT Column 1', 'Technical data directly related to articles enumerated in USML Category II are “subject to the ITAR.”', '15 CFR Part 774, Supplement No. 1, ECCN 0E602 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E604', '0', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by ECCN 0A604 or 0B604, or “software” controlled by ECCN 0D604', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by ECCN 0A604 or 0B604, or “software” controlled by ECCN 0D604. Items: a. “Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by ECCN 0A604 or 0B604, or “software” controlled by ECCN 0D604. b. [Reserved]', '["NS1","RS1","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in this ECCN 0E604.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', 'Technical data directly related to articles enumerated in USML Category IV are controlled under USML Category IV(i).', '15 CFR Part 774, Supplement No. 1, ECCN 0E604 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E606', '0', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbushing of ground vehicles and related commodities in 0A606, 0B606, 0C606, or software in 0D606', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbushing of ground vehicles and related commodities in 0A606, 0B606, 0C606, or software in 0D606. Items: a. “Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities enumerated or otherwise described in ECCN 0A606 (except for ECCNs 0A606.b or 0A606.y), 0B606, or 0C606. b. through x. [Reserved] y. Specific “technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul or refurbishing of commodities or software in ECCN 0A606.y or 0D606.y.', '["NS1?","RS1?","RS?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any technology in 0D606.', 'NS applies to entire entry, except 0E606.y -> NS Column 1.; RS applies to entire entry, except 0E606.y -> RS Column 1.; RS applies to 0E606.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 0E606.y -> See § 746.1(b) for UN controls.', 'Technical data directly related to articles enumerated in USML Category VII are subject to the controls of USML paragraph VII(h).', '15 CFR Part 774, Supplement No. 1, ECCN 0E606 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E614', '0', 'E', '“Technology,” as follows', '“Technology,” as follows. Items: a. “Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities or “software” controlled by ECCNs 0A614, 0B614, or 0D614. b. [Reserved]', '["NS1","RS1","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any technology in 0E614.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '“Technical data” directly related to articles enumerated in USML Category IX is subject to the control of USML paragraph IX(e).', '15 CFR Part 774, Supplement No. 1, ECCN 0E614 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E617', '0', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by ECCN 0A617, “equipment” controlled by 0B617, or materials controlled by 0C617, or “software” controlled by ECCN 0D617', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by ECCN 0A617, “equipment” controlled by 0B617, or materials controlled by 0C617, or “software” controlled by ECCN 0D617. Items: a. “Technology” (other than “technology” controlled by paragraph .y of this entry) “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities or “software” controlled by ECCN 0A617 (except 0A617.y), 0B617, 0C617, or 0D617 (except 0D617.y). b. through x. [Reserved]. y. Specific “technology” “required” for the “production,” “development,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by ECCN 0A617.y or “software” controlled by 0D617.y.', '["NS1?","RS1?","RS?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any technology in 0E617.', 'NS applies to entire entry, except 0E617.y -> NS Column 1.; RS applies to entire entry, except 0E617.y -> RS Column 1.; RS applies to 0E617.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 0E617.y -> See § 746.1(b) for UN controls.', 'Technical data directly related to articles controlled by USML Category XIII are subject to the control of USML paragraph XIII(l).', '15 CFR Part 774, Supplement No. 1, ECCN 0E617 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E977', '0', 'E', '“Technology” “required” for the “development” or “production” of commodities controlled by 0A977', '“Technology” “required” for the “development” or “production” of commodities controlled by 0A977', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A | STA: License Exception STA may not be used for 0E977.', 'CC applies to entire entry -> CC Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 0E977 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('0E982', '0', 'E', '“Technology” exclusively for the “development” or “production” of equipment controlled by 0A982 or 0A503', '“Technology” exclusively for the “development” or “production” of equipment controlled by 0A982 or 0A503', '["CC?"]', '[]', 'TSR: N/A', 'CC applies to “technology” for items controlled by 0A982 or 0A503. A license is required for ALL destinations, except Canada, regardless of end use. Accordingly, a column specific to this control does not appear on the Commerce Country Chart. (See part 742 of the EAR for additional information.)', '', '15 CFR Part 774, Supplement No. 1, ECCN 0E982 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A001', '1', 'A', '“Parts” and “components” made from fluorinated compounds, as follows', '“Parts” and “components” made from fluorinated compounds, as follows. Items: a. Seals, gaskets, sealants or fuel bladders, “specially designed” for “aircraft” or aerospace use, made from more than 50% by weight of any of the materials controlled by 1C009.b or 1C009.c; b. [Reserved]', '["NS2","AT1"]', '["LVS"]', 'LVS: $5000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', '(1) Items “specially designed” or modified for missiles or for items on the U.S. Munitions List are “subject to the ITAR” (see 22 CFR parts 120 through 130, including USML Category XXI).', '15 CFR Part 774, Supplement No. 1, ECCN 1A001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A002', '1', 'A', '“Composite” structures or laminates, as follows', '“Composite” structures or laminates, as follows. Items: a. Made from any of the following: a.1. An organic “matrix” and “fibrous or filamentary materials” specified by 1C010.c or 1C010.d; or a.2. Prepregs or preforms specified by 1C010.e; b. Made from a metal or carbon “matrix”, and any of the following: b.1. Carbon “fibrous or filamentary materials” having all of the following: b.1.a. A “specific modulus” exceeding 10.15 x 10 6 m; and b.1.b. A “specific tensile strength” exceeding 17.7 x 10 4 m; or b.2. Materials controlled by 1C010.c. Note 1: 1A002 does not control “composite” structures or laminates made from epoxy resin impregnated carbon “fibrous or filamentary materials”, for the repair of “civil aircraft” structures or laminates, having all of the following: a. An area not exceeding 1 m 2; b. A length not exceeding 2.5 m; and c. A width exceeding 15 mm. Note 2: 1A002 does not con…', '["NS2","NP1?","AT1"]', '["LVS"]', 'LVS: $1,500; N/A for NP; N/A for “composite” structures or laminates controlled by 1A002.a, having an organic “matrix” and made from materials controlled by 1C010.c or 1C010.d. | GBS: N/A | STA: License Exception STA may not be used to ship any item in this entry to any of the destinations listed in Country Group A:6 (See Supplement No. 1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 2; NP applies to 1A002.b.1 in the form of tubes with an inside diameter between 75 mm and 400 mm -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Also see ECCNs 1A202, 1C010, 1C210, 9A010, and 9A110. (3) “Composite” structures “specially designed” for missile applications (including “specially designed” subsystems, “parts,” and “components”) are controlled by ECCN 9A110. (4) “Composite” structures or laminates “specially designed” or prepared for use in separating uranium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1A002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A003', '1', 'A', 'Manufactures of non-“fusible” aromatic polyimides in film, sheet, tape or ribbon form having any of the following', 'Manufactures of non-“fusible” aromatic polyimides in film, sheet, tape or ribbon form having any of the following. Items: a. A thickness exceeding 0.254 mm; or b. Coated or laminated with carbon, graphite, metals or magnetic substances.', '["NS2","AT1"]', '["LVS"]', 'LVS: $200 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'This entry does not control manufactures when coated or laminated with copper and designed for the production of electronic printed circuit boards. For “fusible” aromatic polyimides in any form, see 1C008.a.3.', '15 CFR Part 774, Supplement No. 1, ECCN 1A003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A004', '1', 'A', 'Protective and detection equipment and “components”, not “specially designed” for military use, as follows', 'Protective and detection equipment and “components”, not “specially designed” for military use, as follows. Items: a. Full face masks, filter canisters and decontamination equipment therefor, designed or modified for defense against any of the following, and “specially designed” “components” therefor: Note: 1A004.a includes Powered Air Purifying Respirators (PAPR) that are designed or modified for defense against agents or materials, listed in 1A004.a. Technical Notes: For the purposes of 1A004.a: 1. Full face masks are also known as gas masks. 2. Filter canisters include filter cartridges. a.1. ''Biological agents''; a.2. ''Radioactive materials''; a.3. Chemical warfare (CW) agents; or a.4. ''Riot control agents'', as follows: a.4.a. α-Bromobenzeneacetonitrile, (Bromobenzyl cyanide) (CA) (CAS 5798-79-8); a.4.b. [(2-chlorophenyl) methylene] propanedinitrile, (o-Chlorobenzylidenemalononitrile)…', '["NS2","CB2?","RS2?","AT1"]', '["GBS"]', 'LVS: N/A | GBS: Yes for 1A004.a, .b, and .c.2.', 'NS applies to entire entry -> NS Column 2; CB applies to chemical detection systems and dedicated detectors therefor, in 1A004.c, that also have the technical characteristic -> CB Column 2; RS apply to 1A004.d -> RS Column 2; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1A995, 2B351, and 2B352. (2) See ECCN 1D003 for “software” “specially designed” or modified to enable equipment to perform the functions of equipment controlled under section 1A004.c (Nuclear, biological, and chemical (NBC) detection systems). (3) See ECCN 1E002.g for control libraries (parametric technical databases) “specially designed” or modified to enable equipment to perform the functions of equipment controlled under 1A004.c (Nuclear, biological, and chemical (NBC) detection systems). (4) Chemical and biological protective and detection equipment specifically designed, developed, modified, configured, or adapted for military applications is “subject to the ITAR” (see 22 CFR parts 120 through 130, including USML Category XIV(f)), as is commercial equipment that incorporates “parts” or “components” controlled under that category except for domestic preparedness devices for individual protection that integrate “components” and “parts” identified in USML Category XIV(f)(4) when such “parts” or “components” are: Integral to the device; inseparable from the device; and incapable of replacement without compromising the effectiveness of the device, in which case the equipment is subject to the export licensing jurisdiction of the Department of Commerce under ECCN 1A004. (5) This entry does not control radionuclides incorporated in equipment listed in this entry—such materials are subject to the licensing jurisdiction of the Nuclear Regulatory Commission (See 10…', '15 CFR Part 774, Supplement No. 1, ECCN 1A004 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A005', '1', 'A', 'Body armor and “specially designed” “components” therefor, as follows', 'Body armor and “specially designed” “components” therefor, as follows. Items: a. Soft body armor not manufactured to military standards or specifications, or to their equivalents, and “specially designed” “components” therefor; b. Hard body armor plates that provide ballistic protection less than NIJ level III (NIJ 0101.06, July 2008) or “equivalent standards”. Notes to ECCN 1A005: 1. This entry does not control body armor when accompanying its user for the user''s own personal protection. 2. This entry does not control body armor designed to provide frontal protection only from both fragment and blast from non-military explosive devices. 3. This entry does not apply to body armor designed to provide protection only from knife, spike, needle or blunt trauma.', '["NS2","UN?","AT1"]', '["GBS"]', 'LVS: N/A | GBS: Yes, except UN', 'NS applies to entire entry -> NS Column 2; UN applies to entire entry -> See § 746.1(b) for UN controls; AT applies to entire entry -> AT Column 1', '(1) Bulletproof and bullet resistant vests (body armor) providing NIJ Type IV protection or greater are “subject to the ITAR” (see 22 CFR 121.1 Category X(a)). (2) Soft body armor and protective garments manufactured to military standards or specifications that provide protection equal to or less than NIJ level III or “equivalent standards” are classified under ECCN 1A613.d.1. (3) Hard armor plates providing NIJ level III or “equivalent standard” ballistic protection are classified under ECCN 1A613.d.2. (4) Police helmets and shields are classified under ECCN 0A979. (5) Other personal protective “equipment” “specially designed” for military applications not controlled by the USML or elsewhere in the CCL is classified under ECCN 1A613.e. (6) For “fibrous or filamentary materials” used in the manufacture of body armor, see ECCN 1C010.', '15 CFR Part 774, Supplement No. 1, ECCN 1A005 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A006', '1', 'A', 'Equipment, “specially designed” or modified for the disposal of Improvised Explosive Devices (IEDs), as follows , and “specially designed” “components” and “accessories” therefor', 'Equipment, “specially designed” or modified for the disposal of Improvised Explosive Devices (IEDs), as follows , and “specially designed” “components” and “accessories” therefor. Items: a. Remotely operated vehicles; b. ''Disruptors''. Technical Note: For the purposes of 1A006.b ''disruptors'' are devices “specially designed” for the purpose of preventing the operation of an explosive device by projecting a liquid, solid or frangible projectile. Note: 1A006 does not apply to equipment when accompanying its operator.', '["NS2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'Equipment “specially designed” for military use for the disposal of IEDs is “subject to the ITAR” (see 22 CFR parts 120 through 130, including USML Category IV).', '15 CFR Part 774, Supplement No. 1, ECCN 1A006 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A007', '1', 'A', 'Equipment and devices, “specially designed” to initiate charges and devices containing “energetic materials,” by electrical means, as follows', 'Equipment and devices, “specially designed” to initiate charges and devices containing “energetic materials,” by electrical means, as follows. Items: a. Explosive detonator firing sets designed to drive explosive detonators specified by 1A007.b; b. Electrically driven explosive detonators as follows: b.1. Exploding bridge (EB); b.2. Exploding bridge wire (EBW); b.3. Slapper; b.4. Exploding foil initiators (EFI). Technical Notes: 1. The word initiator or igniter is sometimes used in place of the word detonator. 2. For the purposes of 1A007.b, the detonators of concern all utilize a small electrical conductor (bridge, bridge wire, or foil) that explosively vaporizes when a fast, high-current electrical pulse is passed through it. In non slapper types, the exploding conductor starts a chemical detonation in a contacting high explosive material such as PETN (pentaerythritoltetranitrate). In…', '["NS2","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; NP applies to 1A007.b, as well as 1A007.a when the detonator firing set meets or exceeds the parameters of 3A229 -> NP Column 1; AT applies to entire entry -> AT Column 1', 'High explosives and related equipment “specially designed” for military use are “subject to the ITAR” (see 22 CFR parts 120 through 130). This entry does not control detonators using only primary explosives, such as lead azide. See also ECCNs 0A604, 3A229, and 3A232. See 1E001 for “development” and “production” technology controls, and 1E201 for “use” technology controls.', '15 CFR Part 774, Supplement No. 1, ECCN 1A007 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A008', '1', 'A', 'Charges, devices and “components”, as follows', 'Charges, devices and “components”, as follows. Items: a. ''Shaped charges'' having all of the following: a.1. Net Explosive Quantity (NEQ) greater than 90 g; and a.2. Outer casing diameter equal to or greater than 75 mm; b. Linear shaped cutting charges having all of the following, and “specially designed” “components” therefor: b.1. An explosive load greater than 40 g/m; and b.2. A width of 10 mm or more; c. Detonating cord with explosive core load greater than 64 g/m; d. Cutters, not specified by 1A008.b, and severing tools, having a NEQ greater than 3.5 kg. Technical Note: For the purposes of 1A008.a, ''shaped charges'' are explosive charges shaped to focus the effects of the explosive blast. Note: The only charges and devices specified in 1A008 are those containing “explosives” (see list of explosives in the Annex at the end of Category 1) and mixtures thereof.', '["NS2","AT1","UN?"]', '["LVS"]', 'LVS: $3,000 for .a through .c; $6,000 for .d. | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls.', '(1) All of the following are “subject to the ITAR” (see 22 CFR parts 120 through 130):', '15 CFR Part 774, Supplement No. 1, ECCN 1A008 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A101', '1', 'A', 'Devices for reduced observables such as radar reflectivity, ultraviolet/infrared signatures and acoustic signatures, for applications usable in rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km or their complete subsystems', 'Devices for reduced observables such as radar reflectivity, ultraviolet/infrared signatures and acoustic signatures, for applications usable in rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km or their complete subsystems', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) See also 1C101. (2) For commodities that meet the definition of defense articles under 22 CFR 120.3 of the International Traffic in Arms Regulations (ITAR), describes similar commodities “subject to the ITAR” (See 22 CFR parts 120 through 130, including USML Category XIII).', '15 CFR Part 774, Supplement No. 1, ECCN 1A101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A102', '1', 'A', 'Resaturated pyrolized carbon-carbon “parts” and “components” designed for rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', 'Resaturated pyrolized carbon-carbon “parts” and “components” designed for rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1A102 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A202', '1', 'A', 'Composite structures, other than those controlled by 1A002, in the form of tubes and having both of the following characteristics', 'Composite structures, other than those controlled by 1A002, in the form of tubes and having both of the following characteristics. Items: a. An inside diameter of between 75 mm and 400 mm; and b. Made with any of the “fibrous or filamentary materials” specified in 1C010.a or .b or 1C210.a or with carbon prepreg materials specified in 1C210.c.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E201 (“use”) and 1E202 (“development” and “production”) for technology for items controlled by this entry. (2) Also see ECCNs 1A002, 1C010, 1C210, 9A010, and 9A110. (3) “Composite” structures “specially designed” or prepared for use in separating uranium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1A202 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A225', '1', 'A', 'Platinized catalysts “specially designed” or prepared for promoting the hydrogen isotope exchange reaction between hydrogen and water for the recovery of tritium from heavy water or for the production of heavy water', 'Platinized catalysts “specially designed” or prepared for promoting the hydrogen isotope exchange reaction between hydrogen and water for the recovery of tritium from heavy water or for the production of heavy water', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E201 (“use”) and 1E202 (“development” and “production”) for technology for items controlled by this entry. (2) Equipment “specially designed” or prepared for the production of heavy water is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1A225 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A226', '1', 'A', 'Specialized packings, which may be used in separating heavy water from ordinary water, having both of the following characteristics', 'Specialized packings, which may be used in separating heavy water from ordinary water, having both of the following characteristics. Items: a. Made of phosphor bronze mesh chemically treated to improve wettability; and b. Designed to be used in vacuum distillation towers.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E201 (“use”) and 1E202 (“development” and “production”) for technology for items controlled by this entry. (2) Equipment “specially designed” or prepared for the production of heavy water is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1A226 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A227', '1', 'A', 'High-density (lead glass or other) radiation shielding windows, having all of the following characteristics , and “specially designed” frames therefor', 'High-density (lead glass or other) radiation shielding windows, having all of the following characteristics , and “specially designed” frames therefor. Items: a. A “cold area” greater than 0.09 m 2; b. A density greater than 3 g/cm 3; and c. A thickness of 100 mm or greater.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E201 (“use”) and 1E202 (“development” and “production”) for technology for items controlled by this entry. (2) Equipment “specially designed” or prepared for nuclear reactors and reprocessing facilities is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1A227 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A231', '1', 'A', 'Target assemblies and components for the production of tritium as follows ', 'Target assemblies and components for the production of tritium as follows . Items: a. Target assemblies made of or containing lithium enriched in the lithium-6 isotope “specially designed” for the “production” of tritium through irradiation, including insertion in a nuclear reactor; b. Components “specially designed” for the target assemblies specified in item a. Technical Note to ECCN 1A231.b.: Components “specially designed” for target assemblies for the “production” of tritium may include lithium pellets, tritium getters, and specially-coated cladding.', '["NP1?","AT1?"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry AT applies to entire entry -> NP Column 1 AT Column 1', 'See ECCNs 1E001 (“production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1A231 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse');
INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('1A290', '1', 'A', 'Depleted uranium (any uranium containing less than 0.711% of the isotope U-235) in shipments of more than 1,000 kilograms in the form of shielding contained in X-ray units, radiographic exposure or teletherapy devices, radioactive thermoelectric generators, or packaging for the transportation of radioactive materials', 'Depleted uranium (any uranium containing less than 0.711% of the isotope U-235) in shipments of more than 1,000 kilograms in the form of shielding contained in X-ray units, radiographic exposure or teletherapy devices, radioactive thermoelectric generators, or packaging for the transportation of radioactive materials', '["NP2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 2; AT applies to entire entry -> AT Column 1', '(1) This entry does not control depleted uranium in fabricated forms for use in munitions. See 22 CFR part 121 for depleted uranium “subject to the ITAR. (2) Depleted uranium that is not fabricated for use in munitions or fabricated into commodities solely to take advantage of its high density (e.g., aircraft, ship, or other counterweights) or in the forms listed in this entry are subject to the export licensing authority of the Nuclear Regulatory Commission. (See 10 CFR part 110.) (3) “Natural uranium” or “depleted uranium” or thorium in the form of metal, alloy, chemical compound or concentrate and any other material containing one or more of the foregoing are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1A290 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A607', '1', 'A', 'Military dissemination “equipment” for riot control agents, military detection and protection “equipment” for toxicological agents (including chemical, biological, and riot control agents), and related commodities', 'Military dissemination “equipment” for riot control agents, military detection and protection “equipment” for toxicological agents (including chemical, biological, and riot control agents), and related commodities. Items: a. through d. [Reserved] e. “Equipment” “specially designed” for military use and for the dissemination of any of the riot control agents controlled in ECCN 1C607.a. f. Protection “equipment” (including air conditioning units, protective coatings, and protective clothing): f.1. Not controlled by USML Category XIV(f); and f.2. “Specially designed” for military use and for defense against: f.2.1. Materials specified by USML Category XIV (a) or (b); or f.2.2. Riot control agents controlled in 1C607.a. g. Decontamination “equipment”: g.1. Not controlled by USML Category XIV(f); and g.2. “Specially designed” for military use and for decontamination of objects contaminated w…', '["NS1","RS1","AT1","UN?"]', '[]', 'LVS: N/A | GBS: N/A Special Conditions for STA | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1A607.', 'NS applies to entire entry -> NS Column 1.; RS applies to entire entry -> RS Column 1.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', '(1) Vaccines identified in ECCN 1C991 are not controlled by this ECCN. (2) See 22 CFR 121.1 (USML), Category XIV(h), for vaccines that are subject to the ITAR. (3) Protection and detection equipment and related items identified in ECCN 1A004, 1A995, or 2B351 are not controlled by this ECCN. (4) See 22 CFR 121.1 (USML), Category XIV(f), for dissemination, detection and protection equipment that is subject to the ITAR. (5) See ECCN 0A919 for “military commodities” located and produced outside the United States that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1A607 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A613', '1', 'A', 'Armored and protective “equipment” and related commodities, as follows', 'Armored and protective “equipment” and related commodities, as follows. Items: a. Metallic or non-metallic armored plate “specially designed” for military use and not controlled by the USML. Note to paragraph a: For controls on body armor plates, see ECCN 1A613.d.2 and USML Category X(a)(1). b. Shelters “specially designed” to: b.1. Provide ballistic protection for military systems; or b.2. Protect against nuclear, biological, or chemical contamination. c. Military helmets (other than helmets controlled under 1A613.y.1) providing less than NIJ Type IV or “equivalent standards” protection. Note 1: See ECCN 0A979 for controls on police helmets. Note 2: See USML Category X(a)(5) and (a)(6) for controls on other military helmets. Note 3: 1A613.c does not apply to helmets that meet all the following: a. Were first manufactured before 1970; and b. Are neither designed or modified to accept, n…', '["NS1?","RS1?","RS?","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1A613.', 'NS applies to entire entry except 1A613.y -> NS Column 1.; RS applies to entire entry except 1A613.y -> RS Column 1.; RS applies 1A613.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 1A613.y -> See § 746.1(b) for UN controls.', '(1) Defense articles, such as materials made from classified information, that are controlled by USML Category X or XIII of the ITAR, and technical data (including software) directly related thereto, are “subject to the ITAR.” (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content. (3) See ECCN 9A610.g for anti-gravity suits (“G-suits”) and pressure suits capable of operating at altitudes higher than 55,000 feet above sea level. (4) For other military helmet “components” or “accessories” not specified in 1A613.c, see the relevant ECCN in the CCL or USML Entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1A613 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A984', '1', 'A', 'Chemical agents, including tear gas formulation containing 1 percent or less of orthochlorobenzalmalononitrile (CS), or 1 percent or less of chloroacetophenone (CN), except in individual containers with a net weight of 20 grams or less; liquid pepper except when packaged in individual containers with a net weight of 3 ounces (85.05 grams) or less; smoke bombs; non-irritant smoke flares, canisters, grenades and charges; and other pyrotechnic articles having dual military and commercial use, and “parts” and “components” “specially designed” therefor, n.e.s', 'Chemical agents, including tear gas formulation containing 1 percent or less of orthochlorobenzalmalononitrile (CS), or 1 percent or less of chloroacetophenone (CN), except in individual containers with a net weight of 20 grams or less; liquid pepper except when packaged in individual containers with a net weight of 3 ounces (85.05 grams) or less; smoke bombs; non-irritant smoke flares, canisters, grenades and charges; and other pyrotechnic articles having dual military and commercial use, and “parts” and “components” “specially designed” therefor, n.e.s', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A', 'CC applies to entire entry -> CC Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1A984 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A985', '1', 'A', 'Fingerprinting powders, dyes, and inks', 'Fingerprinting powders, dyes, and inks', '["CC1"]', '[]', 'LVS: N/A | GBS: N/A', 'CC applies to entire entry -> CC Column 1', 'See 3A981.', '15 CFR Part 774, Supplement No. 1, ECCN 1A985 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A995', '1', 'A', 'Protective and detection equipment not “specially designed” for military use and not controlled by ECCN 1A004 or ECCN 2B351, as follows , and “parts” and “components” not “specially designed” for military use and not controlled by ECCN 1A004 or ECCN 2B351 therefor', 'Protective and detection equipment not “specially designed” for military use and not controlled by ECCN 1A004 or ECCN 2B351, as follows , and “parts” and “components” not “specially designed” for military use and not controlled by ECCN 1A004 or ECCN 2B351 therefor. Items: a. Personal radiation monitoring dosimeters; b. Equipment limited by design or function to protect against hazards specific to civil industries, such as mining, quarrying, agriculture, pharmaceuticals, medical, veterinary, environmental, waste management, or to the food industry. Note: This entry (1A995) does not control items for protection against chemical or biological agents that are consumer goods, packaged for retail sale or personal use, or medical products, such as latex exam gloves, latex surgical gloves, liquid disinfectant soap, disposable surgical drapes, surgical gowns, surgical foot covers, and surgical m…', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', 'See ECCNs 1A004, 2B351, and 2B352.', '15 CFR Part 774, Supplement No. 1, ECCN 1A995 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1A999', '1', 'A', 'Specific Processing Equipment, n.e.s., as Follows', 'Specific Processing Equipment, n.e.s., as Follows. Items: a. Radiation detection, monitoring and measurement equipment, n.e.s.; b. Radiographic detection equipment such as x-ray converters, and storage phosphor image plates.', '["AT?"]', '[]', 'LVS: N/A | GBS: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1A999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B001', '1', 'B', 'Equipment for the production or inspection of “composite” structures or laminates controlled by 1A002 or “fibrous or filamentary materials” controlled by 1C010, as follows , and “specially designed” “components” and “accessories” therefor', 'Equipment for the production or inspection of “composite” structures or laminates controlled by 1A002 or “fibrous or filamentary materials” controlled by 1C010, as follows , and “specially designed” “components” and “accessories” therefor. Items: a. Filament winding machines, of which the motions for positioning, wrapping and winding fibers are coordinated and programmed in three or more ''primary servo positioning'' axes, “specially designed” for the manufacture of “composite” structures or laminates, from “fibrous or filamentary materials”; b. ''Tape laying machines'', of which the motions for positioning and laying tape are coordinated and programmed in five or more ''primary servo positioning'' axes, “specially designed” for the manufacture of “composite” airframe or missile structures; Technical Note: For the purposes of 1B001.b, ''tape-laying machines'' have the ability to lay one or more…', '["NS2","MT1?","NP1?","AT1"]', '[]', 'LVS: N/A for MT and for 1B001.a; $5000 for all other items | GBS: N/A', 'NS applies to entire entry -> NS Column 2; MT applies to entire entry, except 1B001.d.4, e and f. Note: MT applies to equipment in 1B001.d that meet or exceed the parameters of 1B101 -> MT Column 1; NP applies to filament winding machines described in 1B001.a that are capable of winding cylindrical rotors having a diameter between 75 mm (3 in) and 400 mm (16 in) and lengths of 600 mm (24 in) or greater; AND coordinating and programming controls and precision mandrels for these filament winding machines -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 1D001 for software for items controlled by this entry and see ECCNs 1E001 (“development” and “production”) and 1E101 (“use”) for technology for items controlled by this entry. (2) Also see ECCNs 1B101 and 1B201.', '15 CFR Part 774, Supplement No. 1, ECCN 1B001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B002', '1', 'B', 'Equipment designed to produce metal alloy powder or particulate materials and having any of the following', 'Equipment designed to produce metal alloy powder or particulate materials and having any of the following. Items: a. “Specially designed” to avoid contamination; and b. “Specially designed” for use in one of the processes specified by 1C002.c.2.', '["NS2","AT1"]', '["LVS"]', 'LVS: $5000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1B002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B003', '1', 'B', 'Tools, dies, molds or fixtures, for “superplastic forming” or “diffusion bonding” titanium, aluminum or their alloys, “specially designed” for the manufacture of any of the following', 'Tools, dies, molds or fixtures, for “superplastic forming” or “diffusion bonding” titanium, aluminum or their alloys, “specially designed” for the manufacture of any of the following. Items: a. Airframe or aerospace structures; b. “Aircraft” or aerospace engines; or c. “Specially designed” “parts” and “components” for structures specified by 1B003.a or for engines specified by 1B003.b.', '["NS2","AT1"]', '["LVS"]', 'LVS: $5000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'For “specially designed”“production equipment”of systems, sub-systems, and “parts” and “components” controlled by 9A005 to 9A009, 9A011, 9A101, 9A105 to 9A109, 9A111, and 9A116 to 9A120 usable in “missiles,” see 9B115.', '15 CFR Part 774, Supplement No. 1, ECCN 1B003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B018', '1', 'B', 'Items on the Wassenaar Arrangement Munitions List', 'Items on the Wassenaar Arrangement Munitions List. Items: a. [Reserved] b. [Reserved]', '["NS1","MT1?","RS2?","AT1","UN?"]', '["LVS"]', 'LVS: $3000 for 1B018.a for countries WITHOUT an “X” in RS Column 2 on the Country Chart contained in Supplement No. 1 to part 738 of the EAR; $5000 for 1B018.b. | GBS: N/A', 'NS applies to entire entry -> NS Column 1.; MT applies to equipment for the “production” of rocket propellants -> MT Column 1.; RS applies to 1B018.a -> RS Column 2.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', 'See ECCN 1B608.a, .b, and .x for items that, immediately prior to July 1, 2014, were classified under 1B018.a.', '15 CFR Part 774, Supplement No. 1, ECCN 1B018 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B101', '1', 'B', 'Equipment, other than that controlled by 1B001, for the “production” of structural composites, fibers, prepregs or preforms, usable for rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km and their subsystems, as follows ; and “specially designed” “parts,” “components” and “accessories” therefor', 'Equipment, other than that controlled by 1B001, for the “production” of structural composites, fibers, prepregs or preforms, usable for rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km and their subsystems, as follows ; and “specially designed” “parts,” “components” and “accessories” therefor. Items: a. Filament winding machines or ''fiber/tow-placement machines,'' of which the motions for positioning, wrapping and winding fibers can be coordinated and programmed in three or more axes, designed to fabricate composite structures or laminates from fibrous or filamentary materials, and coordinating and programming controls; b. ''Tape-laying machines'' of which the motions for positioning and laying tape can be coordinated and programmed in two or more axes, designed for the manufacture of composite airframe and missile structures; Te…', '["MT1","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to filament winding machines described in 1B101.a that are capable of winding cylindrical rotors having a diameter between 75 mm (3 in.) and 400 mm (16 in.) and lengths of 600 mm (24 in.) or greater AND to coordinating and programming controls and precision mandrels for these filament winding machines -> NP Column 1.; AT applies to entire entry -> AT Column 1.', 'See ECCN 1D101 for software for items controlled by this entry and see ECCNs 1E001 (“development” and “production”) and 1E101 (“use”) for technology for items controlled by this entry. Also see 1B201.', '15 CFR Part 774, Supplement No. 1, ECCN 1B101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B102', '1', 'B', 'Metal powder “production equipment,” other than that specified in 1B002, and “parts” and “components” as follows', 'Metal powder “production equipment,” other than that specified in 1B002, and “parts” and “components” as follows. Items: a. Metal powder “production equipment” usable for the “production”, in a controlled environment, of spherical, spheroidal or atomized materials specified in 1C011.a., 1C011.b., 1C111.a.1., 1C111.a.2., or controlled for MT reasons in Category V of the USML. b. “Specially designed” “parts” and “components” for “production equipment” specified in 1B002 or 1B102.a. Note: 1B102 includes: a. Plasma generators (high frequency arc-jet) usable for obtaining sputtered or spherical metallic powders with organization of the process in an argon-water environment; b. Electroburst equipment usable for obtaining sputtered or spherical metallic powders with organization of the process in an argon-water environment; c. Equipment usable for the “production” of spherical aluminum powders…', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '1. See also 1B115.b.', '15 CFR Part 774, Supplement No. 1, ECCN 1B102 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B115', '1', 'B', '“Equipment, other than that controlled in 1B002 or 1B102, for the “production” of propellant or propellant constituents , and “specially designed” “parts” and “components” therefor', '“Equipment, other than that controlled in 1B002 or 1B102, for the “production” of propellant or propellant constituents , and “specially designed” “parts” and “components” therefor. Items: a. “Production equipment” for the “production”, handling or acceptance testing of liquid propellants or propellant constituents controlled by 1C011.a, 1C011.b, 1C111 or on the U.S. Munitions List; b. “Production equipment,” for the production, handling, mixing, curing, casting, pressing, machining, extruding or acceptance testing of solid propellants or propellant constituents described in 1C011.a, 1C011.b or 1C111, or on the U.S. Munitions List. Note: 1B115.b does not control batch mixers, continuous mixers or fluid energy mills. For the control of batch mixers, continuous mixers and fluid energy mills see 1B117, 1B118, and 1B119. Note 1: [Reserved] Note 2: 1B115 does not control equipment for the “p…', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'For the control of batch mixers, continuous mixers and fluid energy mills, see 1B117, 1B118 and 1B119.', '15 CFR Part 774, Supplement No. 1, ECCN 1B115 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B116', '1', 'B', '“Specially Designed” nozzles for producing pyrolitically derived materials formed on a mold, mandrel or other substrate from precursor gases which decompose in the 1,573 K (1,300 °C) to 3,173 K (2,900 °C) temperature range at pressures of 130 Pa to 20 kPa', '“Specially Designed” nozzles for producing pyrolitically derived materials formed on a mold, mandrel or other substrate from precursor gases which decompose in the 1,573 K (1,300 °C) to 3,173 K (2,900 °C) temperature range at pressures of 130 Pa to 20 kPa', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1B116 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B117', '1', 'B', 'Batch mixers having all of the following , and “specially designed” “parts” and “components” therefor', 'Batch mixers having all of the following , and “specially designed” “parts” and “components” therefor. Items: a. Capable of mixing under vacuum in the range from zero to 13.326 kPa; b. Capable of controlling the temperature of the mixing chamber; c. A total volumetric capacity of 110 liters (30 gallons) or more; and d. At least one ''mixing/kneading shaft'' mounted off center. Note to paragraph d: In 1B117.d. the term ''mixing/kneading shaft'' does not refer to deagglomerators or knife-spindles.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See 1B115, 1B118, and 1B119.', '15 CFR Part 774, Supplement No. 1, ECCN 1B117 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B118', '1', 'B', 'Continuous mixers having all of the following , and “specially designed” “parts” and “components” therefor', 'Continuous mixers having all of the following , and “specially designed” “parts” and “components” therefor. Items: a. Capable of mixing under vacuum in the range from zero to 13.326 kPa; b. Capable of controlling the temperature of the mixing chamber; and c. Either of the following: c.1. Two or more mixing/kneading shafts; or c.2. A single rotating and oscillating shaft with kneading teeth/pins as well as kneading teeth/pins inside the casing of the mixing chamber.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See 1B115, 1B117, and 1B119.', '15 CFR Part 774, Supplement No. 1, ECCN 1B118 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B119', '1', 'B', 'Fluid energy mills usable for grinding or milling propellant or propellant constituents specified in 1C011.a, 1C011.b or 1C111, or on the U.S. Munitions List, and “specially designed” “parts” and “components” therefor', 'Fluid energy mills usable for grinding or milling propellant or propellant constituents specified in 1C011.a, 1C011.b or 1C111, or on the U.S. Munitions List, and “specially designed” “parts” and “components” therefor', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See 1B115, 1B117 and 1B118.', '15 CFR Part 774, Supplement No. 1, ECCN 1B119 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B201', '1', 'B', 'Filament winding machines (other than those controlled by ECCN 1B001 or 1B101) and related equipment, as described in this ECCN', 'Filament winding machines (other than those controlled by ECCN 1B001 or 1B101) and related equipment, as described in this ECCN. Items: a. Filament winding machines having all of the following characteristics: a.1. Having motions for positioning, wrapping, and winding fibers coordinated and programmed in two or more axes; a.2. “Specially Designed” to fabricate composite structures or laminates from “fibrous or filamentary materials”; and a.3. Capable of winding cylindrical tubes with an internal diameter between 75 mm and 650 mm and lengths of 300 mm or greater; b. Coordinating and programming controls for filament winding machines controlled by 1B201.a; c. Precision mandrels for filament winding machines controlled by 1B201.a.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCN 1D201 for software for items controlled by this entry and see ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. Also see ECCN 1E203 for technology for the “development” of software controlled by ECCN 1D201.', '15 CFR Part 774, Supplement No. 1, ECCN 1B201 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B225', '1', 'B', 'Electrolytic cells for fluorine production with a production capacity greater than 250 g of fluorine per hour', 'Electrolytic cells for fluorine production with a production capacity greater than 250 g of fluorine per hour', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) See ECCN 1B999 for specific processing equipment, n.e.s.', '15 CFR Part 774, Supplement No. 1, ECCN 1B225 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B226', '1', 'B', 'Electromagnetic isotope separators designed for, or equipped with, single or multiple ion sources capable of providing a total ion beam current of 50 mA or greater', 'Electromagnetic isotope separators designed for, or equipped with, single or multiple ion sources capable of providing a total ion beam current of 50 mA or greater', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) Electromagnetic isotope separators “specially designed” or prepared for use in separating uranium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (2) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1B226 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B228', '1', 'B', 'Hydrogen cryogenic distillation columns having all of the characteristics described in this ECCN', 'Hydrogen cryogenic distillation columns having all of the characteristics described in this ECCN. Items: a. Designed to operate with internal temperatures of 35 K (−238 °C) or less; b. Designed to operate at an internal pressure of 0.5 to 5 MPa (5 to 50 atmospheres); c. Constructed of “fine-grain stainless steels” of the 300 series with low sulphur content or equivalent cryogenic and H2-compatible materials; and d. With internal diameters of 30 cm or greater and “effective lengths” of 4 m or greater.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) Equipment “specially designed” or prepared for the production of heavy water is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (2) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1B228 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B230', '1', 'B', 'Pumps capable of circulating solutions of concentrated or dilute potassium amide catalyst in liquid ammonia (KNH2/NH3), having all of the following characteristics', 'Pumps capable of circulating solutions of concentrated or dilute potassium amide catalyst in liquid ammonia (KNH2/NH3), having all of the following characteristics. Items: a. Airtight (i.e., hermetically sealed); b. A capacity greater than 8.5 m 3/h; and c. Either of the following characteristics: c.1. For concentrated potassium amide solutions (1% or greater), an operating pressure of 1.5 to 60 MPa (15-600 atmospheres); or c.2. For dilute potassium amide solutions (less than 1%), an operating pressure of 20 to 60 MPa (200-600 atmospheres).', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) Equipment “specially designed” or prepared for the production of heavy water is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (2) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1B230 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B231', '1', 'B', 'Tritium facilities or plants, and equipment therefor, as follows', 'Tritium facilities or plants, and equipment therefor, as follows. Items: a. Facilities or plant for the production, recovery, extraction, concentration, or handling of tritium; b. Equipment for tritium facilities or plant, as follows: b.1. Hydrogen or helium refrigeration units capable of cooling to 23 K (−250 °C) or less, with heat removal capacity greater than 150 watts; or b.2. Hydrogen isotope storage or hydrogen isotope purification systems using metal hydrides as the storage, or purification medium.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) Tritium, tritium compounds, and mixtures containing tritium are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (2) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1B231 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B232', '1', 'B', 'Turboexpanders or turboexpander-compressor sets having both of the following characteristics', 'Turboexpanders or turboexpander-compressor sets having both of the following characteristics. Items: a. Designed for operation with an outlet temperature of 35 K (−238 °C) or less; and b. Designed for a throughput of hydrogen gas of 1,000 kg/h or greater.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) Equipment “specially designed” or prepared for the production of heavy water is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (2) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1B232 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B233', '1', 'B', 'Lithium isotope separation facilities or plants, and systems and equipment therefor', 'Lithium isotope separation facilities or plants, and systems and equipment therefor. Items: a. Facilities or plants for the separation of lithium isotopes; b. Equipment for the separation of lithium isotopes based on the lithium-mercury amalgam process, as follows: b.1. Packed liquid-liquid exchange columns “specially designed” for lithium amalgams; b.2. Mercury and/or lithium amalgam pumps; b.3. Lithium amalgam electrolysis cells; b.4. Evaporators for concentrated lithium hydroxide solution. c. Ion exchange systems “specially designed” for lithium isotope separation, and “specially designed” component parts therefor; d. Chemical exchange systems (employing crown ethers, cryptands, or lariat ethers) “specially designed” for lithium isotope separation, and “specially designed” component parts therefor.', '["NP1?","AT1?"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to 1B233.b -> NP Column 1; AT applies to 1B233.b -> AT Column 1', '(1) See ECCN 1E001 (“development” and “production”) and ECCN 1E201 (“use”) for technology for items described in this entry. (2) Facilities and plants described in 1B233.a are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (3) Certain lithium isotope separation equipment and components for the plasma separation process (PSP) that are described in 1B233.b through .d are also directly applicable to uranium isotope separation and are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1B233 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B234', '1', 'B', 'High explosive containment vessels, chambers, containers, and other similar containment devices, not enumerated in ECCN 1B608 or in USML Category IV or V of the ITAR, designed for the testing of high explosives or explosive devices and having both of the characteristics described in this ECCN', 'High explosive containment vessels, chambers, containers, and other similar containment devices, not enumerated in ECCN 1B608 or in USML Category IV or V of the ITAR, designed for the testing of high explosives or explosive devices and having both of the characteristics described in this ECCN. Items: a. Designed to fully contain an explosion equivalent to 2 kg of TNT or greater; and b. Having design elements or features enabling real time or delayed transfer of diagnostic or measurement information.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) Devices “specially designed” for the handling, control, activation, monitoring, detection, protection, discharge, or detonation of the articles enumerated in USML Category IV(a) and (b) are controlled by USML Category IV(c) of the ITAR (see 22 CFR parts 120 through 130). (2) See USML Category V of the ITAR (22 CFR parts 120 through 130) for devices identified therein that are “specially designed” to fully contain explosives enumerated in USML Category V. (3) Also see ECCN 1B608 for “equipment” “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of items controlled by ECCN 1C608 or USML Category V and not elsewhere specified on the USML.', '15 CFR Part 774, Supplement No. 1, ECCN 1B234 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B607', '1', 'B', 'Military test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities identified in ECCN 1A607 or 1C607, or defense articles enumerated or otherwise described in USML Category XIV', 'Military test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities identified in ECCN 1A607 or 1C607, or defense articles enumerated or otherwise described in USML Category XIV. Items: a. “Equipment” “specially designed” for the destruction of the chemical agents controlled by USML Category XIV(a). Note to 1B607.a: ECCN 1B607.a includes controls over facilities “specially designed” for destruction operations. This paragraph .a does not control incinerators and “specially designed” handling facilities or “specially designed” waste supply systems therefor. b. Test facilities and “equipment” “specially designed” for military certification, qualification, or testing of commodities controlled by ECCN 1A607.e, .f, .g, .h, or .j or by USML Category XIV(f), except for XIV(f)(1).…', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1B607.', 'NS applies to entire entry -> NS Column 1.; RS applies to entire entry -> RS Column 1.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', '(1) See ECCN 2B350 for controls on certain incinerators. (2) See ECCN 0A919 for “military commodities” located and produced outside the United States that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1B607 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B608', '1', 'B', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated in ECCN 1C608 or USML Category V', 'Test, inspection, and production “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities enumerated in ECCN 1C608 or USML Category V. Items: a. “Equipment” “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of items controlled by ECCN 1C608 or USML Category V and not elsewhere specified on the USML. Note to paragraph a: ECCN 1B608.a. includes: (1) Continuous nitrators; (2) dehydration presses; (3) cutting machines for the sizing of extruded propellants; (4) sweetie barrels (tumblers) 6 feet or more in diameter and having over 500 pounds product capacity; (5) convection current converters for the conversion of materials listed in USML Category V(c)(2); and (6) extrusion presses for the extrusion of small arms, cannon and rocket propellants. b. Complete installat…', '["NS1","RS1","MT1?","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1B608.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; MT applies to equipment “specially designed” for MT-controlled commodities in ECCN 1C608 or MT articles in USML Category V -> MT Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Defense articles that are enumerated in USML Category V, and technical data (including software) directly related thereto, are “subject to the ITAR”. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content. (3) See ECCN 1B115 for controls on “production equipment,” not controlled by this ECCN 1B608, for propellants or propellant constituents described in ECCN 1C011.a, 1C011.b, or 1C111 or in USML Category V.', '15 CFR Part 774, Supplement No. 1, ECCN 1B608 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B613', '1', 'B', 'Test, inspection, and “production” “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities controlled by ECCN 1A613 or USML Category X, as follows', 'Test, inspection, and “production” “equipment” and related commodities “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities controlled by ECCN 1A613 or USML Category X, as follows. Items: a. Test, inspection, and “production” “equipment,” not controlled by USML Category X(c), that is “specially designed” for the “development,” “production,” repair, overhaul, or refurbishing of commodities controlled by ECCN 1A613 or USML Category X. b. Plasma pressure compaction (P2C) “equipment” “specially designed” for the “production” of ceramic or composite body armor plates controlled by ECCN 1A613 or USML Category X.', '["NS1","RS1","AT1","UN?"]', '["LVS"]', 'LVS: $1500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1B613.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', 'See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1B613 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1B999', '1', 'B', 'Specific processing equipment, n.e.s., as follows', 'Specific processing equipment, n.e.s., as follows. Items: a. Electrolytic cells for fluorine production, n.e.s. b. Particle accelerators. c. Industrial process control hardware/systems designed for power industries, n.e.s. d. Freon and chilled water cooling systems capable of continuous cooling duties of 100,000 BTU/hr (29.3 kW) or greater. e. Equipment for the production of structural composites, fibers, prepregs and preforms, n.e.s.', '["RS?","AT?"]', '[]', 'LVS: N/A | GBS: N/A', 'RS applies to entire entry -> A license is required for items controlled by this entry for export or reexport to Iraq or Pakistan or transfer within Iraq or Pakistan for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.; AT applies to entire entry -> A license is required for items controlled by this entry to North Korea for anti-terrorism reasons. The Commerce Country Chart is not designed to determine AT license requirements for this entry. See § 742.19 of the EAR for additional information.', 'See also 1B001, 1B101, 1B201, 1B225, and 1D999', '15 CFR Part 774, Supplement No. 1, ECCN 1B999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C001', '1', 'C', 'Materials “specially designed” for absorbing electromagnetic radiation, or intrinsically conductive polymers, as follows', 'Materials “specially designed” for absorbing electromagnetic radiation, or intrinsically conductive polymers, as follows. Items: a. Materials for absorbing frequencies exceeding 2 × 10 8 Hz but less than 3 × 10 12 Hz. Note 1: 1C001.a does not control: a. Hair type absorbers, constructed of natural or synthetic fibers, with non-magnetic loading to provide absorption; b. Absorbers having no magnetic loss and whose incident surface is non-planar in shape, including pyramids, cones, wedges and convoluted surfaces; c. Planar absorbers, having all of the following: 1. Made from any of the following: a. Plastic foam materials (flexible or non-flexible) with carbon-loading, or organic materials, including binders, providing more than 5% echo compared with metal over a bandwidth exceeding ±15% of the center frequency of the incident energy, and not capable of withstanding temperatures exceeding…', '["NS1","MT1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A | STA: License Exception STA may not be used to ship any item in this entry to any of the destinations listed in Country Group A:6 (See Supplement No.1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 1; MT applies to items that meet or exceed the parameters of ECCN 1C101 -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See also 1C101.', '15 CFR Part 774, Supplement No. 1, ECCN 1C001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C002', '1', 'C', 'Metal alloys, metal alloy powder and alloyed materials, as follows', 'Metal alloys, metal alloy powder and alloyed materials, as follows. Items: Note: 1C002 does not control metal alloys, metal alloy powder and alloyed materials, specially formulated for coating purposes. Technical Note: For the purposes of 1C002, metal alloys are those containing a higher percentage by weight of the stated metal than of any other element. a. Aluminides, as follows: a.1. Nickel aluminides containing a minimum of 15% by weight aluminum, a maximum of 38% by weight aluminum and at least one additional alloying element; a.2. Titanium aluminides containing 10% by weight or more aluminum and at least one additional alloying element; b. Metal alloys, as follows, made from the powder or particulate material controlled by 1C002.c: b.1. Nickel alloys having any of the following: b.1.a. A ''stress-rupture life'' of 10,000 hours or longer at 923 K (650 °C) at a stress of 676 MPa; or b.…', '["NS2","NP1?","AT1"]', '["LVS"]', 'LVS: $3000; N/A for NP | GBS: N/A', 'NS applies to entire entry -> NS Column 2; NP applies to 1C002.b.3 or b.4 if they exceed the parameters stated in 1C202 -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Also see ECCN 1C202. (3) Aluminum alloys and titanium alloys in physical forms and finished products “especially designed” or prepared for use in separating uranium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C003', '1', 'C', 'Magnetic metals, of all types and of whatever form, having any of the following', 'Magnetic metals, of all types and of whatever form, having any of the following. Items: a. Initial relative permeability of 120,000 or more and a thickness of 0.05 mm or less; Technical Note: For the purposes of 1C003.a, measurement of initial relative permeability must be performed on fully annealed materials. b. Magnetostrictive alloys having any of the following: b.1. A saturation magnetostriction of more than 5 × 104−4; or b.2. A magnetomechanical coupling factor (k) of more than 0.8; or c. Amorphous or ''nanocrystalline'' alloy strips, having all of the following: c.1. A composition having a minimum of 75% by weight of iron, cobalt or nickel; c.2. A saturation magnetic induction (Bs) of 1.6 T or more; and c.3. Any of the following: c.3.a. A strip thickness of 0.02 mm or less; or c.3.b. An electrical resistivity of 2 × 10−4 ohm cm or more. Technical Note: For the purposes of 1C003.c,…', '["NS2","AT1"]', '["LVS"]', 'LVS: $3000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C004', '1', 'C', 'Uranium titanium alloys or tungsten alloys with a “matrix” based on iron, nickel or copper, having all of the following', 'Uranium titanium alloys or tungsten alloys with a “matrix” based on iron, nickel or copper, having all of the following. Items: a. A density exceeding 17.5 g/cm 3; b. An elastic limit exceeding 880 MPa; c. An ultimate tensile strength exceeding 1,270 MPa; and d. An elongation exceeding 8%.', '["NS2","AT1"]', '["LVS"]', 'LVS: $3000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'See also 1C117 and 1C226.', '15 CFR Part 774, Supplement No. 1, ECCN 1C004 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C005', '1', 'C', '“Superconductive” “composite” conductors in lengths exceeding 100 m or with a mass exceeding 100 g, as follows', '“Superconductive” “composite” conductors in lengths exceeding 100 m or with a mass exceeding 100 g, as follows. Items: a. “Superconductive” “composite” conductors containing one or more niobium-titanium ''filaments'', having all of the following: a.1. Embedded in a “matrix” other than a copper or copper-based mixed “matrix”; and a.2. Having a cross-section area less than 0.28 × 10−4 mm 2 (6 µm in diameter for circular ''filaments''); b. “Superconductive” “composite” conductors consisting of one or more “superconductive” ''filaments'' other than niobium-titanium, having all of the following: b.1. A “critical temperature” at zero magnetic induction exceeding 9.85 K (−263.31 °C); and b.2. Remaining in the “superconductive” state at a temperature of 4.2 K (−268.96 °C) when exposed to a magnetic field oriented in any direction perpendicular to the longitudinal axis of conductor and corresponding t…', '["NS2","AT1"]', '["LVS"]', 'LVS: $1500 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C005 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C006', '1', 'C', 'Fluids and lubricating materials, as follows', 'Fluids and lubricating materials, as follows. Items: a. [Reserved] b. Lubricating materials containing, as their principal ingredients, phenylene or alkylphenylene ethers or thio-ethers, or their mixtures, containing more than two ether or thio-ether functions or mixtures thereof. c. Damping or flotation fluids having all of the following: c.1. Purity exceeding 99.8%; c.2. Containing less than 25 particles of 200 µm or larger in size per 100 ml; and c.3. Made from at least 85% of any of the following: c.3.a. Dibromotetrafluoroethane (CAS 25497-30-7, 124-73-2, 27336-23-8); c.3.b. Polychlorotrifluoroethylene (oily and waxy modifications only); or c.3.c. Polybromotrifluoroethylene; d. Fluorocarbon fluids designed for electronic cooling and having all of the following: d.1. Containing 85% by weight or more of any of the following, or mixtures thereof: d.1.a. Monomeric forms of perfluoropoly…', '["NS2","AT1"]', '["LVS","GBS"]', 'LVS: $3000 | GBS: Yes for 1C006.d', 'NS applies to entire entry -> NS Column 2.; AT applies to entire entry -> AT Column 1.', 'See also 1C996.', '15 CFR Part 774, Supplement No. 1, ECCN 1C006 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C007', '1', 'C', 'Ceramic powders, ceramic “matrix” “composite” materials and ''precursor materials,'' as follows', 'Ceramic powders, ceramic “matrix” “composite” materials and ''precursor materials,'' as follows. Items: a. Ceramic powders of titanium diboride (TiB2) (CAS 12045-63-5) having total metallic impurities, excluding intentional additions, of less than 5,000 ppm, an average particle size equal to or less than 5 µm and no more than 10% of the particles larger than 10 µm; b. [Reserved] c. Ceramic “matrix” “composite” materials as follows: c.1. Ceramic-ceramic “composite” materials with a glass or oxide-“matrix” and reinforced with any of the following: c.1.a. Continuous fibers made from any of the following materials: c.1.a.1. Al2O3 (CAS 1344-28-1); or c.1.a.2. Si-C-N; or Note: 1C007.c.1.a does not apply to “composites” containing fibers with a tensile strength of less than 700 MPa at 1,273 K (1,000 °C) or tensile creep resistance of more than 1% creep strain at 100 MPa load and 1,273 K (1,000 °…', '["NS2","MT1?","AT1"]', '["LVS"]', 'LVS: $5,000, except N/A for MT and for 1C007.e | GBS: N/A | STA: License Exception STA may not be used to ship any item in 1C007.c entry to any of the destinations listed in Country Group A:6 (See Supplement No.1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 2; MT applies to items in 1C007.c when the dielectric constant is less than 6 at any frequency from 100 MHz to 100 GHz for use in “missile” radomes -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See also 1C107', '15 CFR Part 774, Supplement No. 1, ECCN 1C007 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C008', '1', 'C', 'Non-fluorinated polymeric substances as follows', 'Non-fluorinated polymeric substances as follows. Items: a. Imides as follows: a.1. Bismaleimides; a.2. Aromatic polyamide-imides (PAI) having a ''glass transition temperature (Tg)'' exceeding 563 K (290 °C); a.3. Aromatic polyimides having a ''glass transition temperature (Tg)'' exceeding 505 K (232 °C); a.4. Aromatic polyetherimides having a ''glass transition temperature (Tg)'' exceeding 563 K (290 °C); Note: 1C008.a controls the substances in liquid or solid “fusible” form, including resin, powder, pellet, film, sheet, tape, or ribbon. N.B.: For non-“fusible” aromatic polyimides in film, sheet, tape, or ribbon form, see ECCN 1A003. b. [Reserved] c. [Reserved] d. Polyarylene ketones; e. Polyarylene sulfides, where the arylene group is biphenylene, triphenylene or combinations thereof; f. Polybiphenylenethersulphone having a ''glass transition temperature (Tg)'' exceeding 563 K (290 °C). Techn…', '["NS2","AT1"]', '["LVS"]', 'LVS: $200 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'See also 1A003.', '15 CFR Part 774, Supplement No. 1, ECCN 1C008 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C009', '1', 'C', 'Unprocessed fluorinated compounds as follows', 'Unprocessed fluorinated compounds as follows. Items: a. [Reserved] b. Fluorinated polyimides containing 10% by weight or more of combined fluorine; c. Fluorinated phosphazene elastomers containing 30% by weight or more of combined fluorine.', '["NS2","AT1"]', '["LVS"]', 'LVS: $5000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'See also 1A001.', '15 CFR Part 774, Supplement No. 1, ECCN 1C009 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C010', '1', 'C', '“Fibrous or filamentary materials” as follows', '“Fibrous or filamentary materials” as follows. Items: Technical Notes: 1. For the purposes of calculating “specific tensile strength”, “specific modulus” or specific weight of “fibrous or filamentary materials” in 1C010.a, 1C010.b, 1C010.c, or 1C010.e.1.b the tensile strength and modulus should be determined by using Method A described in ISO 10618 (2004) or national equivalents. 2. For the purposes of assessing the “specific tensile strength”, “specific modulus” or specific weight of non-unidirectional “fibrous or filamentary materials” (e.g., fabrics, random mats or braids) in 1C010, this is to be based on the mechanical properties of the constituent unidirectional monofilaments (e.g., monofilaments, yarns, rovings or tows) prior to processing into the non-unidirectional “fibrous or filamentary materials”. a. Organic “fibrous or filamentary materials”, having all of the following: a.1…', '["NS2","NP1?","AT1"]', '["LVS"]', 'LVS: $1500, N/A for NP | GBS: N/A | STA: License Exception STA may not be used to ship any item in 1C010.c to any of the destinations listed in Country Group A:6 (See Supplement No.1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 2; NP applies to 1C010.a (aramid “fibrous or filamentary materials”, b (carbon “fibrous and filamentary materials”), and e.1 for “fibrous and filamentary materials” that meet or exceed the control criteria of ECCN 1C210 -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Also see ECCNs 1C210 and 1C990. (3) See also 9C110 for material not controlled by 1C010.e, as defined by notes 1 or 2.', '15 CFR Part 774, Supplement No. 1, ECCN 1C010 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse');
INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('1C011', '1', 'C', 'Metals and compounds, as follows', 'Metals and compounds, as follows. Items: a. Metals in particle sizes of less than 60 µm whether spherical, atomized, spheroidal, flaked or ground, manufactured from material consisting of 99% or more of zirconium, magnesium and alloys thereof; Technical Note: For the purposes of 1C011.a, the natural content of hafnium in the zirconium (typically 2% to 7%) is counted with the zirconium. Note: The metals or alloys specified by 1C011.a also refer to metals or alloys encapsulated in aluminum, magnesium, zirconium or beryllium. b. Boron or boron alloys, with a particle size of 60 µm or less, as follows: b.1. Boron with a purity of 85% by weight or more; b.2. Boron alloys with a boron content of 85% by weight or more; Note: The metals or alloys specified by 1C011.b also refer to metals or alloys encapsulated in aluminum, magnesium, zirconium or beryllium. c. Guanidine nitrate (CAS 506-93-4);…', '["NS2","MT1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; MT applies to 1C011.a and .b for items that meet or exceed the parameters in 1C111. -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) See also ECCNs 1C111 and 1C608. (2) All of the following are “subject to the ITAR” (see 22 CFR parts 120 through 130): (a) Materials controlled by 1C011.a, and metal fuels in particle form, whether spherical, atomized, spheroidal, flaked or ground, manufactured from material consisting of 99 percent or more of items controlled by 1C011.b; and (b) Metal powders mixed with other substances to form a mixture formulated for military purposes.', '15 CFR Part 774, Supplement No. 1, ECCN 1C011 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C018', '1', 'C', 'Commercial charges and devices containing energetic materials on the Wassenaar Arrangement Munitions List and certain chemicals', 'Commercial charges and devices containing energetic materials on the Wassenaar Arrangement Munitions List and certain chemicals', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C018 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C101', '1', 'C', 'Materials for Reduced Observables such as Radar Reflectivity, Ultraviolet/Infrared Signatures and Acoustic Signatures (i.e., Stealth Technology), Other than Those Controlled by 1C001, for applications usable in rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300km, and their subsystems', 'Materials for Reduced Observables such as Radar Reflectivity, Ultraviolet/Infrared Signatures and Acoustic Signatures (i.e., Stealth Technology), Other than Those Controlled by 1C001, for applications usable in rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300km, and their subsystems', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) Materials controlled by this entry include structural materials and coatings (including paints), “specially designed” for reduced or tailored reflectivity or emissivity in the microwave, infrared or ultraviolet spectra. (2) This entry does not control coatings (including paints) when specially used for the thermal control of satellites. (3) For commodities that meet the definition of defense articles under 22 CFR 120.3 of the International Traffic in Arms Regulations (ITAR), which describes similar commodities “subject to the ITAR” (See 22 CFR parts 120 through 130, including USML Category XIII).', '15 CFR Part 774, Supplement No. 1, ECCN 1C101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C102', '1', 'C', 'Resaturated pyrolized carbon-carbon materials designed for space launch vehicles specified in 9A004 or sounding rockets specified in 9A104. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', 'Resaturated pyrolized carbon-carbon materials designed for space launch vehicles specified in 9A004 or sounding rockets specified in 9A104. (These items are “subject to the ITAR.” See 22 CFR parts 120 through 130.)', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C102 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C107', '1', 'C', 'Graphite and Ceramic Materials, Other Than Those Controlled by 1C007, Which Can be Machined to Any of the Following Products as Follows', 'Graphite and Ceramic Materials, Other Than Those Controlled by 1C007, Which Can be Machined to Any of the Following Products as Follows. Items: a. Fine grain graphites with a bulk density of 1.72 g/cm 3 or greater, measured at 15 °C, and having a grain size of 100 micrometers or less, usable for rocket nozzles and reentry vehicle nose tips as follows: a.1. Cylinders having a diameter of 120 mm or greater and a length of 50 mm or greater; a.2. Tubes having an inner diameter of 65 mm or greater and a wall thickness of 25 mm or greater and a length of 50 mm or greater; a.3. Blocks having a size of 120 mm × 120 mm × 50 mm or greater. b. Pyrolytic or fibrous reinforced graphites, usable for rocket nozzles and reentry vehicle nose tips; c. Ceramic composite materials (dielectric constant is less than 6 at any frequency from 100 MHz to 100 GHz) for use in radomes useable in rockets, missiles,…', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) See also 1C004, 1C007, and 1C298. (2) For commodities that meet the definition of defense articles under 22 CFR 120.3 of the ITAR, which describes similar commodities “subject to the ITAR” (See 22 CFR parts 120 through 130, including USML Category XIII). (3) “Special fissile materials” and “other fissile materials”; except, four “effective grams” or less when contained in a sensing component in instruments are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C107 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C111', '1', 'C', 'Propellants and constituent chemicals for propellants, other than those specified in 1C011, as follows', 'Propellants and constituent chemicals for propellants, other than those specified in 1C011, as follows. Items: a. Propulsive substances: a.1. Spherical or spheroidal aluminum powder (C.A.S. 7429-90-5) in particle size of less than 200 × 10−6 m (200 µm) and an aluminum content of 97% by weight or more, if at least 10% of the total weight is made up of particles of less than 63 µm, according to ISO 2591-1:1988 or national equivalents. Technical Note: A particle size of 63 µm (ISO R-565) corresponds to 250 mesh (Tyler) or 230 mesh (ASTM standard E-11). a.2. Metal powders and alloys where at least 90% of the total particles by particle volume or weight are made up of particles of less than 60 µ (determined by measurement techniques such as using a sieve, laser diffraction or optical scanning), whether spherical, atomized, spheroidal, flaked or ground, as follows: a.2.a. Consisting of 97% by…', '["MT1","NP1?","RS1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to 1C111.a.3.f only -> NP Column 1.; RS applies to 1C111.d.3 only -> RS Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See USML Category V(e)(7) for controls on HTPB (hydroxyl terminated polybutadiene) with a hydroxyl functionality equal to or greater than 2.2 and less than or equal to 2.4, a hydroxyl value of less than 0.77 meq/g, and a viscosity at 30 °C of less than 47 poise (CAS #69102-90-5). (2) See USML Category V for controls on ferrocene derivatives, including butacene. (3) See ECCN 1C608 for controls on oxidizers that are composed of fluorine and also other halogens, oxygen, or nitrogen, except for chlorine trifluoride, which is controlled under this ECCN 1C111.a.3.f. (4) See ECCN 1C011.b for controls on boron and boron alloys not controlled under this ECCN 1C111.a.2.b. (5) See USML Category V for controls on Inhibited Red Fuming Nitric Acid (IRFNA) (CAS 8007-58-7).', '15 CFR Part 774, Supplement No. 1, ECCN 1C111 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C116', '1', 'C', 'Maraging steels having both of the following', 'Maraging steels having both of the following. Items: a. Having an ultimate tensile strength, measured at 20 °C, equal to or greater than: a.1. 0.9 GPa in the solution annealed stage; or a.2. 1.5 GPa in the precipitation hardened stage; and b. Any of the following forms: b.1 Sheet, plate or tubing with a wall or plate thickness equal to or less than 5.0 mm; or b.2 Tubular forms with a wall thickness equal to or less than 50 mm and having an inner diameter equal to or greater than 270 mm. Technical Note: Maraging steels are iron alloys that are generally: a. Characterized by high nickel, very low carbon content and use substitutional elements or precipitates to produce strengthening and age-hardening of the alloy; and b. Subjected to heat treatment cycles to facilitate the martensitic transformation process (solution annealed stage) and subsequently age hardened (precipitation hardened st…', '["MT1","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; NP applies to items that meet or exceed the parameters of 1C216 -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E101 (“use”) for technology for items controlled by this entry. (2) Also see ECCN 1C216. (3) Maraging steel, in physical forms and finished products and “specially designed” or prepared for use in separating uranium isotopes, is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C116 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C117', '1', 'C', 'Materials for the fabrication of missile “parts” or “components” for rockets or missiles capable of achieving a “range” equal to or greater than 300 km, as follows', 'Materials for the fabrication of missile “parts” or “components” for rockets or missiles capable of achieving a “range” equal to or greater than 300 km, as follows. Items: a. Tungsten and alloys in particulate form with a tungsten content of 97% by weight or more and a particle size of 50 × 10−6 m (50 µm) or less; b. Molybdenum and alloys in particulate form with a molybdenum content of 97% by weight or more and a particle size of 50 × 10−6 m (50 µm) or less; c. Tungsten materials in the solid form having all of the following: c.1. Any of the following material compositions: c.1.a. Tungsten and alloys containing 97% by weight or more of tungsten; c.1.b. Copper infiltrated tungsten containing 80% by weight or more of tungsten; or c.1.c. Silver infiltrated tungsten containing 80% by weight or more of tungsten; and c.2. Able to be machined to any of the following products: c.2.a. Cylinders…', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See 1C226.', '15 CFR Part 774, Supplement No. 1, ECCN 1C117 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C118', '1', 'C', 'Titanium-stabilized duplex stainless steel (Ti-DSS), having all of the following characteristics', 'Titanium-stabilized duplex stainless steel (Ti-DSS), having all of the following characteristics. Items: a. Having all of the following characteristics: a.1. Containing 17.0-23.0% by weight of chromium and 4.5-7.0% by weight of nickel; a.2. Having a titanium content of greater than 0.10% by weight; and a.3. A ferritic-austenitic microstructure (also referred to as a two-phase microstructure) of which at least 10% by volume (according to ASTM E-1181-87 or national equivalents) is austenite; and b. Having any of the following forms: b.1. Ingots or bars having a size of 100 mm or more in each dimension; b.2. Sheets having a width of 600 mm or more and a thickness of 3 mm or less; or b.3. Tubes having an outer diameter of 600 mm or more and a wall thickness of 3 mm or less.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C118 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C202', '1', 'C', 'Alloys other than those controlled by 1C002.b.3 or 1C002.b.4 as follows', 'Alloys other than those controlled by 1C002.b.3 or 1C002.b.4 as follows. Items: a. Aluminum alloys having both of the following characteristics: a.1. “Capable of” an ultimate tensile strength of 460 MPa or more at 293 K (20 °C); and a.2. In the form of tubes or cylindrical solid forms (including forgings) with an outside diameter of more than 75 mm; b. Titanium alloys having both of the following characteristics: b.1. “Capable of” an ultimate tensile strength of 900 MPa or more at 293 K (20 °C); and b.2. In the form of tubes or cylindrical solid forms (including forgings) with an outside diameter of more than 75 mm.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Also see ECCN 1C002. (3) Aluminum alloys and titanium alloys, in physical forms and finished products and “specially designed” or prepared for use in separating uranium isotopes, are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C202 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C210', '1', 'C', '“Fibrous or filamentary materials” or prepregs, other than those controlled by 1C010.a, .b or .e, as follows', '“Fibrous or filamentary materials” or prepregs, other than those controlled by 1C010.a, .b or .e, as follows. Items: a. Carbon or aramid “fibrous or filamentary materials” having a “specific modulus” of 12.7 × 10 6 m or greater or a “specific tensile strength” of 235 × 10 3 m or greater except Aramid “fibrous or filamentary materials” having 0.25 percent or more by weight of an ester based fiber surface modifier; b. Glass “fibrous or filamentary materials” having a “specific modulus” of 3.18 × 10 6 m or greater and a “specific tensile strength” of 76.2 × 10 3 m or greater; or c. Thermoset resin impregnated continuous “yarns”, “rovings”, “tows” or “tapes” with a width no greater than 15 mm (prepregs), made from carbon or glass “fibrous or filamentary materials” controlled by 1C210.a or .b. Technical Note: The resin forms the matrix of the composite.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Also see ECCNs 1C010 and 1C990.', '15 CFR Part 774, Supplement No. 1, ECCN 1C210 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C216', '1', 'C', 'Maraging steel, other than that controlled by 1C116, “capable of” an ultimate tensile strength of 1,950 MPa or more, at 293 K (20 °C)', 'Maraging steel, other than that controlled by 1C116, “capable of” an ultimate tensile strength of 1,950 MPa or more, at 293 K (20 °C)', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C216 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C225', '1', 'C', 'Boron enriched in the boron-10 ( 10B) isotope to greater than its natural isotopic abundance, as follows: elemental boron, compounds, mixtures containing boron, manufactures thereof, waste or scrap of any of the foregoing', 'Boron enriched in the boron-10 ( 10B) isotope to greater than its natural isotopic abundance, as follows: elemental boron, compounds, mixtures containing boron, manufactures thereof, waste or scrap of any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C225 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C226', '1', 'C', 'Tungsten, tungsten carbide, and alloys containing more than 90% tungsten by weight, having both of the following characteristics', 'Tungsten, tungsten carbide, and alloys containing more than 90% tungsten by weight, having both of the following characteristics. Items: a. In forms with a hollow cylindrical symmetry (including cylinder segments) with an inside diameter between 100 and 300 mm; and b. A mass greater than 20 kg.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C226 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C227', '1', 'C', 'Calcium having both of the following characteristics', 'Calcium having both of the following characteristics. Items: a. Containing less than 1,000 parts per million by weight of metallic impurities other than magnesium; and b. Containing less than 10 parts per million by weight of boron.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C227 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C228', '1', 'C', 'Magnesium having both of the following characteristics', 'Magnesium having both of the following characteristics. Items: a. Containing less than 200 parts per million by weight of metallic impurities other than calcium; and b. Containing less than 10 parts per million by weight of boron.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C228 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C229', '1', 'C', 'Bismuth having both of the following characteristics', 'Bismuth having both of the following characteristics. Items: a. A purity of 99.99% or greater by weight; and b. Containing less than 10 parts per million by weight of silver.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C229 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C230', '1', 'C', 'Beryllium metal, alloys containing more than 50% beryllium by weight, beryllium compounds, manufactures thereof, and waste or scrap of any of the foregoing', 'Beryllium metal, alloys containing more than 50% beryllium by weight, beryllium compounds, manufactures thereof, and waste or scrap of any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C230 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C231', '1', 'C', 'Hafnium metal, hafnium alloys and compounds containing more than 60% hafnium by weight, manufactures thereof, and waste or scrap of any of the foregoing', 'Hafnium metal, hafnium alloys and compounds containing more than 60% hafnium by weight, manufactures thereof, and waste or scrap of any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C231 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C232', '1', 'C', 'Helium-3 ( 3He), mixtures containing helium-3, and products or devices containing any of the foregoing', 'Helium-3 ( 3He), mixtures containing helium-3, and products or devices containing any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C232 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C233', '1', 'C', 'Lithium enriched in the lithium-6 ( 6 Li) isotope to greater than its natural isotopic abundance, and products or devices containing enriched lithium, as follows: elemental lithium, alloys, compounds, mixtures containing lithium, manufactures thereof, and waste or scrap of any of the foregoing', 'Lithium enriched in the lithium-6 ( 6 Li) isotope to greater than its natural isotopic abundance, and products or devices containing enriched lithium, as follows: elemental lithium, alloys, compounds, mixtures containing lithium, manufactures thereof, and waste or scrap of any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) See ECCN 1B233 for lithium isotope separation facilities or plants, and equipment therefor. (3) Certain facilities or plants for the separation of lithium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C233 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C234', '1', 'C', 'Zirconium with a hafnium content of less than 1 part hafnium to 500 parts zirconium by weight, as follows: metal, alloys containing more than 50% zirconium by weight, compounds, manufactures thereof, and waste or scrap of any of the foregoing', 'Zirconium with a hafnium content of less than 1 part hafnium to 500 parts zirconium by weight, as follows: metal, alloys containing more than 50% zirconium by weight, compounds, manufactures thereof, and waste or scrap of any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Zirconium metal and alloys in the form of tubes or assemblies of tubes, “specially designed” or prepared for use in a reactor, are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C234 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C235', '1', 'C', 'Tritium, tritium compounds, mixtures containing tritium in which the ratio of tritium to hydrogen atoms exceeds 1 part in 1,000, and products or devices containing any of the foregoing', 'Tritium, tritium compounds, mixtures containing tritium in which the ratio of tritium to hydrogen atoms exceeds 1 part in 1,000, and products or devices containing any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Also see ECCN 1B231. (3) Tritium that is byproduct material (e.g., produced in a nuclear reactor) is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C235 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C236', '1', 'C', 'Radionuclides appropriate for making neutron sources based on alpha-n reaction and products or devices containing such radionuclides', 'Radionuclides appropriate for making neutron sources based on alpha-n reaction and products or devices containing such radionuclides. Items: a. Radionuclides identified in 1C236.a.1 in any of the forms described in 1C236.a.2: a.1. Radionuclides, as follows, appropriate for making neutron sources based on alpha-n reactions: a.1.a. Actinium 225; a.1.b. Actinium 227; a.1.c. Californium 253; a.1.d. Curium 240; a.1.e. Curium 241; a.1.f. Curium 242; a.1.g. Curium 243; a.1.h. Curium 244; a.1.i. Einsteinium 253; a.1.j. Einsteinium 254; a.1.k. Gadolinium 148; a.1.l. Plutonium 236; a.1.m. Plutonium 238; a.1.n. Polonium 208; a.1.o. Polonium 209; a.1.p. Polonium 210; a.1.q. Radium 223; a.1.r. Thorium 227; a.1.s. Thorium 228; a.1.t. Uranium 230; a.1.u. Uranium 232; and a.2. In any of the following forms: a.2.a. Elemental; a.2.b. Compounds having a total activity of 37 GBq (1 curie) per kg or greater…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Certain alpha-emitting radionuclides are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C236 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C237', '1', 'C', 'Radium-226 ( 226Ra), radium-226 alloys, radium-226 compounds, mixtures containing radium-226, manufactures thereof, and products or devices containing any of the foregoing', 'Radium-226 ( 226Ra), radium-226 alloys, radium-226 compounds, mixtures containing radium-226, manufactures thereof, and products or devices containing any of the foregoing', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 1C237 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C239', '1', 'C', 'High explosives, other than those controlled by the U.S. Munitions List, or substances or mixtures containing more than 2% by weight thereof, with a crystal density greater than 1.8 g/cm 3 and having a detonation velocity greater than 8,000 m/s', 'High explosives, other than those controlled by the U.S. Munitions List, or substances or mixtures containing more than 2% by weight thereof, with a crystal density greater than 1.8 g/cm 3 and having a detonation velocity greater than 8,000 m/s', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) See ECCNs 1C608 (energetic materials and related commodities on the Wassenaar Arrangement Munitions List) and 1C992 (commercial charges and devices containing energetic materials, n.e.s and nitrogen trifluoride in a gaseous state). (3) High explosives for military use are “subject to the ITAR” (see 22 CFR Part 121.1).', '15 CFR Part 774, Supplement No. 1, ECCN 1C239 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C240', '1', 'C', 'Nickel powder or porous nickel metal, other than nickel powder or porous nickel metal, specially prepared for the manufacture of gaseous diffusion barriers subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110), as follows', 'Nickel powder or porous nickel metal, other than nickel powder or porous nickel metal, specially prepared for the manufacture of gaseous diffusion barriers subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110), as follows. Items: a. Nickel powder having both of the following characteristics: a.1. A nickel purity content of 99.0% or greater by weight; and a.2. A mean particle size of less than 10 micrometers measured by American Society for Testing and Materials (ASTM) B330 standard; b. Porous nickel metal produced from materials controlled by 1C240.a. Technical Note: 1C240.b refers to porous metal formed by compacting and sintering the materials in 1C240.a to form a metal material with fine pores interconnected throughout the structure.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E001 (“development” and “production”) and 1E201 (“use”) for technology for items controlled by this entry. (2) Nickel powder and porous nickel metal, “specially designed” or prepared for use in separating uranium isotopes, are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C240 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C241', '1', 'C', 'Rhenium and alloys containing rhenium', 'Rhenium and alloys containing rhenium. Items: a. Rhenium and alloys containing rhenium, as follows, having both of the characteristics described in 1C241.b: a.1. Alloys containing 90% by weight or more of rhenium; a.2. Alloys containing 90% by weight or more of any combination of rhenium and tungsten; and b. Having both of the following characteristics: b.1. In forms with a hollow cylindrical symmetry (including cylinder segments) with an inside diameter between 100 mm and 300 mm; and b.2. A mass greater than 20 kg.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C241 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C298', '1', 'C', 'Graphite and deuterium that is intended for use other than in a nuclear reactor, as follows', 'Graphite and deuterium that is intended for use other than in a nuclear reactor, as follows. Items: a. Graphite with a boron content of less than 5 parts per million and a density greater than 1.5 grams per cubic centimeter that is intended for use other than in a nuclear reactor; b. ''Deuterium'' not for use in a nuclear reactor.', '["NP2"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 2.', '(1) See also 1C107. (2) Graphite having a purity level of less than 5 parts per million “boron equivalent” as measured according to ASTM standard C-1233-98 and intended for use in a nuclear reactor is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (3) Deuterium and any deuterium compound, including heavy water, in which the ratio of deuterium atoms to hydrogen atoms exceeds 1:5000; and intended for use in a nuclear reactor is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 1C298 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C351', '1', 'C', 'Human and animal pathogens and “toxins,” as follows', 'Human and animal pathogens and “toxins,” as follows. Items: a. Viruses identified on the Australia Group (AG) “List of Human and Animal Pathogens and Toxins for Export Control,” as follows: a.1. African horse sickness virus; a.2. African swine fever virus; a.3. Andes virus; a.4. Avian influenza (AI) viruses identified as having high pathogenicity (HP), as follows: a.4.a. AI viruses that have an intravenous pathogenicity index (IVPI) in 6-week-old chickens greater than 1.2; or a.4.b. AI viruses that cause at least 75% mortality in 4- to 8-week-old chickens infected intravenously. Note: Avian influenza (AI) viruses of the H5 or H7 subtype that do not have either of the characteristics described in 1C351.a.4 (specifically, 1C351.a.4.a or .a.4.b) should be sequenced to determine whether multiple basic amino acids are present at the cleavage site of the haemagglutinin molecule (HA0). If the…', '["CB1?","CB2","AT?","CW?"]', '[]', '', 'CB applies to items controlled by 1C351.d.15 and .16 -> CB Column 1.; CB applies to entire entry -> CB Column 2.; AT applies to entire entry -> Column 1.', '(1) Certain forms of ricin and saxitoxin in 1C351.d.15 and .d.16 are CWC Schedule 1 chemicals (see § 742.18 of the EAR). The U.S. Government must provide advance notification and annual reports to the OPCW of all exports of Schedule 1 chemicals. See § 745.1 of the EAR for notification procedures. See 22 CFR part 121, Category XIV for CWC Schedule 1 chemicals that are “subject to the ITAR.” (2) The Animal and Plant Health Inspection Service (APHIS), U.S. Department of Agriculture, and the Centers for Disease Control and Prevention (CDC), U.S. Department of Health and Human Services, maintain controls on the possession, use, and transfer within the United States of certain items controlled by this ECCN (for APHIS, see 7 CFR 331.3(b), 9 CFR 121.3(b), and 9 CFR 121.4(b); for CDC, see 42 CFR 73.3(b) and 42 CFR 73.4(b)). (3) See USML Category XIV for modified biological agents and biologically derived substances that are “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 1C351 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C353', '1', 'C', 'Genetic elements and genetically modified organisms, as follows', 'Genetic elements and genetically modified organisms, as follows. Items: a. Any genetically modified organism that contains, or any genetic element that codes for, any of the following: a.1. Any gene, genes, translated product or translated products specific to any virus controlled by 1C351.a or .b or 1C354.c; a.2. Any gene or genes specific to any bacterium controlled by 1C351.c or 1C354.a, or any fungus controlled by 1C351.e or 1C354.b, and which; a.2.a. In itself or through its transcribed or translated products represents a significant hazard to human, animal or plant health; or a.2.b. Could endow or enhance pathogenicity; or a.3. Any toxins, or their subunits, controlled by 1C351.d. b. [Reserved]. Technical Notes: 1. Genetically modified organisms include organisms in which the nucleic acid sequences have been created or altered by deliberate molecular manipulation. 2. “Genetic elem…', '["CB1?","CB2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'CB applies to genetic elements of items controlled by 1C351.d.15 and .16 -> CB Column 1.; CB applies to entire entry -> CB Column 2.; AT applies to entire entry -> AT Column 1.', '(1) The Animal and Plant Health Inspection Service (APHIS), U.S. Department of Agriculture, and the Centers for Disease Control and Prevention (CDC), U.S. Department of Health and Human Services, maintain controls on the possession, use, and transfer within the United States of certain items controlled by this ECCN, including (but not limited to) certain genetic elements, recombinant nucleic acids, and recombinant organisms associated with the agents or toxins in ECCN 1C351 or 1C354 (for APHIS, see 7 CFR 331.3(c), 9 CFR 121.3(c), and 9 CFR 121.4(c); for CDC, see 42 CFR 73.3(c) and 42 CFR 73.4(c)). (2) See USML Category XIV for modified biological agents and biologically derived substances that are “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 1C353 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C354', '1', 'C', 'Plant pathogens, as follows', 'Plant pathogens, as follows. Items: a. Bacteria, as follows: a.1. Xanthomonas albilineans; a.2. Xanthomonas citri pv. citri (Xanthomonas axonopodis pv. citri, Xanthomonas campestris pv. citri); a.3. Xanthomonas oryzae [this species of proteobacteria is identified on the APHIS “select agents” list (see Related Controls paragraph for this ECCN), but only the pathovar Xanthomonas oryzae pv. oryzae (syn. Pseudomonas campestris pv. oryzae) is identified on the Australia Group (AG) “List of Plant Pathogens for Export Control”]; a.4. Clavibacter michiganensis subsp. sepedonicus (Clavibacter sepedonicus, Clavibacter michiganense subsp. sepedonicus, Corynebacterium michiganensis subsp. sepedonicum, Corynebacterium sepedonicum); a.5. Ralstonia solanacearum, race 3, biovar 2; a.6. Raythayibactor toxicus [this bacterium is identified on the APHIS “select agents” list (see the Related Controls parag…', '["CB2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'CB applies to entire entry -> CB Column 2; AT applies to entire entry -> AT Column 1', '(1) The Animal and Plant Health Inspection Service (APHIS), U.S. Department of Agriculture, maintains controls on the possession, use, and transfer within the United States of certain items controlled by this ECCN (see 7 CFR 331.3(c), 9 CFR 121.3(c), and 9 CFR 121.4(c)). (2) See 22 CFR part 121, Category XIV(b), for modified biological agents and biologically derived substances that are subject to the export licensing jurisdiction of the U.S. Department of State, Directorate of Defense Trade Controls.', '15 CFR Part 774, Supplement No. 1, ECCN 1C354 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C355', '1', 'C', 'Chemical Weapons Convention (CWC) Schedule 2 and 3 chemicals and families of chemicals not controlled by ECCN 1C350 or “subject to the ITAR” (see 22 CFR parts)', 'Chemical Weapons Convention (CWC) Schedule 2 and 3 chemicals and families of chemicals not controlled by ECCN 1C350 or “subject to the ITAR” (see 22 CFR parts). Items: a. CWC Schedule 2 chemicals and mixtures containing Schedule 2 chemicals: a.1. Toxic chemicals, as follows, and mixtures containing toxic chemicals: a.1.a. PFIB: 1,1,3,3,3-Pentafluoro-2-(trifluoromethyl)-1-propene (C.A.S. 382-21-8) and mixtures in which PFIB constitutes more than 1 percent of the weight of the mixture; a.1.b. [Reserved] a.2. Precursor chemicals, as follows, and mixtures in which at least one of the following precursor chemicals constitutes more than 10 percent of the weight of the mixture: a.2.a. Chemicals, except for those listed in Schedule 1, containing a phosphorus atom to which is bonded one methyl, ethyl, or propyl (normal or iso) group but not further carbon atoms. Note: 1C355.a.2.a does not contro…', '["CW?","AT?"]', '[]', 'LVS: N/A | GBS: N/A', '', 'See also ECCNs 1C350 1C351, 1C395, and 1C995. See §§ 742.18 and 745.2 of the EAR for End-Use Certification requirements.', '15 CFR Part 774, Supplement No. 1, ECCN 1C355 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C395', '1', 'C', 'Mixtures and Medical, Analytical, Diagnostic, and Food Testing Kits Not Controlled by ECCN 1C350, as follows', 'Mixtures and Medical, Analytical, Diagnostic, and Food Testing Kits Not Controlled by ECCN 1C350, as follows. Items: a. Mixtures containing more than 10 percent, but less than 30 percent, by weight of any single CWC Schedule 2 chemical identified in ECCN 1C350.b (For controls on other mixtures containing these chemicals, see Note 1 in the Related Controls paragraph of this ECCN.). b. “Medical, analytical, diagnostic, and food testing kits” (as defined in the Related Definitions for this ECCN) that contain CWC Schedule 2 or 3 chemicals controlled by ECCN 1C350.b or .c in an amount not exceeding 300 grams per chemical. (For controls on other such test kits containing these and other controlled chemicals, see Note 2 in the Related Controls paragraph of this ECCN.)', '["CB?","CW?","AT?"]', '[]', 'LVS: N/A | GBS: N/A', '', '1. ECCN 1C350 controls mixtures containing 30 percent or higher concentrations, by weight, of any single CWC Schedule 2 chemical identified in ECCN 1C350.b; ECCN 1C995 controls such mixtures containing concentrations of 10 percent or less. 2. ECCN 1C995 controls “medical, analytical, diagnostic, and food testing kits” (as defined in the Related Definitions paragraph of this ECCN) that contain precursor chemicals listed in ECCN 1C350.d. ECCN 1C350 controls any such kits in which the amount of any single chemical listed in 1C350.b, .c, or .d exceeds 300 grams by weight.', '15 CFR Part 774, Supplement No. 1, ECCN 1C395 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C607', '1', 'C', 'Tear Gases, Riot Control Agents and materials for the detection and decontamination of chemical warfare agents', 'Tear Gases, Riot Control Agents and materials for the detection and decontamination of chemical warfare agents. Items: a. Tear gases and riot control agents including: a.1. CA (Bromobenzyl cyanide) (CAS 5798-79-8); a.2. CS (o-Chlorobenzylidenemalononitrile or o-Chlorobenzalmalononitrile) (CAS 2698-41-1); a.3. CN (Phenylacyl chloride or w-Chloroacetophenone) (CAS 532-27-4); a.4. CR (Dibenz-(b,f)-1,4-oxazephine) (CAS 257-07-8); a.5. Adamsite (Diphenylamine chloroarsine or DM) (CAS 578-94-9); a.6. N-Nonanoylmorpholine, (MPA) (CAS 5299-64-9); a.7. Dibromodimethyl ether (CAS 4497-29-4); a.8. Dichlorodimethyl ether (ClCi) (CAS 542-88-1); a.9. Ethyldibromoarsine (CAS 683-43-2); a.10. Bromo acetone (CAS 598-31-2); a.11. Bromo methylethylketone (CAS 816-40-0); a.12. Iodo acetone (CAS 3019-04-3); a.13. Phenylcarbylamine chloride (CAS 622-44-6); a.14. Ethyl iodoacetate (CAS 623-48-3); Note to 1C60…', '["NS1?","RS1","AT1","UN?"]', '[]', 'LVS: N/A | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1C607.', 'NS applies to entire entry, except 1C607.a.10, .a.11, .a.12, and .a.14 -> NS Column 1.; RS applies to entire entry -> RS Column 1.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', '(1) See ECCN 1A984 for controls on other riot control agents. (2) See 22 CFR 121.1 (USML), Category XIV(b), for modified biological agents and biologically derived substances that are subject to the ITAR. (3) See 22 CFR 121.1 (USML), Category XIV(g), for ITAR controls on antibodies, recombinant protective antigens, polynucleotides, biopolymers or biocatalysts (including the expression vectors, viruses, plasmids, or cultures of specific cells used to produce them) that are “specially designed” for use with articles controlled under USML Category XIV(f). (4) See ECCN 0A919 for “military commodities” located and produced outside the United States that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1C607 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C608', '1', 'C', '“Energetic materials” and related commodities', '“Energetic materials” and related commodities. Items: a. ''Single base'', ''double base'', and ''triple base'' ''propellants'' having nitrocellulose with nitrogen content greater than 12.6% in the form of either: a.1. ''Sheetstock'' or ''carpet rolls''; or a.2. Grains with diameter greater than 0.10 inches. Note: This entry does not control ''propellant'' grains used in shotgun shells, small arms cartridges, or rifle cartridges. Technical Notes: 1. ''Sheetstock'' is ''propellant'' that has been manufactured in the form of a sheet suitable for further processing. 2. A ''carpet roll'' is ''propellant'' that has been manufactured as a sheet, often cut to a desired width, and subsequently rolled up (like a carpet). 3. ''Single base'' is ''propellant'' which consists mostly of nitrocellulose. 4. ''Double base'' ''propellant'' consist mostly of nitrocellulose and nitroglycerine. 5. ''Triple base'' consists mostly of nitroce…', '["NS1","RS1","MT1?","AT1","UN?"]', '["LVS"]', 'LVS: $1,500 | GBS: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1C608.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; MT applies to 1C608.m -> MT Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) of the EAR for UN controls', '(1) The EAR does not control devices or charges containing materials controlled by USML subparagraphs V(c)(6), V(h), or V(i). The USML controls devices containing such materials. (2) The USML in Categories III, IV, or V controls devices and charges in this entry if they contain materials controlled by Category V (other than slurries) and such materials can be easily extracted without destroying the device or charge. (3) See also explosives and other items enumerated in ECCNs 1A006, 1A007, 1A008, 1C011, 1C111, 1C239, and 1C992. (4) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1C608 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C980', '1', 'C', 'Inorganic chemicals listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', 'Inorganic chemicals listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', '["SS?"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C980 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C982', '1', 'C', 'Other petroleum products listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', 'Other petroleum products listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', '["SS?"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C982 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C983', '1', 'C', 'Natural gas liquids and other natural gas derivatives listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', 'Natural gas liquids and other natural gas derivatives listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', '["SS?"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C983 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C984', '1', 'C', 'Manufactured gas and synthetic natural gas (except when commingled with natural gas and thus subject to export authorization from the Department of Energy) listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', 'Manufactured gas and synthetic natural gas (except when commingled with natural gas and thus subject to export authorization from the Department of Energy) listed in Supplement No. 1 to part 754 of the EAR that were produced or derived from the Naval Petroleum Reserves (NPR) or became available for export as a result of an exchange of any NPR produced or derived commodities', '["SS?"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C984 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C988', '1', 'C', 'Unprocessed western red cedar (thuja plicata) logs and timber, and rough, dressed and worked lumber containing wane, as described in § 754.4 of the EAR', 'Unprocessed western red cedar (thuja plicata) logs and timber, and rough, dressed and worked lumber containing wane, as described in § 754.4 of the EAR', '["SS?"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C988 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C990', '1', 'C', 'Fibrous and filamentary materials, not controlled by 1C010 or 1C210, for use in “composite” structures and with a specific modulus of 3.18 × 10 6 m or greater and a specific tensile strength of 7.62 × 10 4 m or greater', 'Fibrous and filamentary materials, not controlled by 1C010 or 1C210, for use in “composite” structures and with a specific modulus of 3.18 × 10 6 m or greater and a specific tensile strength of 7.62 × 10 4 m or greater', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C990 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C991', '1', 'C', 'Vaccines, immunotoxins, medical products, diagnostic and food testing kits, as follows', 'Vaccines, immunotoxins, medical products, diagnostic and food testing kits, as follows. Items: Technical Note: For purposes of the controls described in this ECCN, ''toxins'' refers to those toxins, or their subunits, controlled under ECCN 1C351.d. a. Vaccines containing, or designed for use against, items controlled by ECCN 1C351, 1C353 or 1C354. b. Immunotoxins containing toxins controlled by 1C351.d; c. Medical products that contain any of the following: c.1. Toxins controlled by ECCN 1C351.d (except for botulinum neurotoxins controlled by ECCN 1C351.d.3, conotoxins controlled by ECCN 1C351.d.6, or items controlled for CW reasons under ECCN 1C351.d.15 or .d.16); or c.2. Genetically modified organisms or genetic elements controlled by ECCN 1C353.a.3 (except for those that contain, or code for, botulinum neurotoxins controlled by ECCN 1C351.d.3 or conotoxins controlled by ECCN 1C351.d.6)…', '["CB3?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'CB applies to 1C991.c -> CB Column 3.; AT applies to entire entry -> AT Column 1.', '(1) Medical products containing ricin or saxitoxin, as follows, are controlled for CW reasons under ECCN 1C351:', '15 CFR Part 774, Supplement No. 1, ECCN 1C991 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C992', '1', 'C', 'Commercial charges and devices containing energetic materials, n.e.s. and nitrogen trifluoride in a gaseous state', 'Commercial charges and devices containing energetic materials, n.e.s. and nitrogen trifluoride in a gaseous state. Items: a. Shaped charges “specially designed” for oil well operations, utilizing one charge functioning along a single axis, that upon detonation produce a hole, and a.1. Contain any formulation of controlled materials; a.2. Have only a uniform shaped conical liner with an included angle of 90 degrees or less; a.3. Contain more than 0.010 kg but less than or equal to 0.090 kg of controlled materials; and a.4. Have a diameter not exceeding 4.5 inches; b. Shaped charges “specially designed” for oil well operations containing less than or equal to 0.010 kg of controlled materials; c. Detonation cord or shock tubes containing less than or equal to 0.064 kg per meter (300 grains per foot) of controlled materials; d. Cartridge power devices, that contain less than or equal to 0.7…', '["AT1","RS?"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1.; RS applies to entire entry -> A license is required for items controlled by this entry for export or reexport to Iraq and transfer within Iraq for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.; Russian industry sector sanctions apply to entire entry -> See § 746.8 for specific license requirements and license review policy.', '(1) Commercial charges and devices “subject to the EAR,” contain energetic materials described on the USML that exceed the quantities noted or that are not covered by this entry are controlled under ECCN 1C608. (2) Nitrogen trifluoride when not in a gaseous state is controlled under ECCN 1C608.', '15 CFR Part 774, Supplement No. 1, ECCN 1C992 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse');
INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('1C995', '1', 'C', 'Mixtures not controlled by ECCN 1C350, ECCN 1C355 or ECCN 1C395 that contain chemicals controlled by ECCN 1C350 or ECCN 1C355 and medical, analytical, diagnostic, and food testing kits not controlled by ECCN 1C350 or ECCN 1C395 that contain chemicals controlled by ECCN 1C350.d, as follows', 'Mixtures not controlled by ECCN 1C350, ECCN 1C355 or ECCN 1C395 that contain chemicals controlled by ECCN 1C350 or ECCN 1C355 and medical, analytical, diagnostic, and food testing kits not controlled by ECCN 1C350 or ECCN 1C395 that contain chemicals controlled by ECCN 1C350.d, as follows. Items: a. Mixtures containing the following concentrations of precursor chemicals controlled by ECCN 1C350 (For controls on other mixtures containing these chemicals, see Notes 1 and 2 in the Related Controls paragraph of this ECCN.): a.1. Mixtures containing 10 percent or less, by weight, of any single CWC Schedule 2 chemical controlled by ECCN 1C350.b; a.2. Mixtures containing less than 30 percent, by weight, of: a.2.a. Any single CWC Schedule 3 chemical controlled by ECCN 1C350.c; or a.2.b. Any single precursor chemical controlled by ECCN 1C350.d. b. Mixtures containing the following concentrations…', '["AT1","RS?"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1.; RS applies to entire entry. -> A license is required for items controlled by this entry for export or reexport to Iraq or transfer within Iraq for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.', '1. ECCN 1C350 controls mixtures containing 30 percent or higher concentrations of any single CWC Schedule 2 chemical identified in ECCN 1C350.b. ECCN 1C395 controls mixtures containing concentrations of more than 10 percent, but less than 30 percent, of any single CWC Schedule 2 chemical identified in ECCN 1C350.b. 2. ECCN 1C350 controls mixtures containing chemicals identified in ECCN 1C350.c or .d that exceed the concentration levels indicated in 1C995.a.2. 3. ECCN 1C355 controls mixtures containing chemicals identified in ECCN 1C355 that exceed the concentration levels indicated in 1C995.b. 4. ECCN 1C395 controls “medical, analytical, diagnostic, and food testing kits” (as defined in the Related Controls paragraph of this ECCN) that contain CWC Schedule 2 or 3 chemicals listed in 1C350.b or .c. ECCN 1C350 controls any such testing kits in which the amount of any single chemical listed in 1C350.b, .c., or .d exceeds 300 grams by weight.', '15 CFR Part 774, Supplement No. 1, ECCN 1C995 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C996', '1', 'C', 'Hydraulic fluids containing synthetic hydrocarbon oils, not controlled by 1C006, having all the following characteristics', 'Hydraulic fluids containing synthetic hydrocarbon oils, not controlled by 1C006, having all the following characteristics. Items: a. A flash point exceeding 477 K (204 °C); b. A pour point at 239 K (−-34 °C) or less; c. A viscosity index of 75 or more; and d. A thermal stability at 616 K (343 °C).', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C996 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C997', '1', 'C', 'Ammonium Nitrate, Including Fertilizers and Fertilizer Blends Containing More Than 15% by Weight Ammonium Nitrate, Except Liquid Fertilizers (Containing Any Amount of Ammonium Nitrate) or Dry Fertilizers Containing Less Than 15% by Weight Ammonium Nitrate', 'Ammonium Nitrate, Including Fertilizers and Fertilizer Blends Containing More Than 15% by Weight Ammonium Nitrate, Except Liquid Fertilizers (Containing Any Amount of Ammonium Nitrate) or Dry Fertilizers Containing Less Than 15% by Weight Ammonium Nitrate', '["AT1","RS?"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1.; RS applies to entire entry. -> A license is required for items controlled by this entry for export or reexport to Iraq or transfer within Iraq for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C997 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C998', '1', 'C', 'Non-fluorinated polymeric substances, not controlled by 1C008, as follows', 'Non-fluorinated polymeric substances, not controlled by 1C008, as follows. Items: a. Polyarylene ether ketones, as follows: a.1 Polyether ether ketone (PEEK); a.2. Polyether ketone ketone (PEKK); a.3. Polyether ketone (PEK); a.4. Polyether ketone ether ketone ketone (PEKEKK); b. [Reserved]', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 1C998 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1C999', '1', 'C', 'Specific Materials, n.e.s., as Follows', 'Specific Materials, n.e.s., as Follows. Items: a. Hardened steel and tungsten carbide precision ball bearings (3mm or greater diameter); b. 304 and 316 stainless steel plate, n.e.s.; c. Monel plate; d. Tributyl phosphate; e. Nitric acid in concentrations of 20 weight percent or greater; f. Fluorine; g. Alpha-emitting radionuclides, n.e.s.', '["AT?","RS?"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> A license is required for items controlled by this entry to North Korea for anti-terrorism reasons. The Commerce Country Chart is not designed to determine AT license requirements for this entry. See § 742.19 of the EAR for additional information.; RS applies to entire entry. -> A license is required for items controlled by this entry for export or reexport to Iraq or transfer within Iraq for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See §§ 742.6 and 746.3 of the EAR for additional information.', 'See also 1C236.', '15 CFR Part 774, Supplement No. 1, ECCN 1C999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D001', '1', 'D', '“Software” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 1B001 to 1B003', '“Software” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 1B001 to 1B003', '["NS1","MT1?","NP1?","AT1"]', '["TSR"]', 'TSR: Yes, except N/A for MT', 'NS applies to entire entry -> NS Column 1; MT applies to “software” for the “development,” “production,” operation, or maintenance of items controlled by 1B001 for MT reasons -> MT Column 1; NP applies to “software” for the “development”, “production” or “use” of items controlled by 1B001 for NP reasons -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 1E101 (“use”) and 1E102 (“development” and “production”) for technology for items controlled by this entry. (2) Also see 1D002, 1D101, 1D201, and 1D999.', '15 CFR Part 774, Supplement No. 1, ECCN 1D001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D002', '1', 'D', '“Software” for the “development” of organic “matrix”, metal “matrix” or carbon “matrix” laminates or “composites”', '“Software” for the “development” of organic “matrix”, metal “matrix” or carbon “matrix” laminates or “composites”', '["NS1","AT1"]', '[]', '', 'NS applies to entire entry -> NS Column 1; AT applies to entire entry -> AT Column 1', '“Software” for items controlled by 1A102 are “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 1D002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D003', '1', 'D', '“Software” “specially designed” or modified to enable equipment to perform the functions of equipment controlled under 1A004.c or 1A004.d', '“Software” “specially designed” or modified to enable equipment to perform the functions of equipment controlled under 1A004.c or 1A004.d', '["NS2","RS2?","AT1"]', '[]', 'TSR: N/A', 'NS applies to entire entry -> NS Column 2.; RS applies to software for equipment controlled by 1A004.d -> RS Column 2.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 1D003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D018', '1', 'D', '“Software” “specially designed“ or modified for the “development,” “production,” or “use” of items controlled by 1B018.b', '“Software” “specially designed“ or modified for the “development,” “production,” or “use” of items controlled by 1B018.b', '["NS1","MT?","AT1","UN?"]', '[]', 'TSR: N/A', 'NS applies to entire entry -> NS Column 1.; MT applies to “software” for the “development”, “production”, operation, or maintenance of items controlled by 1B018 for MT reasons; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', 'See ECCN 1D608 for “software” for items classified under ECCN 1B608 that, immediately prior to July 1, 2014, were classified under 1B018.a.', '15 CFR Part 774, Supplement No. 1, ECCN 1D018 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D101', '1', 'D', '“Software” “specially designed” or modified for the operation or maintenance of commodities controlled by 1B101, 1B102, 1B115, 1B117, 1B118, or 1B119', '“Software” “specially designed” or modified for the operation or maintenance of commodities controlled by 1B101, 1B102, 1B115, 1B117, 1B118, or 1B119', '["MT1","NP1?","AT1"]', '[]', 'TSR: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to “software” for the “use” of items controlled by 1B101.a -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 1D101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D103', '1', 'D', '“Software” “specially designed” for reduced observables such as radar reflectivity, ultraviolet/infrared signatures and acoustic signatures, for applications usable in rockets, missiles, or unmanned aerial vehicles capable of delivering at least a 500 kg payload to a “range” equal to or greater than 300 km and their complete subsystems', '“Software” “specially designed” for reduced observables such as radar reflectivity, ultraviolet/infrared signatures and acoustic signatures, for applications usable in rockets, missiles, or unmanned aerial vehicles capable of delivering at least a 500 kg payload to a “range” equal to or greater than 300 km and their complete subsystems', '["MT1","AT1"]', '[]', 'TSR: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) This entry includes “software” “specially designed” for analysis of signature reduction. (2) For software that meets the definition of defense articles under 22 CFR 120.3 of the International Traffic in Arms Regulations (ITAR), which describes similar software that are “subject to the ITAR” (see 22 CFR parts 120 through 130, including USML Category XIII).', '15 CFR Part 774, Supplement No. 1, ECCN 1D103 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D201', '1', 'D', '“Software” “specially designed” or modified for the “use” of items controlled by 1B201', '“Software” “specially designed” or modified for the “use” of items controlled by 1B201', '["NP1","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1D201 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D390', '1', 'D', '“Software” for process control that is specifically configured to control or initiate “production” of chemicals controlled by 1C350', '“Software” for process control that is specifically configured to control or initiate “production” of chemicals controlled by 1C350', '["CB2","AT1"]', '[]', 'TSR: N/A', 'CB applies to entire entry -> CB Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1D390 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D607', '1', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of items controlled by 1A607, 1B607 or 1C607', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of items controlled by 1A607, 1B607 or 1C607. Items: a. “Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCN 1A607, 1B607, or 1C607. b. [Reserved]', '["NS1?","RS1","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1D607.', 'NS applies to entire entry, except “software” for 1C607.a.10, .a.11, .a.12, and .a.14 -> NS Column 1.; RS applies to entire entry -> RS Column 1.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', '(1) “Software” directly related to articles enumerated or otherwise described in USML Category XIV is subject to the ITAR (see 22 CFR § 121.1, Category XIV(m)). “Software” controlled by USML Category XIV(m) includes “software” directly related to any equipment containing reagents, algorithms, coefficients, software, libraries, spectral databases, or alarm set point levels developed under U.S. Department of Defense contract or funding for the detection, identification, warning or monitoring of items controlled in paragraphs (a) or (b) of USML Category XIV, or for chemical or biological agents specified by U.S. Department of Defense funding or contract. (2) See ECCN 0A919 for “military commodities” located and produced outside the United States that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1D607 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D608', '1', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 1B608 or 1C608', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 1B608 or 1C608. Items: a. “Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCN 1B608 or 1C608. b. [Reserved]', '["NS1","RS1","MT1?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1D608.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; MT applies to “software” “specially designed” for the “use” of 1B608 equipment in the “production” and handling of materials controlled by 1C608.m or MT articles in USML Category V -> MT Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Software directly related to articles enumerated or otherwise described in USML Categories III, IV or V is subject to the controls of those USML Categories, respectively. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of U.S.-origin “600 series” items.', '15 CFR Part 774, Supplement No. 1, ECCN 1D608 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D613', '1', 'D', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 1A613 or 1B613, as follows', '“Software” “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by 1A613 or 1B613, as follows. Items: a. “Software” (other than “software” controlled in paragraph .y of this entry) “specially designed” for the “development,” “production,” operation, or maintenance of commodities controlled by ECCNs 1A613 (except 1A613.y) or 1B613 (except 1B613.y). b. to x. [Reserved] y. Specific “software” “specially designed” for the “production,” “development,” operation, or maintenance of commodities controlled by ECCN 1A613.y.', '["NS1?","RS1?","RS?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any “software” in 1D613.', 'NS applies to entire entry except 1D613.y -> NS Column 1.; RS applies to entire entry except 1D613.y -> RS Column 1.; RS applies to 1D613.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 1D613.y -> See § 746.1(b) for UN controls.', '(1) “Software” directly related to articles controlled by USML Category X is subject to the control of USML paragraph X(e) of the ITAR. (2) See ECCN 0A919 for foreign-made “military commodities” that incorporate more than a de minimis amount of US-origin “600 series” controlled content.', '15 CFR Part 774, Supplement No. 1, ECCN 1D613 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D993', '1', 'D', '“Software” “specially designed” for the “development,” “production” or “use” of materials controlled by 1C210.b, or 1C990', '“Software” “specially designed” for the “development,” “production” or “use” of materials controlled by 1C210.b, or 1C990', '["AT1"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1D993 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1D999', '1', 'D', 'Specific Software, n.e.s., as Follows', 'Specific Software, n.e.s., as Follows. Items: a. Software “specially designed” for industrial process control hardware/systems controlled by 1B999, n.e.s.; b. Software “specially designed” for equipment for the production of structural composites, fibers, prepregs and preforms controlled by 1B999, n.e.s.', '["AT?"]', '[]', 'TSR: N/A', '', 'See also 1B999.', '15 CFR Part 774, Supplement No. 1, ECCN 1D999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E001', '1', 'E', '“Technology” according to the General Technology Note for the “development” or “production” of items controlled by 1A002, 1A003, 1A004, 1A005, 1A006.b, 1A007, 1A008 1A101, 1A231, 1B (except 1B608, 1B613 or 1B999), or 1C (except 1C355, 1C608, 1C980 to 1C984, 1C988, 1C990, 1C991, 1C995 to 1C999)', '“Technology” according to the General Technology Note for the “development” or “production” of items controlled by 1A002, 1A003, 1A004, 1A005, 1A006.b, 1A007, 1A008 1A101, 1A231, 1B (except 1B608, 1B613 or 1B999), or 1C (except 1C355, 1C608, 1C980 to 1C984, 1C988, 1C990, 1C991, 1C995 to 1C999)', '["NS1?","NS2?","MT1?","NP1?","CB1?","CB2?","RS2?","AT1"]', '["TSR"]', 'TSR: Yes, except for the following: | STA: License Exception STA may not be used to ship or transmit “technology” according to the General Technology Note for the “development” or “production” of equipment and materials specified by ECCNs 1A002, 1C001, 1C007.c, 1C010.c or d or 1C012 to any of the destinations listed in Country Group A:6 (See Supplement No. 1 to part 740 of the EAR).', 'NS applies to “technology” for items controlled by 1A002, 1A003, 1A005, 1A006.b, 1A007, 1B001 to 1B003, 1B018, 1C001 to 1C011, or 1C018 -> NS Column 1.; NS applies to “technology” for items controlled by 1A004 -> NS Column 2.; MT applies to “technology” for items controlled by 1A101, 1B001, 1B101, 1B102, 1B115 to 1B119, 1C001, 1C007, 1C011, 1C101, 1C102, 1C107, 1C111, 1C116, 1C117, or 1C118 for MT reasons -> MT Column 1.; NP applies to “technology” for items controlled by 1A002, 1A007, 1A231, 1B001, 1B101, 1B201, 1B225, 1B226, 1B228 to 1B234, 1C002, 1C010, 1C111, 1C116, 1C202, 1C210, 1C216, 1C225 to 1C237, or 1C239 to 1C241 for NP reasons -> NP Column 1.; CB applies to “technology” for items controlled by 1C351.d.15 and .16 and the 1C353 genetic elements of toxins in ECCN 1C351.d.15 and .16 -> CB Column 1.; CB applies to “technology” for items controlled by 1C351, 1C353, or 1C354; and CB applies to “technology” for materials controlled by 1C350 and for chemical detection systems and dedicated detectors therefor, in 1A004.c, that also have the technical characteristics described in 2B351.a -> CB Column 2.; RS applies to technology for equipment controlled in 1A004.d -> RS Column 2.; AT applies to entire entry -> AT Column 1.', '(1) Also see ECCNs 1E101, 1E201, and 1E202. (2) See ECCN 1E608 for “technology” for items classified under ECCN 1B608 or 1C608 that, immediately prior to July 1, 2014, were classified under ECCN 1B018.a or 1C018.b through .m (note that ECCN 1E001 controls “development” and “production” “technology” for chlorine trifluoride controlled by ECCN 1C111.a.3.f—see ECCN 1E101 for controls on “use” “technology” for chlorine trifluoride). (3) See ECCN 1E002.g for control libraries (parametric technical databases) “specially designed” or modified to enable equipment to perform the functions of equipment controlled under ECCN 1A004.c (Nuclear, biological and chemical (NBC) detection systems) or ECCN 1A004.d (Equipment for detecting or identifying explosives residues). (4) “Technology” for lithium isotope separation (see related ECCN 1B233) and “technology” for items described in ECCN 1C012 are subject to the export licensing authority of the Department of Energy (see 10 CFR part 810). (5) “Technology” for items described in ECCN 1A102 is “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 1E001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E002', '1', 'E', 'Other “technology” as follows', 'Other “technology” as follows. Items: a. “Technology” for the “development” or “production” of polybenzothiazoles or polybenzoxazoles; b. “Technology” for the “development” or “production” of fluoroelastomer compounds containing at least one vinylether monomer; c. “Technology” for the design or “production” of the following ceramic powders or non-“composite” ceramic materials: c.1. Ceramic powders having all of the following: c.1.a. Any of the following compositions: c.1.a.1. Single or complex oxides of zirconium and complex oxides of silicon or aluminum; c.1.a.2. Single nitrides of boron (cubic crystalline forms); c.1.a.3. Single or complex carbides of silicon or boron; or c.1.a.4. Single or complex nitrides of silicon; c.1.b. Any of the following total metallic impurities (excluding intentional additions): c.1.b.1. Less than 1,000 ppm for single oxides or carbides; or c.1.b.2. Less th…', '["NS1?","NS2?","MT1?","NP1?","AT1"]', '["TSR"]', 'TSR: Yes, except for 1E002.e and .f. | STA: License Exception STA may not be used to ship or transmit any item in 1E002.e or .f to any of the destinations listed in Country Group A:6 (See Supplement No. 1 to part 740 of the EAR).', 'NS applies to entire entry, except 1E002.g -> NS Column 1; NS applies to 1E002.g -> NS Column 2; MT applies to 1E002.e -> MT Column 1; NP applies to “technology” for items controlled by 1A002 for NP reasons -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See also 1E001, 1E101,1E102, 1E202, and 1E994 for “technology” related to 1E002.e or .f.', '15 CFR Part 774, Supplement No. 1, ECCN 1E002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E101', '1', 'E', '“Technology”, in accordance with the General Technology Note, for the “use” of commodities and “software” controlled by 1A101, 1A102, 1B001, 1B101, 1B102, 1B115 to 1B119, 1C001, 1C007, 1C011, 1C101, 1C107, 1C111, 1C116, 1C117, 1C118, 1D001, 1D101, or 1D103', '“Technology”, in accordance with the General Technology Note, for the “use” of commodities and “software” controlled by 1A101, 1A102, 1B001, 1B101, 1B102, 1B115 to 1B119, 1C001, 1C007, 1C011, 1C101, 1C107, 1C111, 1C116, 1C117, 1C118, 1D001, 1D101, or 1D103', '["MT1?","NP1?","AT1"]', '[]', 'TSR: N/A', 'MT applies to “technology” for commodities and software controlled by 1A101, 1A102, 1B001, 1B101, 1B102, 1B115 to 1B119, 1C001, 1C007, 1C011, 1C101, 1C107, 1C111, 1C116, 1C117, 1C118, 1D001, 1D101, or 1D103 for MT reasons -> MT Column 1; NP applies to “technology” for items controlled by 1B001, 1B101, 1C111, 1C116, 1D001, or 1D101 for NP reasons -> NP Column 1; AT applies to entire entry -> AT Column 1', '“Technology” for items controlled by 1A102 is “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 1E101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E102', '1', 'E', '“Technology” according to the General Technology Note for the “development” of software controlled by 1D001, 1D101 or 1D103', '“Technology” according to the General Technology Note for the “development” of software controlled by 1D001, 1D101 or 1D103', '["MT1","NP1?","AT1"]', '[]', 'TSR: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to “technology” for items controlled by 1D001 and 1D101 for NP reasons -> NP Column 1.; AT applies to entire entry -> AT Column 1.', 'This entry includes databases “specially designed” for analysis of signature reduction.', '15 CFR Part 774, Supplement No. 1, ECCN 1E102 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E103', '1', 'E', '“Technical data” (including processing conditions) and procedures for the regulation of temperature, pressure or atmosphere in autoclaves or hydroclaves, when used for the “production” of “composites” or partially processed “composites”, usable for equipment or materials specified in 1C007, 1C102, 1C107, 1C116, 1C117, 1C118, 9A110, and 9C110', '“Technical data” (including processing conditions) and procedures for the regulation of temperature, pressure or atmosphere in autoclaves or hydroclaves, when used for the “production” of “composites” or partially processed “composites”, usable for equipment or materials specified in 1C007, 1C102, 1C107, 1C116, 1C117, 1C118, 9A110, and 9C110', '["MT1","AT1"]', '[]', 'TSR: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See also 1E203', '15 CFR Part 774, Supplement No. 1, ECCN 1E103 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E104', '1', 'E', '“Technology” for the “production” of pyrolytically derived materials formed on a mold, mandrel or other substrate from precursor gases which decompose in the 1,573 K (1,300 °C) to 3,173 K (2,900 °C) temperature range at pressures of 130 Pa (1 mm Hg) to 20 kPa (150 mm Hg), including “technology” for the composition of precursor gases, flow-rates and process control schedules and parameters', '“Technology” for the “production” of pyrolytically derived materials formed on a mold, mandrel or other substrate from precursor gases which decompose in the 1,573 K (1,300 °C) to 3,173 K (2,900 °C) temperature range at pressures of 130 Pa (1 mm Hg) to 20 kPa (150 mm Hg), including “technology” for the composition of precursor gases, flow-rates and process control schedules and parameters', '["MT1","AT1"]', '[]', 'TSR: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E104 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E201', '1', 'E', '“Technology” according to the General Technology Note for the “use” of items controlled by 1A002, 1A007, 1A202, 1A225 to 1A227, 1A231, 1B201, 1B225, 1B226, 1B228 to 1B232, 1B233.b, 1B234, 1C002.b.3 and b.4, 1C010.a, 1C010.b, 1C010.e.1, 1C202, 1C210, 1C216, 1C225 to 1C237, 1C239 to 1C241 or 1D201', '“Technology” according to the General Technology Note for the “use” of items controlled by 1A002, 1A007, 1A202, 1A225 to 1A227, 1A231, 1B201, 1B225, 1B226, 1B228 to 1B232, 1B233.b, 1B234, 1C002.b.3 and b.4, 1C010.a, 1C010.b, 1C010.e.1, 1C202, 1C210, 1C216, 1C225 to 1C237, 1C239 to 1C241 or 1D201', '["NP1?","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry, for items controlled for NP reasons -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E201 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E202', '1', 'E', '“Technology” according to the General Technology Note for the “development” or “production” of goods controlled by 1A202 or 1A225 to 1A227', '“Technology” according to the General Technology Note for the “development” or “production” of goods controlled by 1A202 or 1A225 to 1A227', '["NP1","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E202 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E203', '1', 'E', '“Technology” according to the General Technology Note for the “development” or “production” of “software” controlled by 1D201', '“Technology” according to the General Technology Note for the “development” or “production” of “software” controlled by 1D201', '["NP1","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E203 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E350', '1', 'E', '“Technology” according to the “General Technology Note” for facilities designed or intended to produce chemicals controlled by 1C350', '“Technology” according to the “General Technology Note” for facilities designed or intended to produce chemicals controlled by 1C350', '["CB2","AT1"]', '[]', 'TSR: N/A', 'CB applies to entire entry -> CB Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E350 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E351', '1', 'E', '“Technology” according to the “General Technology Note” for the disposal of chemicals or microbiological materials controlled by 1C350, 1C351, 1C353, or 1C354', '“Technology” according to the “General Technology Note” for the disposal of chemicals or microbiological materials controlled by 1C350, 1C351, 1C353, or 1C354', '["CB1?","CB2?","AT1"]', '[]', '', 'CB applies to “technology” for the disposal of items controlled by 1C351.d.15 and .16 and the 1C353 genetic elements of toxins in ECCN 1C351.d.15 and .16 -> CB Column 1.; CB applies to “technology” for the disposal of items controlled by 1C351, 1C353, or 1C354; and CB applies to “technology” for the disposal of items controlled by 1C350 -> CB Column 2.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E351 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E355', '1', 'E', 'Technology for the production of Chemical Weapons Convention (CWC) Schedule 2 and 3 chemicals, as follows ', 'Technology for the production of Chemical Weapons Convention (CWC) Schedule 2 and 3 chemicals, as follows . Items: a. Technology for the production of the following CWC Schedule 2 toxic chemicals: a.1. PFIB: 1,1,3,3,3-Pentafluoro-2-(trifluoromethyl)-1-propene (382-21-8); a.2. [Reserved] b. Technology for the production of the following CWC Schedule 3 toxic chemicals: b.1. Phosgene: Carbonyl dichloride (75-44-5); b.2. Cyanogen chloride (506-77-4); b.3. Hydrogen cyanide (74-90-8).', '["CW?","AT1"]', '[]', 'TSR: N/A', 'CW applies to entire entry. A license is required for CW reasons to CWC non-States Parties (destinations not listed in Supplement No. 2 to part 745), except for Israel and Taiwan. See § 742.18 of the EAR. The Commerce Country Chart is not designed to determine licensing requirements for items controlled for CW reasons; AT applies to the entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E355 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E607', '1', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of items controlled by ECCN 1A607, 1B607, 1C607, or 1D607', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of items controlled by ECCN 1A607, 1B607, 1C607, or 1D607. Items: a. “Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of items controlled by ECCN 1A607, 1B607, 1C607 or 1D607. Note to 1E607.a: ECCN 1E607.a includes “technology” “required” exclusively for the incorporation of “biocatalysts” controlled by ECCN 1C607.c.1 into military carrier substances or military material. b. [Reserved]', '["NS1?","RS1","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1E607.', 'NS applies to entire entry, except “technology” for 1C607.a.10, .a.11, .a.12, and .a.14 and for 1D607 “software” therefor -> NS Column 1.; RS applies to entire entry -> RS Column 1.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry -> See § 746.1(b) for UN controls.', 'Technical data directly related to defense articles enumerated or otherwise described in USML Category XIV are subject to the ITAR (see 22 CFR § 121.1, Category XIV(m)). Technical data controlled by USML Category XIV(m) include technical data directly related to any equipment containing reagents, algorithms, coefficients, software, libraries, spectral databases, or alarm set point levels developed under U.S. Department of Defense contract or funding for the detection, identification, warning or monitoring of items controlled in paragraphs (a) or (b) of USML Category XIV, or for chemical or biological agents specified by U.S. Department of Defense funding or contract.', '15 CFR Part 774, Supplement No. 1, ECCN 1E607 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E608', '1', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of equipment controlled in 1B608 or materials controlled by 1C608', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of equipment controlled in 1B608 or materials controlled by 1C608. Items: a. “Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of equipment controlled by ECCN 1B608 or materials controlled by ECCN 1C608. b. “Technology” “required” for the “development” or “production” of nitrocellulose with nitrogen content over 12.6% and at rates greater than 2000 pounds per hour. c. “Technology” “required” for the “development” or “production” of nitrate esters (e.g., nitroglycerine) at rates greater than 2000 pounds per hour.', '["NS1","RS1","MT1?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any item in 1E608.', 'NS applies to entire entry -> NS Column 1; RS applies to entire entry -> RS Column 1; MT applies to “technology” “required” for 1C608.m -> MT Column 1; AT applies to entire entry -> AT Column 1; UN applies to entire entry -> See § 746.1(b) for UN controls', '(1) Technical data directly related to articles enumerated or otherwise described in USML Categories III, IV, or V are subject to the controls of those USML Categories, respectively.', '15 CFR Part 774, Supplement No. 1, ECCN 1E608 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E613', '1', 'E', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by 1A613 or 1B613 or “software” controlled by 1D613, as follows', '“Technology” “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities controlled by 1A613 or 1B613 or “software” controlled by 1D613, as follows. Items: a. “Technology” (other than “technology” controlled by paragraph .y of this entry) “required” for the “development,” “production,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities or “software” controlled by ECCNs 1A613 (except 1A613.y), 1B613 or 1D613 (except 1D613.y). b. through x. [Reserved] y. Specific “technology” “required” for the “production,” “development,” operation, installation, maintenance, repair, overhaul, or refurbishing of commodities or software controlled by ECCN 1A613.y or 1D613.y.', '["NS1?","RS1?","RS?","AT1","UN?"]', '[]', 'TSR: N/A | STA: Paragraph (c)(2) of License Exception STA (§ 740.20(c)(2) of the EAR) may not be used for any “technology” in 1E613.', 'NS applies to entire entry except 1E613.y -> NS Column 1.; RS applies to entire entry except 1E613.y -> RS Column 1.; RS applies to 1E613.y -> China, Russia, or Venezuela (see § 742.6(a)(7)).; AT applies to entire entry -> AT Column 1.; UN applies to entire entry, except 1E613.y -> See § 746.1(b) for UN controls.', 'Technical data directly related to articles controlled by USML Category X are subject to the control of USML paragraph X(e) of the ITAR.', '15 CFR Part 774, Supplement No. 1, ECCN 1E613 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E994', '1', 'E', '“Technology” for the “development”, “production”, or “use” of fibrous and filamentary materials controlled by 1C990', '“Technology” for the “development”, “production”, or “use” of fibrous and filamentary materials controlled by 1C990', '["AT1"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E994 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('1E998', '1', 'E', '“Technology” for the “development” or “production” of processing equipment controlled by 1B999, and materials controlled by 1C996, 1C997, 1C998, or 1C999', '“Technology” for the “development” or “production” of processing equipment controlled by 1B999, and materials controlled by 1C996, 1C997, 1C998, or 1C999', '["AT1"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 1E998 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A001', '2', 'A', 'Anti-friction bearings, bearing systems and “components,” as follows,', 'Anti-friction bearings, bearing systems and “components,” as follows,. Items: Note: 2A001.a includes ball bearing and roller elements “specially designed” for the items specified therein. a. Ball bearings and solid roller bearings, having all tolerances specified by the manufacturer in accordance with ISO 492 Tolerance Class 2 or Class 4 (or national equivalents), or better, and having both ''rings'' and ''rolling elements'', made from monel or beryllium; Note: 2A001.a does not control tapered roller bearings. Technical Notes: For the purposes of 2A001.a: 1. ''Ring''—is an annular part of a radial rolling bearing incorporating one or more raceways (ISO 5593:1997). 2. ''Rolling element''—is a ball or roller which rolls between raceways (ISO 5593:1997). b. [Reserved] c. Active magnetic bearing systems using any of the following, and “specially designed” components therefor: c.1. Materials with fl…', '["NS2","MT1?","AT1"]', '["LVS"]', 'LVS: $3000, N/A for MT', 'NS applies to entire entry -> NS Column 2; MT applies to radial ball bearings having all tolerances specified in accordance with ISO 492 Tolerance Class 2 (or ANSI/ABMA Std 20 Tolerance Class ABEC-9, or other national equivalents) or better and having all the following characteristics: an inner ring bore diameter between 12 and 50 mm; an outer ring outside diameter between 25 and 100 mm; and a width between 10 and 20 mm. -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) See also 2A991. (2) Quiet running bearings are “subject to the ITAR” (see 22 CFR parts 120 through 130.)', '15 CFR Part 774, Supplement No. 1, ECCN 2A001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A101', '2', 'A', 'Radial Ball Bearings Having all Tolerances Specified in Accordance With ISO 492 Tolerance Class 2 (or ANSI/ABMA Std 20 Tolerance Class ABEC-9 or Other National Equivalents), or Better and Having all of the Following Characteristics', 'Radial Ball Bearings Having all Tolerances Specified in Accordance With ISO 492 Tolerance Class 2 (or ANSI/ABMA Std 20 Tolerance Class ABEC-9 or Other National Equivalents), or Better and Having all of the Following Characteristics. Items: a. An inner ring bore diameter between 12 and 50 mm; b. An outer ring outside diameter between 25 and 100 mm; and c. A width between 10 and 20 mm.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; AT applies to entire entry -> AT Column 1.', 'See ECCN 2A001.', '15 CFR Part 774, Supplement No. 1, ECCN 2A101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A225', '2', 'A', 'Crucibles made of materials resistant to liquid actinide metals', 'Crucibles made of materials resistant to liquid actinide metals. Items: a. Crucibles having both of the following characteristics: a.1. A volume of between 150 cm 3 (150 ml) and 8,000 cm 3 (8 liters); and a.2. Made of, or coated with, any of the following materials, or combination of the following materials, having an overall impurity level of 2% or less by weight: a.2.a. Calcium fluoride (CaF2); a.2.b. Calcium zirconate (metazirconate) (CaZrO3); a.2.c. Cerium sulfide (Ce2S3); a.2.d. Erbium oxide (erbia) (Er2O3); a.2.e. Hafnium oxide (hafnia) (HfO2); a.2.f. Magnesium oxide (MgO); a.2.g. Nitrided niobium-titanium-tungsten alloy (approximately 50% Nb, 30% Ti, 20% W); a.2.h. Yttrium oxide (yttria) (Y2O3); or a.2.i. Zirconium oxide (zirconia) (ZrO2); b. Crucibles having both of the following characteristics: b.1. A volume of between 50 cm 3 (50 ml) and 2,000 cm 3 (2 liters); and b.2. Made o…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2A225 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A226', '2', 'A', 'Valves having all of the following characteristics', 'Valves having all of the following characteristics. Items: a. A “nominal size” of 5 mm or greater; b. Having a bellows seal; and c. Wholly made of or lined with aluminum, aluminum alloy, nickel, or nickel alloy containing more than 60% nickel by weight.', '["NP1","CB2?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1.; CB applies to valves that also meet or exceed the technical parameters in 2B350.g -> CB Column 2.; AT applies to entire entry -> AT Column 1.', '(1) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (2) Also see ECCNs 2A992, 2B350.g and 2B999. (3) Valves “specially designed” or prepared for certain nuclear uses are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2A226 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A290', '2', 'A', 'Generators and other equipment “specially designed”, prepared, or intended for use with nuclear plants', 'Generators and other equipment “specially designed”, prepared, or intended for use with nuclear plants. Items: a. Generators, turbine-generator sets, steam turbines, heat exchangers, and heat exchanger type condensers designed or intended for use in a nuclear reactor; b. Process control systems intended for use with the equipment controlled by 2A290.a.', '["NP2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 2; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D290 for software for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E290 (“use”) for technology for items controlled under this entry. (3) Also see ECCN 2A291. (4) Certain nuclear equipment “specially designed” or prepared for use in nuclear plants is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2A290 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A291', '2', 'A', 'Equipment, except items controlled by 2A290, related to nuclear material handling and processing and to nuclear reactors, and “parts,” “components” and “accessories” therefor', 'Equipment, except items controlled by 2A290, related to nuclear material handling and processing and to nuclear reactors, and “parts,” “components” and “accessories” therefor. Items: a. Process control systems intended for use with nuclear reactors. b. Simulators “specially designed” for “nuclear reactors”. c. Casks that are “specially designed” for transportation of high-level radioactive material and that weigh more than 1,000 kg. d. Commodities, “parts,” “components” and “accessories” “specially designed” or prepared for use with nuclear plants (e.g., snubbers, airlocks, pumps, reactor fuel charging and discharging equipment, containment equipment such as hydrogen recombiner and penetration seals, and reactor and fuel inspection equipment, including ultrasonic or eddy current test equipment). e. Radiation detectors and monitors “specially designed” for detecting or measuring “special…', '["NP2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 2; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D290 for software for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E290 (“use”) for technology for items controlled under this entry. (3) Also see ECCN 2A290. (4) Certain equipment “specially designed” or prepared for use in a nuclear reactor or in nuclear material handling is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110). (5) Nuclear radiation detection and measurement devices “specially designed” or modified for military purposes are “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 2A291 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A983', '2', 'A', 'Explosives or detonator detection equipment, both bulk and trace based, consisting of an automated device, or combination of devices for automated decision making to detect the presence of different types of explosives, explosive residue, or detonators; and “parts” and “components,” n.e.s', 'Explosives or detonator detection equipment, both bulk and trace based, consisting of an automated device, or combination of devices for automated decision making to detect the presence of different types of explosives, explosive residue, or detonators; and “parts” and “components,” n.e.s. Items: Note: Explosives or detonation detection equipment in 2A983 includes equipment for screening people, documents, baggage, other personal effects, cargo and/or mail. a. Explosives detection equipment for automated decision making to detect and identify bulk explosives utilizing, but not limited to, x-ray (e.g., computed tomography, dual energy, or coherent scattering), nuclear (e.g., thermal neutron analysis, pulse fast neutron analysis, pulse fast neutron transmission spectroscopy, and gamma resonance absorption), or electromagnetic techniques (e.g., quadropole resonance and dielectrometry). b.…', '["RS2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'RS applies to entire entry -> RS Column 2; AT applies to entire entry -> AT Column 1', 'Also see 1A004 and 1A995.', '15 CFR Part 774, Supplement No. 1, ECCN 2A983 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A984', '2', 'A', 'Concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution of 0.1 milliradian up to and including 1 milliradian at a standoff distance of 100 meters; and “parts” and “components,” n.e.s', 'Concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution of 0.1 milliradian up to and including 1 milliradian at a standoff distance of 100 meters; and “parts” and “components,” n.e.s', '["RS2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'RS applies to entire entry -> RS Column 2.; AT applies to entire entry -> AT Column 1.', '(1) Concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution less than 0.1 milliradian (a lower milliradian number means a more accurate image resolution) at a standoff distance of 100 meters is “subject to the ITAR” under USML Category XII(c). (2) Concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution greater than 1 milliradian (a higher milliradian number means a less accurate image resolution) at a standoff distance of 100 meters is designated as EAR99. (3) See ECCNs 2D984 and 2E984 for related software and technology controls.', '15 CFR Part 774, Supplement No. 1, ECCN 2A984 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A991', '2', 'A', 'Bearings and bearing systems not controlled by 2A001', 'Bearings and bearing systems not controlled by 2A001. Items: a. Ball bearings or Solid ball bearings, having tolerances specified by the manufacturer in accordance with ABEC 7, ABEC 7P, or ABEC 7T or ISO Standard Class 4 or better (or equivalents) and having any of the following characteristics. a.1. Manufactured for use at operating temperatures above 573 K (300 °C) either by using special materials or by special heat treatment; or a.2. With lubricating elements or “part” or “component” modifications that, according to the manufacturer''s specifications, are “specially designed” to enable the bearings to operate at speeds exceeding 2.3 million DN. b. Solid tapered roller bearings, having tolerances specified by the manufacturer in accordance with ANSI/AFBMA Class 00 (inch) or Class A (metric) or better (or equivalents) and having either of the following characteristics. b.1. With lubric…', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '(1) This entry does not control balls with tolerance specified by the manufacturer in accordance with ISO 3290 as grade 5 or worse. (2) Quiet running bearings are “subject to the ITAR” (see 22 CFR parts 120 through 130).', '15 CFR Part 774, Supplement No. 1, ECCN 2A991 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A992', '2', 'A', 'Piping, fittings and valves made of, or lined with stainless, copper-nickel alloy or other alloy steel containing 10% or more nickel and/or chromium', 'Piping, fittings and valves made of, or lined with stainless, copper-nickel alloy or other alloy steel containing 10% or more nickel and/or chromium. Items: a. Pressure tube, pipe, and fittings of 200 mm (8 in.) or more inside diameter, and suitable for operation at pressures of 3.4 MPa (500 psi) or greater; b. Pipe valves having all of the following characteristics that are not controlled by ECCN 2B350.g: b.1. A pipe size connection of 200 mm (8 in.) or more inside diameter; and b.2. Rated at 10.3 MPa (1,500 psi) or more.', '["RS?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'RS applies to entire entry -> A license is required for items controlled by this entry for export or reexport to Pakistan or transfer within Pakistan for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See § 742.6(a)(12) of the EAR for additional information.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 2A992 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A993', '2', 'A', 'Pumps designed to move molten metals by electromagnetic forces', 'Pumps designed to move molten metals by electromagnetic forces', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D993 for software for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E993 (“use”) for technology for items controlled under this entry. (3) Pumps for use in liquid-metal-cooled reactors are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2A993 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A994', '2', 'A', 'Portable electric generators and “specially designed” “parts” and “components”', 'Portable electric generators and “specially designed” “parts” and “components”', '["AT?"]', '[]', 'LVS: N/A | GBS: N/A', '', 'See also 2D994 and 2E994.', '15 CFR Part 774, Supplement No. 1, ECCN 2A994 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2A999', '2', 'A', 'Specific Processing Equipment, n.e.s., as Follows', 'Specific Processing Equipment, n.e.s., as Follows. Items: a. Bellows sealed valves; b. Reserved.', '["AT?"]', '[]', 'LVS: N/A | GBS: N/A', '', 'See also 2A226, 2B350.', '15 CFR Part 774, Supplement No. 1, ECCN 2A999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse');
INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('2B001', '2', 'B', 'Machine tools and any combination thereof, for removing (or cutting) metals, ceramics or “composites”, which, according to the manufacturer''s technical specifications, can be equipped with electronic devices for “numerical control”; as follows', 'Machine tools and any combination thereof, for removing (or cutting) metals, ceramics or “composites”, which, according to the manufacturer''s technical specifications, can be equipped with electronic devices for “numerical control”; as follows. Items: Note 1: 2B001 does not control special purpose machine tools limited to the manufacture of gears. For such machines, see 2B003. Note 2: 2B001 does not control special purpose machine tools limited to the manufacture of any of the following: a. Crank shafts or cam shafts; b. Tools or cutters; c. Extruder worms; d. Engraved or faceted jewelry parts; or e. Dental prostheses. Note 3: A machine tool having at least two of the three turning, milling or grinding capabilities (e.g., a turning machine with milling capability), must be evaluated against each applicable entry 2B001.a, .b or .c. Note 4: A machine tool having an additive manufacturing…', '["NS2","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2.; NP applies to 2B001.a, .b, .c, and .d, EXCEPT: (1) turning machines under 2B001.a with a capacity no greater than 35 mm diameter; (2) bar machines (Swissturn), limited to machining only bar feed through, if maximum bar diameter is equal to or less than 42 mm and there is no capability of mounting chucks. (Machines may have drilling and/or milling capabilities for machining “parts” or “components” with diameters less than 42 mm); or (3) milling machines under 2B001.b with x-axis travel greater than two meters and overall positioning accuracy according to ISO 230/2 (2006) on the x-axis more (worse) than 22.5 µm. -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 2B002 for optical finishing machines. (2) See ECCNs 2D001 and 2D002 for software for items controlled under this entry. (3) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (4) Also see ECCNs 2B201 and 2B991.', '15 CFR Part 774, Supplement No. 1, ECCN 2B001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B002', '2', 'B', 'Numerically controlled optical finishing machine tools equipped for selective material removal to produce non-spherical optical surfaces having all of the following characteristics', 'Numerically controlled optical finishing machine tools equipped for selective material removal to produce non-spherical optical surfaces having all of the following characteristics. Items: a. Finishing the form to less (better) than 1.0 µm; b. Finishing to a roughness less (better) than 100 nm rms; c. Four or more axes which can be coordinated simultaneously for “contouring control”; and d. Using any of the following processes: d.1. ‘Magnetorheological finishing (MRF)’; d.2. ‘Electrorheological finishing (ERF)’; d.3. ‘Energetic particle beam finishing’; d.4. ‘Inflatable membrane tool finishing’; or d.5. ‘Fluid jet finishing’.', '["NS2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'See also 2B001.', '15 CFR Part 774, Supplement No. 1, ECCN 2B002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B003', '2', 'B', '“Numerically controlled” machine tools, “specially designed” for the shaving, finishing, grinding or honing of hardened (Rc = 40 or more) spur, helical and double-helical gears having all of the following', '“Numerically controlled” machine tools, “specially designed” for the shaving, finishing, grinding or honing of hardened (Rc = 40 or more) spur, helical and double-helical gears having all of the following. Items: a. A pitch diameter exceeding 1,250 mm; b. A face width of 15% of pitch diameter or larger; and c. A finished quality of AGMA 14 or better (equivalent to ISO 1328 class 3).', '["NS2","AT1"]', '["LVS"]', 'LVS: $5,000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'See also 2B993', '15 CFR Part 774, Supplement No. 1, ECCN 2B003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B004', '2', 'B', 'Hot “isostatic presses” having all of the characteristics described in the List of Items Controlled, and “specially designed” “components” and “accessories” therefor', 'Hot “isostatic presses” having all of the characteristics described in the List of Items Controlled, and “specially designed” “components” and “accessories” therefor. Items: a. A controlled thermal environment within the closed cavity and possessing a chamber cavity with an inside diameter of 406 mm or more; and b. Having any of the following: b.1. A maximum working pressure exceeding 207 MPa; b.2. A controlled thermal environment exceeding 1,773 K (1,500 °C); or b.3. A facility for hydrocarbon impregnation and removal of resultant gaseous degradation products. Technical Note: For the purposes of 2B004, the inside chamber dimension is that of the chamber in which both the working temperature and the working pressure are achieved and does not include fixtures. That dimension will be the smaller of either the inside diameter of the pressure chamber or the inside diameter of the insulated…', '["NS2","MT1","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; MT applies to entire entry -> MT Column 1; NP applies to entire entry, except 2B004.b.3 and presses with maximum working pressures below 69 MPa -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D001 for software for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) For “specially designed” dies, molds and tooling, see ECCNs 0B501, 0B602, 0B606, 1B003, 9B004, and 9B009. (4) For additional controls on dies, molds and tooling, see ECCNs 1B101.d, 2B104 and 2B204. (5) Also see ECCNs 2B117 and 2B999.a.', '15 CFR Part 774, Supplement No. 1, ECCN 2B004 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B005', '2', 'B', 'Equipment “specially designed” for the deposition, processing and in-process control of inorganic overlays, coatings and surface modifications, as follows, for substrates specified in column 2, by processes shown in column 1 in the “Materials Processing Table; Deposition Techniques” following 2E003.f , and “specially designed” automated handling, positioning, manipulation and control “components” therefor', 'Equipment “specially designed” for the deposition, processing and in-process control of inorganic overlays, coatings and surface modifications, as follows, for substrates specified in column 2, by processes shown in column 1 in the “Materials Processing Table; Deposition Techniques” following 2E003.f , and “specially designed” automated handling, positioning, manipulation and control “components” therefor. Items: a. Chemical vapor deposition (CVD)“production equipment”having all of the following: a.1. A process modified for one of the following: a.1.a. Pulsating CVD; a.1.b. Controlled nucleation thermal deposition (CNTD); or a.1.c. Plasma enhanced or plasma assisted CVD; and a.2. Having any of the following: a.2.a. Incorporating high vacuum (equal to or less than 0.01 Pa) rotating seals; or a.2.b. Incorporating in situ coating thickness control; b. Ion implantation “production equipment…', '["NS2","AT1"]', '["LVS"]', 'LVS: $1000 | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', '(1) This entry does not control chemical vapor deposition, cathodic arc, sputter deposition, ion plating or ion implantation equipment, “specially designed” for cutting or machining tools. (2) Vapor deposition equipment for the production of filamentary materials are controlled by 1B001 or 1B101. (3) Chemical Vapor Deposition furnaces designed or modified for densification of carbon-carbon composites are controlled by 2B105. (4) See also 2B999.i.', '15 CFR Part 774, Supplement No. 1, ECCN 2B005 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B006', '2', 'B', 'Dimensional inspection or measuring systems, equipment, position feedback units and “electronic assemblies”, as follows', 'Dimensional inspection or measuring systems, equipment, position feedback units and “electronic assemblies”, as follows. Items: a. Computer controlled or “numerically controlled” Coordinate Measuring Machines (CMM), having a three dimensional length (volumetric) maximum permissible error of length measurement (E0,MPE) at any point within the operating range of the machine (i.e., within the length of axes) equal to or less (better) than (1.7 + L/1,000) µm (L is the measured length in mm) according to ISO 10360-2 (2009); Technical Note: For the purposes of 2B006.a, E0,MPE of the most accurate configuration of the CMM specified by the manufacturer (e.g.,best of the following: Probe, stylus length, motion parameters, environment) and with “all compensations available” shall be compared to the 1.7 + L/1,000 µm threshold. b. Linear displacement measuring instruments or systems, linear positio…', '["NS2","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; NP applies to those items in 2B006.a, b.1, b.3, and .c (angular displacement measuring instruments) that meet or exceed the technical parameters in 2B206. -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2D001 and 2D002 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B206 and 2B996.', '15 CFR Part 774, Supplement No. 1, ECCN 2B006 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B007', '2', 'B', '“Robots” having any of the following characteristics described in the List of Items Controlled and “specially designed” controllers and “end-effectors” therefor', '“Robots” having any of the following characteristics described in the List of Items Controlled and “specially designed” controllers and “end-effectors” therefor. Items: a. [Reserved] b. “Specially designed” to comply with national safety standards applicable to potentially explosive munitions environments; Note: 2B007.b does not apply to “robots” “specially designed” for paint-spraying booths. c. “Specially designed” or rated as radiation-hardened to withstand a total radiation dose greater than 5 × 10 3 Gy (silicon) without operational degradation; or Technical Note: The term Gy (silicon) refers to the energy in Joules per kilogram absorbed by an unshielded silicon sample when exposed to ionizing radiation. d. “Specially designed” to operate at altitudes exceeding 30,000 m.', '["NS2","NP1?","AT1"]', '["LVS"]', 'LVS: $5,000, except 2B007.b and .c | GBS: N/A', 'NS applies to entire entry -> NS Column 2; NP applies to equipment that meets or exceeds the criteria in ECCNs 2B207 -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B007 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B008', '2', 'B', '''Compound rotary tables'' and “tilting spindles”, “specially designed” for machine tools, as follows', '''Compound rotary tables'' and “tilting spindles”, “specially designed” for machine tools, as follows. Items: a. [Reserved] b. [Reserved] c. ''Compound rotary tables'' having all of the following: c.1. Designed for machine tools for turning, milling or grinding; and c.2. Two rotary axes designed to be coordinated simultaneously for “contouring control”. Technical Note: For the purposes of 2B008.c, a ''compound rotary table'' is a table allowing the workpiece to rotate and tilt about two non-parallel axes. d. “Tilting spindles” having all of the following: d.1. Designed for machine tools for turning, milling or grinding; and d.2. Designed to be coordinated simultaneously for “contouring control”.', '["NS2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; AT applies to entire entry -> AT Column 1', 'See also 2B998.', '15 CFR Part 774, Supplement No. 1, ECCN 2B008 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B009', '2', 'B', 'Spin-forming machines and flow-forming machines, which, according to the manufacturer''s technical specifications, can be equipped with “numerical control” units or a computer control and having all of the following characteristics', 'Spin-forming machines and flow-forming machines, which, according to the manufacturer''s technical specifications, can be equipped with “numerical control” units or a computer control and having all of the following characteristics. Items: a. Three or more axes which can be coordinated simultaneously for “contouring control”; and b. A roller force more than 60 kN. Technical Note: For the purposes of 2B009, machines combining the function of spin-forming and flow-forming are regarded as flow-forming machines.', '["NS2","MT1?","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NS applies to entire entry -> NS Column 2; MT applies to: spin-forming machines combining the functions of spin-forming and flow-forming; and flow-forming machines that meet or exceed the parameters of 2B009.a and 2B109 -> MT Column 1; NP applies to flow-forming machines, and spin-forming machines capable of flow-forming functions, that meet or exceed the parameters of 2B209 -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D001 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B109 and 2B209 for additional flow-forming machines for MT and NP reasons.', '15 CFR Part 774, Supplement No. 1, ECCN 2B009 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B018', '2', 'B', 'Equipment on the Wassenaar Arrangement Munitions List', 'Equipment on the Wassenaar Arrangement Munitions List', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B018 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B104', '2', 'B', '“Isostatic presses”, other than those controlled by 2B004, having all of the following characteristics', '“Isostatic presses”, other than those controlled by 2B004, having all of the following characteristics. Items: a. Maximum working pressure equal to or greater than 69 MPa; b. Designed to achieve and maintain a controlled thermal environment of 873 K (600 °C) or greater; and c. Possessing a chamber cavity with an inside diameter of 254 mm or greater.', '["MT1","NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 2D101 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B004, 2B204, and 2B117.', '15 CFR Part 774, Supplement No. 1, ECCN 2B104 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B105', '2', 'B', 'Chemical vapor deposition (CVD) furnaces, other than those controlled by 2B005.a, designed or modified for the densification of carbon-carbon composites', 'Chemical vapor deposition (CVD) furnaces, other than those controlled by 2B005.a, designed or modified for the densification of carbon-carbon composites. Items: The list of items controlled in contained in the ECCN heading.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 2D101 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B005, 2B117, 2B226 and 2B227.', '15 CFR Part 774, Supplement No. 1, ECCN 2B105 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B109', '2', 'B', 'Flow-forming machines, other than those controlled by 2B009, as follows', 'Flow-forming machines, other than those controlled by 2B009, as follows. Items: a. Flow-forming machines, usable in the “production” of propulsion components and equipment (e.g., motor cases and interstages) for “missiles”, having all of the following: a.1. Equipped with, or according to the manufacturer''s technical specification are capable of being equipped with, “numerical control” units or a computer control, even when not equipped with such units at delivery; and a.2. More than two axes which can be coordinated simultaneously for “contouring control.” b. “Specially designed” “parts” and “components” for flow-forming machines controlled in 2B009 for MT reasons or 2B109.a. Technical Note: 1. Machines combining the function of spin-forming and flow-forming are for the purpose of 2B109 regarded as flow-forming machines.', '["MT1","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; NP applies to items controlled by this entry that meet or exceed the technical parameters in 2B209 -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D101 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B009 and 2B209.', '15 CFR Part 774, Supplement No. 1, ECCN 2B109 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B116', '2', 'B', 'Vibration test systems and equipment, usable for rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km and their subsystems, and “parts” and “components” therefor, as follows', 'Vibration test systems and equipment, usable for rockets, missiles, or unmanned aerial vehicles capable of achieving a “range” equal to or greater than 300 km and their subsystems, and “parts” and “components” therefor, as follows. Items: a. Vibration test systems employing feedback or closed loop techniques and incorporating a digital controller, capable of vibrating a system at an acceleration equal to or greater than 10 g rms between 20 Hz to 2,000 Hz while imparting forces equal to or greater than 50 kN (11,250 lbs.), measured ‘bare table’; b. Digital controllers, combined with “specially designed” vibration test “software”, with a ‘real-time control bandwidth’ greater than 5 kHz and designed for use with vibration test systems described in 2B116.a; c. Vibration thrusters (shaker units), with or without associated amplifiers, capable of imparting a force equal to or greater than 50…', '["MT1","NP1?","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to electrodynamic vibration test systems in 2B116.a and to all items in 2B116.b, .c, and .d -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 2D101 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 9B106 and 9B990.', '15 CFR Part 774, Supplement No. 1, ECCN 2B116 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B117', '2', 'B', 'Equipment and process controls, other than those controlled by 2B004, 2B005.a, 2B104 or 2B105, designed or modified for the densification and pyrolysis of structural composite rocket nozzles and reentry vehicle nose tips', 'Equipment and process controls, other than those controlled by 2B004, 2B005.a, 2B104 or 2B105, designed or modified for the densification and pyrolysis of structural composite rocket nozzles and reentry vehicle nose tips. Items: The list of items controlled in contained in the ECCN heading.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 2D101 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E101 (“use”) for technology for items controlled under this entry. (3) Also see ECCN s 2B004, 2B005, 2B104, 2B105, and 2B204.', '15 CFR Part 774, Supplement No. 1, ECCN 2B117 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B119', '2', 'B', 'Balancing machines and related equipment, as follows', 'Balancing machines and related equipment, as follows. Items: a. Balancing machines having all of the following characteristics: a.1. Not capable of balancing rotors/assemblies having a mass greater than 3 kg; a.2. Capable of balancing rotors/assemblies at speeds greater than 12,500 rpm; a.3. Capable of correcting unbalance in two planes or more; and a.4. Capable of balancing to a residual specific unbalance of 0.2 g mm per kg of rotor mass. Note: 2B119.a. does not control balancing machines designed or modified for dental or other medical equipment. b. Indicator heads designed or modified for use with machines specified in 2B119.a. Note: Indicator heads are sometimes known as balancing instrumentation.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1.; AT applies to entire entry -> AT Column 1.', 'See also 7B101.', '15 CFR Part 774, Supplement No. 1, ECCN 2B119 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B120', '2', 'B', 'Motion simulators or rate tables (equipment capable of simulating motion), having all of the following characteristics', 'Motion simulators or rate tables (equipment capable of simulating motion), having all of the following characteristics. Items: a. Two or more axes; b. Designed or modified to incorporate sliprings or integrated non-contact devices capable of transferring electrical power, signal information, or both; and c. Having any of the following characteristics: c.1. For any single axis having all of the following: c.1.a. Capable of rates of rotation of 400 degrees/s or more, or 30 degrees/s or less, and c.1.b. A rate resolution equal to or less than 6 degrees/s and an accuracy equal to or less than 0.6 degrees/s; or c.2. Having a worst-case rate stability equal to or better (less) than plus or minus 0.05% averaged over 10 degrees or more; or c.3. A positioning “accuracy” equal to or better than 5 arc-second. Note: 2B120 does not control rotary tables designed or modified for machine tools or for…', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) Rate tables not controlled by 2B120 and providing the characteristics of a positioning table are to be evaluated according to 2B121. (2) Equipment that has the characteristics specified in 2B121, which also meets the characteristics of 2B120 will be treated as equipment specified in 2B120. (3) See also 2B008, 2B121, 7B101 and 7B994.', '15 CFR Part 774, Supplement No. 1, ECCN 2B120 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B121', '2', 'B', 'Positioning tables (equipment capable of precise rotary position in any axis), other than those controlled in 2B120, having all the following characteristics', 'Positioning tables (equipment capable of precise rotary position in any axis), other than those controlled in 2B120, having all the following characteristics. Items: a. Two or more axes; and b. A positioning “accuracy” equal to or better than 5 arc-second. Note: 2B121 does not control rotary tables designed or modified for machine tools or for medical equipment. For controls on machine tool rotary tables see 2B008.', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', '(1) Equipment that has the characteristics specified in 2B121, which also meets the characteristics of 2B120 will be treated as equipment specified in 2B120. (2) See also 2B008, 2B120, 7B101, and 7B994.', '15 CFR Part 774, Supplement No. 1, ECCN 2B121 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B122', '2', 'B', 'Centrifuges capable of imparting accelerations greater than 100 g and designed or modified to incorporate sliprings or integrated non-contact devices capable of transferring electrical power, signal information, or both', 'Centrifuges capable of imparting accelerations greater than 100 g and designed or modified to incorporate sliprings or integrated non-contact devices capable of transferring electrical power, signal information, or both', '["MT1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'MT applies to entire entry -> MT Column 1; AT applies to entire entry -> AT Column 1', 'See also 7B101.', '15 CFR Part 774, Supplement No. 1, ECCN 2B122 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B201', '2', 'B', 'Machine tools, and any combination thereof, other than those controlled by 2B001, for removing or cutting metals, ceramics or “composites,” which, according to manufacturer''s technical specifications, can be equipped with electronic devices for simultaneous “contouring control” in two or more axes', 'Machine tools, and any combination thereof, other than those controlled by 2B001, for removing or cutting metals, ceramics or “composites,” which, according to manufacturer''s technical specifications, can be equipped with electronic devices for simultaneous “contouring control” in two or more axes. Items: Note: 2B201 does not control special purpose machine tools limited to the manufacture of any of the following parts: a. Gears; b. Crank shafts or cam shafts; c. Tools or cutters; d. Extruder worms; Technical Note: The identified positioning accuracy values in this entry are based on ISO 230/2 (2006), which equates to the values based on ISO 230/2 (1988) that are used by the Nuclear Supplier''s Group (NSG). In 2B201.a and .b.1, this results in a change from 6 µm to 4.5 µm. In paragraph .b of the Note to 2B201.b, the resulting change is from 30 µm to 22.5 µm, In 2B201.c, the resulting cha…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2D002 and 2D202 for “software” for items controlled by this entry. “Numerical control” units are controlled by their associated “software”. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B001 and 2B991.', '15 CFR Part 774, Supplement No. 1, ECCN 2B201 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B204', '2', 'B', '“Isostatic presses”, other than those controlled by 2B004 or 2B104, and related equipment, as follows', '“Isostatic presses”, other than those controlled by 2B004 or 2B104, and related equipment, as follows. Items: a. “Isostatic presses” having both of the following characteristics: a.1. Capable of achieving a maximum working pressure of 69 MPa or greater; and a.2. A chamber cavity with an inside diameter in excess of 152 mm; b. Dies, molds and controls, “specially designed” for “isostatic presses” controlled by 2B204.a.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D201 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B004 and 2B104.', '15 CFR Part 774, Supplement No. 1, ECCN 2B204 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B206', '2', 'B', 'Dimensional inspection machines, instruments or systems, other than those described in 2B006, as follows', 'Dimensional inspection machines, instruments or systems, other than those described in 2B006, as follows. Items: Control Notes to ECCN 2B206: (1) Machine tools that can be used as measuring machines are controlled by ECCN 2B206 if they meet or exceed the control parameters specified in this entry for the measuring machine function. (2) The machines described in ECCN 2B206 are controlled by this entry if they exceed the specified control threshold anywhere in their operating range. Technical Note to ECCN 2B206: All parameters of measurement values in this entry represent plus/minus, i.e., not total band. a. Computer controlled or numerically controlled coordinate measuring machines (CMM) with either of the following characteristics: a.1. Having only two axes with a maximum permissible error of length measurement along any axis (one dimension), identified as any combination of E0x MPE, E0…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2D002 and 2D201 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B006 and 2B996.', '15 CFR Part 774, Supplement No. 1, ECCN 2B206 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B207', '2', 'B', '“Robots”, “end-effectors” and control units, other than those controlled by 2B007, as follows', '“Robots”, “end-effectors” and control units, other than those controlled by 2B007, as follows. Items: a. “Robots” or “end-effectors” “specially designed” to comply with national safety standards applicable to handling high explosives (for example, meeting electrical code ratings for high explosives); b. Control units “specially designed” for any of the “robots” or “end-effectors” controlled by 2B207.a.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D201 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B007, 2B225, and 2B997.', '15 CFR Part 774, Supplement No. 1, ECCN 2B207 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B209', '2', 'B', 'Flow forming machines, spin forming machines capable of flow forming functions, other than those controlled by 2B009 or 2B109, and mandrels, as follows', 'Flow forming machines, spin forming machines capable of flow forming functions, other than those controlled by 2B009 or 2B109, and mandrels, as follows. Items: a. Machines having both of the following characteristics: a.1. Three or more rollers (active or guiding); and a.2. According to the manufacturer''s technical specifications, can be equipped with “numerical control” units or a computer control; Note: 2B209.a includes machines that have only a single roller designed to deform metal, plus two auxiliary rollers that support the mandrel, but do not participate directly in the deformation process. b. Rotor-forming mandrels designed to form cylindrical rotors of inside diameter between 75 mm and 650 mm.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCN 2D201 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (3) Also see ECCNs 2B009 and 2B109.', '15 CFR Part 774, Supplement No. 1, ECCN 2B209 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B225', '2', 'B', 'Remote manipulators that can be used to provide remote actions in radiochemical separation operations or hot cells, having either of the following characteristics', 'Remote manipulators that can be used to provide remote actions in radiochemical separation operations or hot cells, having either of the following characteristics. Items: a. A capability of penetrating 0.6 m or more of hot cell wall (through-the-wall operation); or b. A capability of bridging over the top of a hot cell wall with a thickness of 0.6 m or more (over-the-wall operation). Technical Note: Remote manipulators provide translation of human operator actions to a remote operating arm and terminal fixture. They may be of “master/slave” type or operated by joystick or keypad.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (2) Also see ECCNs 2B007 and 2B207. (3) Remote manipulators “specially designed” or prepared for use in fuel reprocessing or for use in a reactor are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2B225 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B226', '2', 'B', 'Controlled atmosphere (vacuum or inert gas) induction furnaces, and power supplies therefor, as follows', 'Controlled atmosphere (vacuum or inert gas) induction furnaces, and power supplies therefor, as follows. Items: a. Furnaces having all of the following characteristics: a.1. Capable of operation above 1,123 K (850 °C); a.2. Induction coils 600 mm or less in diameter; and a.3. Designed for power inputs of 5 kW or more; b. Power supplies, with a specified power output of 5 kW or more, “specially designed” for furnaces controlled by 2B226.a.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (2) Also see ECCN 2B227 and Category 3B.', '15 CFR Part 774, Supplement No. 1, ECCN 2B226 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B227', '2', 'B', 'Vacuum or other controlled atmosphere metallurgical melting and casting furnaces and related equipment, as follows', 'Vacuum or other controlled atmosphere metallurgical melting and casting furnaces and related equipment, as follows. Items: a. Arc remelt and casting furnaces having both of the following characteristics: a.1. Consumable electrode capabilities between 1,000 cm 3 and 20,000 cm 3; and a.2. Capable of operating with melting temperatures above 1,973 K (1,700 °C); b. Electron beam melting furnaces and plasma atomization and melting furnaces, having both of the following characteristics: b.1. A power of 50 kW or greater; and b.2. Capable of operating with melting temperatures above 1,473 K (1,200 °C); c. Computer control and monitoring systems specially configured for any of the furnaces controlled by 2B227.a or .b.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D201 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry. (2) Also see ECCN 2B226.', '15 CFR Part 774, Supplement No. 1, ECCN 2B227 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B228', '2', 'B', 'Rotor fabrication and assembly equipment, rotor straightening equipment, bellows-forming mandrels and dies, as follows', 'Rotor fabrication and assembly equipment, rotor straightening equipment, bellows-forming mandrels and dies, as follows. Items: a. Rotor assembly equipment for assembly of gas centrifuge rotor tube sections, baffles, and end-caps; Note: 2B228.a includes precision mandrels, clamps, and shrink fit machines. b. Rotor straightening equipment for alignment of gas centrifuge rotor tube sections to a common axis; Technical Note: The rotor straightening equipment in 2B228.b normally consists of precision measuring probes linked to a computer that subsequently controls the action of, for example, pneumatic rams used for aligning the rotor tube sections. c. Bellows-forming mandrels and dies for producing single-convolution bellows. Technical Note: In 2B228.c, the bellows have all of the following characteristics: 1. Inside diameter between 75 mm and 650 mm; 2. Length equal to or greater than 12.7…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', 'See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 2B228 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B229', '2', 'B', 'Centrifugal multiplane balancing machines, fixed or portable, horizontal or vertical, as follows', 'Centrifugal multiplane balancing machines, fixed or portable, horizontal or vertical, as follows. Items: a. Centrifugal balancing machines designed for balancing flexible rotors having a length of 600 mm or more and having all of the following characteristics: a.1. Swing or journal diameter greater than 75 mm; a.2. Mass capability of from 0.9 to 23 kg; and a.3. Capable of balancing speed of revolution greater than 5,000 r.p.m.; b. Centrifugal balancing machines designed for balancing hollow cylindrical rotor “parts” or “components” and having all of the following characteristics: b.1. Journal diameter greater than 75 mm; b.2. Mass capability of from 0.9 to 23 kg; b.3. A minimum achievable residual specific unbalance equal to or less than 10 g-mm/kg per plane; and b.4. Belt drive type.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCN 2D201 for “software” for items controlled under this entry. (2) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 2B229 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B230', '2', 'B', 'All types of “pressure transducers” capable of measuring absolute pressures and having all of the characteristics described in this ECCN', 'All types of “pressure transducers” capable of measuring absolute pressures and having all of the characteristics described in this ECCN. Items: a. Pressure sensing elements made of or protected by aluminum, aluminum alloy, aluminum oxide (alumina or sapphire), nickel, nickel alloy with more than 60% nickel by weight, or fully fluorinated hydrocarbon polymers; b. Seals, if any, essential for sealing the pressure sensing element, and in direct contact with the process medium, made of or protected by aluminum, aluminum alloy, aluminum oxide (alumina or sapphire), nickel, nickel alloy with more than 60% nickel by weight, or fully fluorinated hydrocarbon polymers; and c. Either of the following characteristics: c.1. A full scale of less 13 kPa and an “accuracy” of better than ±1% of full scale; or c.2. A full scale of 13 kPa or greater and an “accuracy” of better than ±130 Pa when measuring…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B230 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B231', '2', 'B', 'Vacuum pumps having all of the characteristics described in this ECCN', 'Vacuum pumps having all of the characteristics described in this ECCN. Items: a. Input throat size equal to or greater than 380 mm; b. Pumping speed equal to or greater than 15 m 3/s; and c. Capable of producing an ultimate vacuum better than 13.3 mPa.', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for “technology” for items controlled under this entry. (2) Also see bellows-sealed scroll-type compressors and bellows-sealed scroll-type vacuum pumps controlled under ECCN 2B233. (3) Vacuum pumps “specially designed” or prepared for the separation of uranium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2B231 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B232', '2', 'B', 'High-velocity gun systems (propellant, gas, coil, electromagnetic, and electrothermal types, and other advanced systems) capable of accelerating projectiles to 1.5 km/s or greater', 'High-velocity gun systems (propellant, gas, coil, electromagnetic, and electrothermal types, and other advanced systems) capable of accelerating projectiles to 1.5 km/s or greater', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', 'See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for technology for items controlled under this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 2B232 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B233', '2', 'B', 'Bellows-sealed scroll-type compressors and bellows-sealed scroll-type vacuum pumps having all of the characteristics described in this ECCN', 'Bellows-sealed scroll-type compressors and bellows-sealed scroll-type vacuum pumps having all of the characteristics described in this ECCN. Items: a. Capable of an inlet volume flow rate of 50 m 3/h or greater; b. Capable of a pressure ratio of 2:1 or greater; and c. Having all surfaces that come in contact with the process gas made from any of the following: c.1. Aluminum or aluminum alloy; c.2. Aluminum oxide; c.3. Stainless steel; c.4. Nickel or nickel alloy; c.5. Phosphor bronze; or c.6. Fluoropolymers. Technical Notes: 1. In a scroll compressor or vacuum pump, crescent-shaped pockets of gas are trapped between one or more pairs of intermeshed spiral vanes, or scrolls, one of which moves while the other remains stationary. The moving scroll orbits the stationary scroll; it does not rotate. As the moving scroll orbits the stationary scroll, the gas pockets diminish in size (i.e., th…', '["NP1","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2E001 (“development”), 2E002 (“production”), and 2E201 (“use”) for “technology” for items controlled under this entry. (2) Also see vacuum pumps controlled under ECCN 2B231. (3) Vacuum pumps “specially designed” or prepared for the separation of uranium isotopes are subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2B233 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B350', '2', 'B', 'Chemical manufacturing facilities and equipment, except valves controlled by 2A226, as follows', 'Chemical manufacturing facilities and equipment, except valves controlled by 2A226, as follows. Items: a. Reaction vessels, reactors and prefabricated repair assemblies therefor, as follows: a.1. Reaction vessels or reactors, with or without agitators, with total internal (geometric) volume greater than 0.1 m 3 (100 liters) and less than 20 m 3 (20,000 liters), where all surfaces that come in direct contact with the chemical(s) being processed or contained are made from any of the following materials: a.1.a Alloys with more than 25% nickel and 20% chromium by weight; a.1.b. Nickel or alloys with more than 40% nickel by weight; a.1.c. Fluoropolymers (polymeric or elastomeric materials with more than 35% fluorine by weight); a.1.d. Glass (including vitrified or enameled coating or glass lining); a.1.e. Tantalum or tantalum alloys; a.1.f. Titanium or titanium alloys; a.1.g. Zirconium or zi…', '["CB2","AT1"]', '["LVS"]', 'LVS: $2,000 for all Country Group B destinations, except those also listed under Country Group D:3 (see Supplement No. 1 to part 740 of the EAR). | GBS: N/A', 'CB applies to entire entry -> CB Column 2; AT applies to entire entry -> AT Column 1', 'See also ECCNs 2A226, 2A992, 2A993, 2B231, and 2B999.', '15 CFR Part 774, Supplement No. 1, ECCN 2B350 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B351', '2', 'B', 'Toxic gas monitors and monitoring systems, and their dedicated detecting “parts” and “components” (i.e., detectors, sensor devices, and replaceable sensor cartridges), as follows, except those systems and detectors controlled by ECCN 1A004.c', 'Toxic gas monitors and monitoring systems, and their dedicated detecting “parts” and “components” (i.e., detectors, sensor devices, and replaceable sensor cartridges), as follows, except those systems and detectors controlled by ECCN 1A004.c. Items: a. Designed for continuous operation and usable for the detection of chemical warfare agents or precursor chemicals controlled by 1C350 ''minimum detection limit'' of 0.3 mg/m 3; or b. Designed for the detection of cholinesterase-inhibiting activity. Technical note: The ''minimum detection limit'' of toxic gas monitors or monitoring systems is the lowest detectable concentration of the analyte required to produce a signal greater than three times the standard deviation of the toxic gas monitor''s or monitoring system''s signal when measuring a blank sample. In the case of toxic gas monitors or monitoring systems having a deadband or programmed zer…', '["CB2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'CB applies to entire entry -> CB Column 2.; AT applies to entire entry -> AT Column 1.', 'See ECCN 2D351 for “software” for toxic gas monitors and monitoring systems, and their dedicated detecting “parts” and “components,” controlled by this ECCN. Also see ECCN 1A004, which controls chemical detection systems and “specially designed” “parts” and “components” therefor that are “specially designed” or modified for detection or identification of chemical warfare agents, but not “specially designed” for military use, and ECCN 1A995, which controls certain detection equipment, “parts” and “components” not controlled by ECCN 1A004 or by this ECCN.', '15 CFR Part 774, Supplement No. 1, ECCN 2B351 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B352', '2', 'B', 'Equipment Capable of Use in Handling Biological Materials, as Follows', 'Equipment Capable of Use in Handling Biological Materials, as Follows. Items: a. Containment facilities and related equipment, as follows: a.1. Complete containment facilities at P3 or P4 containment level. Technical Note to 2B352.a.1: P3 or P4 (BL3, BL4, L3, L4) containment levels are as specified in the WHO Laboratory Biosafety Manual (3rd edition, Geneva, 2004). a.2. Equipment designed for fixed installation in containment facilities specified in paragraph a.1 of this ECCN, as follows: a.2.a. Double-door pass-through decontamination autoclaves; a.2.b. Breathing air suit decontamination showers; a.2.c. Mechanical-seal or inflatable-seal walkthrough doors. b. Fermenters and components as follows: b.1. Fermenters capable of cultivation of micro-organisms or of live cells for the production of viruses or toxins, without the propagation of aerosols, having a total internal volume of 20 li…', '["CB2","AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'CB applies to entire entry -> CB Column 2.; AT applies to entire entry -> AT Column 1.', 'See ECCNs 1A004 and 1A995 for protective equipment that is not covered by this entry. Also see ECCN 9A120 for controls on certain “UAV” systems designed or modified to dispense an aerosol and capable of carrying elements of a payload in the form of a particulate or liquid, other than fuel “parts” or “components” of such vehicles, of a volume greater than 20 liters.', '15 CFR Part 774, Supplement No. 1, ECCN 2B352 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B910', '2', 'B', 'Additive manufacturing equipment, designed to produce metal or metal alloy components, having all of the following , and “specially designed” “components” therefor', 'Additive manufacturing equipment, designed to produce metal or metal alloy components, having all of the following , and “specially designed” “components” therefor', '["NS?","RS?","AT1"]', '["IEC"]', 'LVS: N/A | GBS: N/A | IEC: Yes, see § 740.2(a)(22) and § 740.24 of the EAR.', 'NS applies to entire entry -> Worldwide control. See § 742.4(a)(5) and (b)(10) of the EAR.; RS applies to entire entry -> Worldwide control. See § 742.6(a)(10) and (b)(11) of the EAR.; AT applies to entire entry -> AT Column 1.', 'For related “technology” see ECCN 2E910.', '15 CFR Part 774, Supplement No. 1, ECCN 2B910 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B991', '2', 'B', 'Numerical control units for machine tools and “numerically controlled” machine tools, n.e.s', 'Numerical control units for machine tools and “numerically controlled” machine tools, n.e.s. Items: a. “Numerical control” units for machine tools: a.1. Having four interpolating axes that can be coordinated simultaneously for “contouring control;” or a.2. Having two or more axes that can be coordinated simultaneously for “contouring control” and a minimum programmable increment better (less) than 0.001 mm; a.3. “Numerical control” units for machine tools having two, three or four interpolating axes that can be coordinated simultaneously for “contouring control,” and capable of receiving directly (on-line) and processing computer-aided-design (CAD) data for internal preparation of machine instructions; or b. “Motion control boards” “specially designed” for machine tools and having any of the following characteristics: b.1. Interpolation in more than four axes; b.2. Capable of “real-time…', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', 'See also ECCNs 2B001 and 2B201.', '15 CFR Part 774, Supplement No. 1, ECCN 2B991 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B992', '2', 'B', 'Non-“numerically controlled” machine tools for generating optical quality surfaces, and “specially designed” “parts” and “components” therefor', 'Non-“numerically controlled” machine tools for generating optical quality surfaces, and “specially designed” “parts” and “components” therefor. Items: a. Turning machines using a single point cutting tool and having all of the following characteristics: a.1. Slide positioning accuracy less (better) than 0.0005 mm per 300 mm of travel; a.2. Bidirectional slide positioning repeatability less (better) than 0.00025 mm per 300 mm of travel; a.3. Spindle “run out” and “camming” less (better) than 0.0004 mm total indicator reading (TIR); a.4. Angular deviation of the slide movement (yaw, pitch and roll) less (better) than 2 seconds of arc, TIR, over full travel; and a.5. Slide perpendicularity less (better) than 0.001 mm per 300 mm of travel; Technical Note: The bidirectional slide positioning repeatability (R) of an axis is the maximum value of the repeatability of positioning at any position…', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B992 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B993', '2', 'B', 'Gearmaking and/or finishing machinery not controlled by 2B003 capable of producing gears to a quality level of better than AGMA 11', 'Gearmaking and/or finishing machinery not controlled by 2B003 capable of producing gears to a quality level of better than AGMA 11', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B993 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B996', '2', 'B', 'Dimensional inspection or measuring systems or equipment not controlled by 2B006 or 2B206, as follows', 'Dimensional inspection or measuring systems or equipment not controlled by 2B006 or 2B206, as follows. Items: a. Manual dimensional inspection machines, having both of the following characteristics: a.1. Two or more axes; and a.2. A measurement uncertainty equal to or less (better) than (3 + L/300) micrometer in any axes (L measured length in mm).', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B996 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B997', '2', 'B', '“Robots” not controlled by 2B007 or 2B207 that are capable of employing feedback information in real-time processing from one or more sensors to generate or modify “programs” or to generate or modify numerical program data', '“Robots” not controlled by 2B007 or 2B207 that are capable of employing feedback information in real-time processing from one or more sensors to generate or modify “programs” or to generate or modify numerical program data', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2B997 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse');
INSERT INTO eccn_entries (eccn, category, product_group, title, description, reasons_for_control, license_exceptions, license_exceptions_text, control_text, related_controls, citation, source_url, source_tier, last_updated, origin) VALUES
('2B998', '2', 'B', 'Assemblies, circuit boards or inserts “specially designed” for machine tools controlled by 2B991, or for equipment controlled by 2B993, 2B996 or 2B997', 'Assemblies, circuit boards or inserts “specially designed” for machine tools controlled by 2B991, or for equipment controlled by 2B993, 2B996 or 2B997. Items: a. Spindle assemblies, consisting of spindles and bearings as a minimal assembly, with radial (“run out”) or axial (“camming”) axis motion in one revolution of the spindle less (better) than 0.0006 mm total indicator reading (TIR); b. Single point diamond cutting tool inserts, having all of the following characteristics: b.1. Flawless and chip-free cutting edge when magnified 400 times in any direction; b.2. Cutting radius from 0.1 to 5 mm inclusive; and b.3. Cutting radius out-of-roundness less (better) than 0.002 mm TIR. c. “Specially designed” printed circuit boards with mounted “parts” or “components” capable of upgrading, according to the manufacturer''s specifications, “numerical control” units, machine tools or feed-back dev…', '["AT1"]', '[]', 'LVS: N/A | GBS: N/A', 'AT applies to entire entry -> AT Column 1', 'This entry does not control measuring interferometer systems, without closed or open loop feedback, containing a laser to measure slide movement errors of machine-tools, dimensional inspection machines or similar equipment.', '15 CFR Part 774, Supplement No. 1, ECCN 2B998 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2B999', '2', 'B', 'Specific Processing Equipment, n.e.s., as Follows', 'Specific Processing Equipment, n.e.s., as Follows. Items: a. Isostatic presses, n.e.s. b. Bellows manufacturing equipment, including hydraulic forming equipment and bellows forming dies. c. Laser welding machines. d. MIG welders. e. E-beam welders. f. Monel equipment, including valves, piping, tanks and vessels. g. 304 and 316 stainless steel valves, piping, tanks and vessels. Note: Fittings are considered part of “piping” for purposes of 2B999.g. h. Mining and drilling equipment, as follows: h.1. Large boring equipment capable of drilling holes greater than two feet in diameter. h.2. Large earth-moving equipment used in the mining industry. i. Electroplating equipment designed for coating parts with nickel or aluminum. j. Pumps designed for industrial service and for use with an electrical motor of 5 HP or greater. k. Vacuum valves, piping, flanges, gaskets and related equipment “speci…', '["RS?","AT?"]', '[]', 'LVS: N/A | GBS: N/A', 'RS applies to entire entry except 2B999.h.2 -> A license is required for items controlled by this entry, other than 2B999.h.2, for export or reexport to Pakistan or transfer within Pakistan for regional stability reasons. The Commerce Country Chart is not designed to determine RS license requirements for this entry. See § 742.6(a)(12) of the EAR for additional information.; AT applies to entire entry -> A license is required for items controlled by this entry to North Korea for anti-terrorism reasons. The Commerce Country Chart is not designed to determine AT licensing requirements for this entry. See § 742.19 of the EAR for additional information.', '(1) See also 1B233, 2A992, 2A993, 2B001.f, 2B004, 2B009, 2B104, 2B109, 2B204, 2B209, 2B228, 2B229, 2B231, and 2B350. (2) Certain nuclear related processing equipment is subject to the export licensing authority of the Nuclear Regulatory Commission (see 10 CFR part 110).', '15 CFR Part 774, Supplement No. 1, ECCN 2B999 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D001', '2', 'D', '“Software”, other than that controlled by 2D002, as follows', '“Software”, other than that controlled by 2D002, as follows. Items: a. “Software” “specially designed” or modified for the “development” or “production” of equipment controlled by 2A001 or 2B001 to 2B009; b. “Software” “specially designed” or modified for the “use” of equipment specified by 2A001.c., 2B001, or 2B003 to 2B009. Note: 2D001 does not apply to part programming “software” that generates “numerical control” codes for machining various parts.', '["NS1","MT1?","NP1?","AT1"]', '["TSR"]', 'TSR: Yes, except N/A for MT | STA: License Exception STA may not be used to ship or transmit “software”, other than that specified by ECCN 2D002, “specially designed” for the “development” or “production” of equipment as follows: ECCN 2B001 entire entry; or “Numerically controlled” or manual machine tools as specified in 2B003 to any of the destinations listed in Country Group A:6 (See Supplement No. 1 to part 740 of the EAR).', 'NS applies to entire entry -> NS Column 1; MT applies to “software” for equipment controlled by 2B004 and 2B009 for MT reasons -> MT Column 1; NP applies to “specially designed” or modified “software” for equipment controlled by 2B001 for NP reasons, and to “specially designed” “software” for equipment controlled by 2B004, 2B006, 2B007, or 2B009 for NP reasons -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2E001 (“development”) and 2E101 (“use”) for technology for “software” controlled under this entry. (2) Also see ECCNs 2D101 and 2D201.', '15 CFR Part 774, Supplement No. 1, ECCN 2D001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D002', '2', 'D', '“Software” for electronic devices, even when residing in an electronic device or system, enabling such devices or systems to function as a “numerical control” unit, capable of coordinating simultaneously more than 4 axes for “contouring control”', '“Software” for electronic devices, even when residing in an electronic device or system, enabling such devices or systems to function as a “numerical control” unit, capable of coordinating simultaneously more than 4 axes for “contouring control”', '["NS1","NP1","AT1"]', '["TSR"]', 'TSR: Yes', 'NS applies to entire entry -> NS Column 1.; NP applies to entire entry -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCNs 2E001 (“development”) and 2E201 (“use”) for technology for “software” controlled under this entry. (2) Also see ECCN 2D202.', '15 CFR Part 774, Supplement No. 1, ECCN 2D002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D003', '2', 'D', '“Software”, designed or modified for the operation of equipment specified by 2B002, that converts optical design, workpiece measurements and material removal functions into “numerical control” commands to achieve the desired workpiece form', '“Software”, designed or modified for the operation of equipment specified by 2B002, that converts optical design, workpiece measurements and material removal functions into “numerical control” commands to achieve the desired workpiece form', '["NS2","AT1"]', '["TSR"]', 'TSR: Yes.', 'NS applies to entire entry -> NS Column 2.; AT applies to entire entry -> AT Column 1.', 'See ECCN 2E001 (“development”) for technology for “software” controlled under this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 2D003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D018', '2', 'D', '“Software” for the “development,” “production,” or “use” of equipment controlled by 2B018', '“Software” for the “development,” “production,” or “use” of equipment controlled by 2B018', '["VERIFY"]', '[]', '', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D018 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D101', '2', 'D', '“Software” “specially designed” or modified for the “use” of equipment controlled by 2B104, 2B105, 2B109, 2B116, 2B117, or 2B119 to 2B122', '“Software” “specially designed” or modified for the “use” of equipment controlled by 2B104, 2B105, 2B109, 2B116, 2B117, or 2B119 to 2B122', '["MT1","NP1?","AT1"]', '[]', 'TSR: N/A', 'MT applies to entire entry -> MT Column 1.; NP applies to “software” “specially designed” for the use” of items controlled by 2B104, 2B109, or 2B116 for NP reasons -> NP Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See ECCNs 2E001 (“development”) and 2E101 (“use”) for technology for “software” controlled under this entry. (2) Also see ECCN 9D004.', '15 CFR Part 774, Supplement No. 1, ECCN 2D101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D201', '2', 'D', '“Software” “specially designed” or modified for the “use” of equipment controlled by 2B204, 2B206, 2B207, 2B209, 2B227, or 2B229', '“Software” “specially designed” or modified for the “use” of equipment controlled by 2B204, 2B206, 2B207, 2B209, 2B227, or 2B229', '["NP1","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '(1) See ECCNs 2E001 (“development”) and 2E201 (“use”) for technology for “software” controlled under this entry. (2) Also see ECCNs 2D002 and 2D202.', '15 CFR Part 774, Supplement No. 1, ECCN 2D201 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D202', '2', 'D', '“Software” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 2B201', '“Software” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 2B201', '["NP1","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 1; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D202 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D290', '2', 'D', '“Software” “specially designed” or modified for the “development,” “production,” or “use” of items controlled by 2A290 or 2A291', '“Software” “specially designed” or modified for the “development,” “production,” or “use” of items controlled by 2A290 or 2A291', '["NP2","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 2; AT applies to entire entry -> AT Column 1', 'See ECCN 2E001 (“development”) for technology for “software” controlled under this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 2D290 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D351', '2', 'D', 'Dedicated “software” for toxic gas monitors and monitoring systems, and their dedicated detecting “parts” and “components,” controlled by ECCN 2B351', 'Dedicated “software” for toxic gas monitors and monitoring systems, and their dedicated detecting “parts” and “components,” controlled by ECCN 2B351', '["CB2","AT1"]', '[]', 'TSR: N/A', 'CB applies to entire entry -> CB Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D351 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D352', '2', 'D', '“Software” designed for nucleic acid assemblers and synthesizers controlled by 2B352.j that is capable of designing and building functional genetic elements from digital sequence data', '“Software” designed for nucleic acid assemblers and synthesizers controlled by 2B352.j that is capable of designing and building functional genetic elements from digital sequence data', '["CB2","AT1"]', '[]', 'TSR: N/A', 'CB applies to entire entry -> CB Column 2.; AT applies to entire entry -> AT Column 1.', 'See ECCN 1E001 for “development” or “production “technology” for genetic elements controlled by ECCN 1C353.', '15 CFR Part 774, Supplement No. 1, ECCN 2D352 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D910', '2', 'D', '“Software”, not specified elsewhere, “specially designed” or modified for the “development” or “production” of equipment specified in ECCN 2B910', '“Software”, not specified elsewhere, “specially designed” or modified for the “development” or “production” of equipment specified in ECCN 2B910', '["NS?","RS?","AT1"]', '["IEC"]', 'TSR: N/A | IEC: Yes, see § 740.2(a)(22) and § 740.24 of the EAR. | STA: License Exception STA may not be used to ship any item in this ECCN to any of the destinations listed in Country Group A:5 or A:6 (See Supplement No. 1 to part 740 of the EAR).', 'NS applies to entire entry -> Worldwide control. See § 742.4(a)(5) and (b)(10) of the EAR.; RS applies to entire entry -> Worldwide control. See § 742.6(a)(10) and (b)(11) of the EAR.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D910 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D983', '2', 'D', '“Software” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 2A983', '“Software” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 2A983', '["RS2","AT1"]', '[]', 'TSR: N/A', 'RS applies to entire entry -> RS Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D983 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D984', '2', 'D', '“Software” “required” for the “development”, “production” or “use” of concealed object detection equipment controlled by 2A984', '“Software” “required” for the “development”, “production” or “use” of concealed object detection equipment controlled by 2A984', '["RS2","AT1"]', '[]', 'TSR: N/A', 'RS applies to entire entry -> RS Column 2.; AT applies to entire entry -> AT Column 1.', '(1) “Software” “required” for the “development,” “production” or “use” of concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution less than 0.5 milliradian (a lower milliradian number means a more accurate image resolution) at a standoff distance of 100 meters is “subject to the ITAR” (see 22 CFR parts 120 through 130). (2) “Software” “required” for the “development”, “production” or “use” of concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution greater than 1 milliradian spatial resolution (a higher milliradian number means a less accurate image resolution) at a standoff distance of 100 meters is designated as EAR99. (3) See ECCNs 2A984 and 2E984 for related commodity and technology controls.', '15 CFR Part 774, Supplement No. 1, ECCN 2D984 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D991', '2', 'D', '“Software” “specially designed” for the “development”, “production”, or “use” of equipment controlled by 2B991, 2B993, or 2B996, 2B997, and 2B998', '“Software” “specially designed” for the “development”, “production”, or “use” of equipment controlled by 2B991, 2B993, or 2B996, 2B997, and 2B998', '["AT1"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D991 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D992', '2', 'D', 'Specific “software”, as follows', 'Specific “software”, as follows. Items: a. “Software” to provide “adaptive control” and having both of the following characteristics: a.1. For “flexible manufacturing units” (FMUs) which consist at least of equipment described in b.1 and b.2 of the definition of “flexible manufacturing unit” contained in part 772 of the EAR; and a.2. Capable of generating or modifying, in “real-time processing”, programs or data by using the signals obtained simultaneously by means of at least two detection techniques, such as: a.2.a. Machine vision (optical ranging); a.2.b. Infrared imaging; a.2.c. Acoustical imaging (acoustical ranging); a.2.d. Tactile measurement; a.2.e. Inertial positioning; a.2.f. Force measurement; and a.2.g. Torque measurement. Note: 2D992.a does not control “software” which only provides rescheduling of functionally identical equipment within “flexible manufacturing units” using…', '["AT1"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D992 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D993', '2', 'D', '“Software” “specially designed” or modified for the “development,” “production,” or “use” of items controlled by 2A992 or 2A993', '“Software” “specially designed” or modified for the “development,” “production,” or “use” of items controlled by 2A992 or 2A993', '["AT1"]', '[]', 'TSR: N/A', 'AT applies to entire entry -> AT Column 1', 'See ECCN 2E001 (“development”) for “technology” for “software” controlled under this entry.', '15 CFR Part 774, Supplement No. 1, ECCN 2D993 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2D994', '2', 'D', '“Software” “specially designed” for the “development” or “production” of portable electric generators controlled by 2A994', '“Software” “specially designed” for the “development” or “production” of portable electric generators controlled by 2A994', '["AT?"]', '[]', 'TSR: N/A', '', '', '15 CFR Part 774, Supplement No. 1, ECCN 2D994 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E001', '2', 'E', '“Technology” according to the General Technology Note for the “development” of equipment or “software” controlled by 2A (except 2A983, 2A984, 2A991, or 2A994), 2B (except 2B991, 2B993, 2B996, 2B997, 2B998, or 2B999), or 2D (except 2D983, 2D984, 2D991, 2D992, or 2D994)', '“Technology” according to the General Technology Note for the “development” of equipment or “software” controlled by 2A (except 2A983, 2A984, 2A991, or 2A994), 2B (except 2B991, 2B993, 2B996, 2B997, 2B998, or 2B999), or 2D (except 2D983, 2D984, 2D991, 2D992, or 2D994)', '["NS1?","MT1?","NP1?","NP2?","CB2?","AT1"]', '[]', '', 'NS applies to “technology” for items controlled by 2A001, 2B001 to 2B009, 2D001 or 2D002 -> NS Column 1.; MT applies to “technology” for items controlled by 2B004, 2B009, 2B104, 2B105, 2B109, 2B116, 2B117, 2B119 to 2B122, 2D001, or 2D101 for MT reasons -> MT Column 1.; NP applies to “technology” for items controlled by 2A225, 2A226, 2B001, 2B004, 2B006, 2B007, 2B009, 2B104, 2B109, 2B116, 2B201, 2B204, 2B206, 2B207, 2B209, 2B225 to 2B233, 2D001, 2D002, 2D101, 2D201, or 2D202 for NP reasons -> NP Column 1.; NP applies to “technology” for items controlled by 2A290, 2A291, or 2D290 for NP reasons -> NP Column 2.; CB applies to “technology” for equipment controlled by 2B350 to 2B352, valves controlled by 2A226 having the characteristics of those controlled by 2B350.g, and software controlled by 2D351 or 2D352 -> CB Column 2.; AT applies to entire entry -> AT Column 1.', 'See also 2E101, 2E201, and 2E301', '15 CFR Part 774, Supplement No. 1, ECCN 2E001 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E002', '2', 'E', '“Technology” according to the General Technology Note for the “production” of equipment controlled by 2A (except 2A983, 2A984, 2A991, or 2A994), or 2B (except 2B991, 2B993, 2B996, 2B997, 2B998, or 2B999)', '“Technology” according to the General Technology Note for the “production” of equipment controlled by 2A (except 2A983, 2A984, 2A991, or 2A994), or 2B (except 2B991, 2B993, 2B996, 2B997, 2B998, or 2B999)', '["NS1?","MT1?","NP1?","NP2?","CB2?","AT1"]', '["TSR"]', 'TSR: Yes, except N/A for MT | STA: License Exception STA may not be used to ship or transmit “technology” according to the General Technology Note for the “production” of equipment as follows: ECCN 2B001 entire entry; or “Numerically controlled” or manual machine tools as specified in 2B003 to any of the destinations listed in Country Group A:6 (See Supplement No. 1 to part 740 of the EAR).', 'NS applies to “technology” for equipment controlled by 2A001, 2B001 to 2B009 -> NS Column 1; MT applies to “technology” for equipment controlled by 2B004, 2B009, 2B104, 2B105, 2B109, 2B116, 2B117, or 2B119 to 2B122 for MT reasons -> MT Column 1; NP applies to “technology” for equipment controlled by 2A225, 2A226, 2B001, 2B004, 2B006, 2B007, 2B009, 2B104, 2B109, 2B116, 2B201, 2B204, 2B206, 2B207, 2B209, 2B225 to 2B233 for NP reasons -> NP Column 1; NP applies to “technology” for equipment controlled by 2A290 or 2A291 for NP reasons -> NP Column 2; CB applies to “technology” for equipment Controlled by 2B350 to 2B352 and for valves controlled by 2A226 having the characteristics of those controlled by 2B350.g -> CB Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E002 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E003', '2', 'E', 'Other “technology”, as follows', 'Other “technology”, as follows. Items: a. [Reserved] b. “Technology” for metal-working manufacturing processes, as follows: b.1. “Technology” for the design of tools, dies or fixtures “specially designed” for any of the following processes: b.1.a. “Superplastic forming”; b.1.b. “Diffusion bonding”; or b.1.c. ''Direct-acting hydraulic pressing''; b.2. [Reserved] N.B.: For “technology” for metal-working manufacturing processes for gas turbine engines and components, see 9E003 and USML Category XIX. Technical Note: For the purposes of 2E003.b.1.c, ''direct-acting hydraulic pressing'' is a deformation process which uses a fluid-filled flexible bladder in direct contact with the workpiece. c. “Technology” for the “development” or “production” of hydraulic stretch-forming machines and dies therefor, for the manufacture of airframe structures; d. [Reserved] e. “Technology” for the “development” of…', '["NS1","AT1"]', '["TSR"]', 'TSR: Yes, except 2E003.b, .e and .f', 'NS applies to entire entry -> NS Column 1.; AT applies to entire entry -> AT Column 1.', '(1) See 2E001, 2E002, and 2E101 for “development” and “use” technology for equipment that are designed or modified for densification of carbon-carbon composites, structural composite rocket nozzles and reentry vehicle nose tips. (2) See 2E903 for “technology”, not specified elsewhere, for the “development” or “production” of coating systems (as defined in 2E903).', '15 CFR Part 774, Supplement No. 1, ECCN 2E003 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E018', '2', 'E', '“Technology” for the “use” of equipment controlled by 2B018', '“Technology” for the “use” of equipment controlled by 2B018', '["NS1","MT1?","AT1","UN?"]', '[]', '', 'NS applies to entire entry -> NS Column 1.; MT applies to “technology” for equipment controlled by 2B018 for MT reasons -> MT Column 1.; AT applies to entire entry -> AT Column 1.; UN applies to entire entry. -> See § 746.1(b) for UN controls.', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E018 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E101', '2', 'E', '“Technology” according to the General Technology Note for the “use” of equipment or “software” controlled by 2B004, 2B009, 2B104, 2B105, 2B109, 2B116, 2B117, 2B119 to 2B122, 2D001, 2D002 or 2D101', '“Technology” according to the General Technology Note for the “use” of equipment or “software” controlled by 2B004, 2B009, 2B104, 2B105, 2B109, 2B116, 2B117, 2B119 to 2B122, 2D001, 2D002 or 2D101', '["MT1?","NP1?","AT1"]', '[]', 'TSR: N/A', 'MT applies to “technology” for items controlled by 2B004, 2B009, 2B104, 2B105, 2B109, 2B116, 2B117, 2B119 to 2B122, 2D001, or 2D101 for MT reasons -> MT Column 1; NP applies to “technology” for items controlled by 2B004, 2B009, 2B104, 2B109, 2B116, 2D001, 2D002 or 2D101 for NP reasons -> NP Column 1; AT applies to entire entry. -> AT Column 1', '(1) This entry controls only “technology” for 2B009 and 2B109 for spin forming machines combining the functions of spin forming and flow forming, and flow forming machines. (2) Also see 2E201.', '15 CFR Part 774, Supplement No. 1, ECCN 2E101 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E201', '2', 'E', '“Technology” according to the General Technology Note for the “use” of equipment or “software” controlled by 2A225, 2A226, 2B001, 2B006, 2B007.b, 2B007.c, 2B201, 2B204, 2B206, 2B207, 2B209, 2B225 to 2B233, 2D002, 2D201 or 2D202 for NP reasons', '“Technology” according to the General Technology Note for the “use” of equipment or “software” controlled by 2A225, 2A226, 2B001, 2B006, 2B007.b, 2B007.c, 2B201, 2B204, 2B206, 2B207, 2B209, 2B225 to 2B233, 2D002, 2D201 or 2D202 for NP reasons', '["NP1","CB2?","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 1.; CB applies to “technology” for valves controlled by 2A226 that meet or exceed the technical parameters in 2B350.g -> CB Column 2.; AT applies to entire entry -> AT Column 1.', 'Also see 2E290 and 2E991.', '15 CFR Part 774, Supplement No. 1, ECCN 2E201 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E290', '2', 'E', '“Technology” according to the General Technology Note for the “use” of equipment controlled by 2A290 or 2A291', '“Technology” according to the General Technology Note for the “use” of equipment controlled by 2A290 or 2A291', '["NP2","AT1"]', '[]', 'TSR: N/A', 'NP applies to entire entry -> NP Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E290 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E301', '2', 'E', '“Technology” according to the “General Technology Note” for the “use” of items controlled by 2B350, 2B351 and 2B352', '“Technology” according to the “General Technology Note” for the “use” of items controlled by 2B350, 2B351 and 2B352. Items: The lists of items controlled are contained in the ECCN headings.', '["CB2","AT1"]', '[]', 'TSR: N/A', 'CB applies to entire entry -> CB Column 2.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E301 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E903', '2', 'E', '“Technology”, not specified elsewhere, for the “development” or “production” of ''coating systems'' having all of the following', '“Technology”, not specified elsewhere, for the “development” or “production” of ''coating systems'' having all of the following. Items: a. Designed to protect ceramic “matrix” “composite” materials specified by ECCN 1C007 from corrosion; and b. Designed to operate at temperatures exceeding 1,373.15 K (1,100 °C). Technical Note: For the purposes of 2E903, ''coating systems'' consist of one or more layers (e.g., bond, interlayer, top coat) of material deposited on the substrate.', '["NS?","RS?","AT1"]', '["IEC"]', 'TSR: N/A | IEC: Yes, see § 740.2(a)(22) and § 740.24 of the EAR. | STA: License Exception STA may not be used to ship any item in this ECCN to any of the destinations listed in Country Group A:5 or A:6 (See Supplement No.1 to part 740 of the EAR).', 'NS applies to entire entry -> Worldwide control. See § 742.4(a)(5) and (b)(10) of the EAR.; RS applies to entire entry -> Worldwide control. See § 742.6(a)(10) and (b)(11) of the EAR.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E903 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E910', '2', 'E', '“Technology”, not specified elsewhere, “specially designed” or modified for the “development” or “production” of equipment specified in ECCN 2B910', '“Technology”, not specified elsewhere, “specially designed” or modified for the “development” or “production” of equipment specified in ECCN 2B910', '["NS?","RS?","AT1"]', '["IEC"]', 'TSR: N/A | IEC: Yes, see § 740.2(a)(22) and § 740.24 of the EAR. | STA: License Exception STA may not be used to ship any item in this ECCN to any of the destinations listed in Country Group A:5 or A:6 (See Supplement No.1 to part 740 of the EAR).', 'NS applies to entire entry -> Worldwide control. See § 742.4(a)(5) and (b)(10) of the EAR.; RS applies to entire entry -> Worldwide control. See § 742.6(a)(10) and (b)(11) of the EAR.; AT applies to entire entry -> AT Column 1.', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E910 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E983', '2', 'E', '“Technology” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 2A983, or the “development” of software controlled by 2D983', '“Technology” “specially designed” or modified for the “development”, “production” or “use” of equipment controlled by 2A983, or the “development” of software controlled by 2D983', '["RS2","AT1"]', '[]', 'TSR: N/A', 'RS applies to entire entry -> RS Column 2; AT applies to entire entry -> AT Column 1', '', '15 CFR Part 774, Supplement No. 1, ECCN 2E983 (eCFR text as of 2026-11-19)', 'https://www.ecfr.gov/current/title-15/subtitle-B/chapter-VII/subchapter-C/part-774/appendix-Supplement%20No.%201%20to%20Part%20774', 1, '2026-11-19', 'ecfr_parse'),
('2E984', '2', 'E', '“Technology” “required” for the “development”, “production” or “use” of equipment controlled by 2A984 or “required” for the “development” of “software” controlled by 2D984', '“Technology” “required” for the “development”, “production” or “use” of equipment controlled by 2A984 or “required” for the “development” of “software” controlled by 2D984', '["RS2","AT1"]', '[]', 'TSR: N/A', 'RS applies to entire entry -> RS Column 2.; AT applies to entire entry -> AT Column 1.', '(1) “Technology” “required” for the “development,” “production” or “use” of concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution less than 0.5 milliradian (a lower milliradian number means a more accurate image resolution) at a standoff distance of 100 meters or “required” for the “development” of “software” “required” for the “development,” “production” or “use” of concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution less than 0.5 milliradian at a standoff distance of 100 meters is “subject to the ITAR” (see 22 CFR parts 120 through 130). (2) “Technology” “required” for the “development”, “production” or “use” of concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution greater than 1 milliradian spatial resolution (a higher milliradian number means a less accurate image resolution) at a standoff distance of 100 meters or “required” for the “development” of “software” “required” for the “development”, “production” or “use” of concealed object detection equipment operating in the frequency range from 30 GHz to 3000 GHz and having a spatial resolution greater than 1 milliradian spatial resolution (a higher milliradian number means a less accurate image resolution) at a standoff distance of 100 meters is designated as EAR99. (3) See ECCNs 2A984 and 2D984 for related…', '1