-- Commerce Control List (15 CFR Part 774 Supp. No. 1), part 1 of 1. eCFR text as of 2026-11-19, last amended 2026-11-19.
-- Generated by scripts/build-ccl.ts (636 ECCNs; the hand-verified ones from 0032 keep their reasons, exceptions and description). Summaries are not regulatory text.
-- A trailing "?" in reasons_for_control means the control applies only to some paragraphs or is set by country group, so the app says "verify". "VERIFY" means no
-- readable Reason for Control (for example an ITAR cross-reference); it is never treated as uncontrolled.
DELETE FROM eccn_entries WHERE origin = 'ecfr_parse';
UPDATE eccn_entries SET title = 'Chemicals that may be used as precursors for toxic chemical agents', control_text = 'CB applies to entire entry CB Column 2.', license_exceptions_text = 'LVS: N/A | GBS: N/A', related_controls = 'See USML Category XIV for related chemical agent binary precursors and key precursors “subject to the ITAR” (see 22 CFR parts 120 through 130).' WHERE eccn = '1C350' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = 'Electronic items as follows', control_text = 'NS applies to “Monolithic Microwave Integrated Circuit” (“MMIC”) amplifiers in 3A001.b.2 and discrete microwave transistors in 3A001.b.3, except those 3A001.b.2 and b.3 items being exported or reexported for use in civil telecommunications applications -> NS Column 1.; NS applies to entire entry -> NS Column 2.; RS applies “Monolithic Microwave Integrated Circuit” (“MMIC”) amplifiers in 3A001.b.2 and discrete microwave transistors in 3A001.b.3, except those 3A001.b.2 and b.3 items being exported or reexported for use in civil telecommunications applications -> RS Column 1.; RS applies to 3A001.z -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to 3A001.z -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; MT applies to 3A001.a.1.a when usable in “missiles”; and to 3A001.a.5.a when “designed or modified” for military use, hermetically sealed and rated for operation in the temperature range from below −54 °C to above +125 °C; and 3A001.z.2 -> MT Column 1.; NP applies to pulse discharge capacitors in 3A001.e.2 and superconducting solenoidal electromagnets in 3A001.e.3 that meet or exceed the technical parameters in 3A201.a and 3A201.b, respectively; and 3A001.z.3 -> NP Column 1.; AT applies to entire entry -> AT Column 1.', license_exceptions_text = 'LVS: N/A for MT, NP; N/A for “Monolithic Microwave Integrated Circuit” (“MMIC”) amplifiers in 3A001.b.2, discrete microwave transistors in 3A001.b.3, except those that are being exported or reexported for use in civil telecommunications applications; N/A for and 3A001.z. Yes for: $1500: 3A001.c. $3000: 3A001.b.1, b.2 (exported or reexported for use in civil telecommunications applications), b.3 (exported or reexported for use in civil telecommunications applications), b.9, .d, .e, .f, and .g. $5000: 3A001.a (except a.1.a and a.5.a when controlled for MT), b.4 to b.7, and b.12. | GBS: Yes for 3A001.a.1.b, a.2 to a.14 (except .a.5.a when controlled for MT), b.2 (exported or reexported for use in civil telecommunications applications), b.8 (except for “vacuum electronic devices” exceeding 18 GHz), b.9., b.10, .g, .h, .i, and z.1.b (exported or reexported for use in civil telecommunications applications). | NAC/ACA: Yes, for 3A001.z. | ACM: Yes for 3A001.z | STA: License Exception STA may not be used to ship any item in 3A001.b.2 or b.3, except those that are being exported or reexported for use in civil telecommunications applications, or 3A001.z to any of the destinations listed in Country Group A:5 or A:6 (See Supplement No. 1 to part 740 of the EAR).', related_controls = '(1) See Category XV of the USML for certain “space-qualified” electronics and Category XI of the USML for certain ASICs, ''transmit/receive modules,'' ''transmit modules,'' or ''MMICs'' “subject to the ITAR.” (2) See also 3A090, 3A101, 3A201, 3A611, 3A901 for cryogenic CMOS integrated circuits and parametric signal amplifiers or quantum limited amplifiers not controlled by 3A001, 3A991, and 9A515.' WHERE eccn = '3A001' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = 'Integrated circuits as follows', control_text = 'RS applies to entire entry, except for 3A090.c -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to entire entry, except 3A090.c -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; RS applies to 3A090.c -> To or within Macau or a destination specified in Country Group D:5 of supplement no. 1 to part 740 of the EAR. See § 742.6(a)(6)(i)(B) of the EAR.; AT applies to entire entry -> AT Column 1.', license_exceptions_text = 'LVS: N/A | GBS: N/A | NAC/ACA: Yes, for 3A090.a, if the item is not designed or marketed for use in datacenters and has a ''total processing performance'' of 4800 or more; yes, for 3A090.b, if the item is designed or marketed for use in datacenters. N/A for 3A090.c. | HBM: Yes, for 3A090.c. See § 740.25 of the EAR. | ACM: Yes', related_controls = '(1) See ECCNs 3D001, 3E001, 5D002.z, and 5D992.z for associated technology and software controls. (2) See ECCNs 3A001.z, 5A002.z, 5A004.z, and 5A992.z.' WHERE eccn = '3A090' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = 'Digital computers”, “electronic assemblies”, and related equipment therefor, as follows and “specially designed” “components” therefor', control_text = 'NS applies to 4A003.b, .c, and .z.1 -> NS Column 1.; NS applies to 4A003.g and z.2 -> NS Column 2.; RS applies to 4A003.z -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to 4A003.z -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; CC applies to “digital computers” for computerized finger-print equipment -> CC Column 1.; AT applies to entire entry (refer to 4A994 for controls on “digital computers” with an APP >0.0128 but ≤70 WT) -> AT Column 1.', license_exceptions_text = 'LVS: $5000; N/A for 4A003.b, c, and z. | GBS: Yes, for 4A003.g and “specially designed” “parts” and “components” therefor, exported separately or as part of a system. | APP: Yes, for computers controlled by 4A003.b, and “electronic assemblies” controlled by 4A003.c, to the exclusion of other technical parameters. See § 740.7 of the EAR. | NAC/ACA: Yes, for 4A003.z. | ACM: Yes for 4A003.z', related_controls = 'See also ECCNs 4A090, 4A994 and 4A980.' WHERE eccn = '4A003' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = 'Computers as follows and related equipment, “electronic assemblies,” and “components” therefor', control_text = 'RS applies to 4A090 -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to 4A090 -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; AT applies to entire entry -> AT Column 1.', license_exceptions_text = 'LVS: N/A | GBS: N/A | NAC/ACA: Yes | ACM: Yes', related_controls = '(1) For associated “software” for commodities in this ECCN, see 4D090, 5D002.z, and 5D992.z and for associated “technology” for commodities in this ECCN, see 4E001. (2) Also ECCNs 4A003.z, 4A004.z, 4A005.z, 5A002.z, 5A004.z, and 5A992.z.' WHERE eccn = '4A090' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = '“Information security” systems, equipment and “components,” as follows', control_text = 'NS applies to entire entry -> NS Column 1.; RS applies to items controlled by 5A002.z -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to items controlled by 5A002.z -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; AT applies to entire entry -> AT Column 1.; EI applies to entire entry -> Refer to § 742.15 of the EAR.', license_exceptions_text = 'LVS: Yes: $500 for “components,” N/A for systems and equipment. N/A for 5A002.z. | GBS: N/A | ENC: Yes for certain EI controlled commodities, see § 740.17 of the EAR for eligibility. | NAC/ACA: Yes, for 5A002.z.1.b, z.2.b | ACM: Yes for 5A002.z', related_controls = '(1) ECCN 5A002.a controls “components” providing the means or functions necessary for “information security.” All such “components” are presumptively “specially designed” and controlled by 5A002.a. (2) See USML Categories XI (including XI(b)) and XIII(b) (including XIII(b)(2)) for controls on systems, equipment, and components described in 5A002.d or .e that are “subject to the ITAR” (see 22 CFR parts 120 through 130). (3) For “satellite navigation system” receiving equipment containing or employing decryption see 7A005, and for related decryption “software” and “technology” see 7D005 and 7E001. (4) Noting that items may be controlled elsewhere on the CCL, examples of items not controlled by ECCN 5A002.a.4 include the following: (a) An automobile where the only ''cryptography for data confidentiality'' having a ''described security algorithm'' is performed by a Category 5—Part 2 Note 3 eligible mobile telephone that is built into the car. In this case, secure phone communications support a non-primary function of the automobile but the mobile telephone (equipment), as a standalone item, is not controlled by ECCN 5A002 because it is excluded by the Cryptography Note (Note 3) (See ECCN 5A992.c). (b) An exercise bike with an embedded Category 5—Part 2 Note 3 eligible web browser, where the only controlled cryptography is performed by the web browser. In this case, secure web browsing supports a non-primary function of the exercise bike but the web browser (“software”), as a standal…' WHERE eccn = '5A002' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = 'Equipment not controlled by 5A002', control_text = 'RS applies to items controlled by 5A992.z -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to items controlled by 5A992.z -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; AT applies to entire entry -> AT Column 1.', license_exceptions_text = 'LVS: N/A | GBS: N/A | NAC/ACA: Yes, for 5A992.z.2; N/A for all other 5A992 commodities. | ACM: Yes for 5A992.z', related_controls = 'See also ECCNs 3A090 and 4A090.' WHERE eccn = '5A992' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = '“Software” as follows', control_text = 'NS applies to entire entry -> NS Column 1.; RS applies to “software” controlled by 5D002.z -> To or within any destination specified in § 742.6(a)(6)(iii)(A)(1) of the EAR.; RS applies to “software” controlled by 5D002.z -> To or within the United Arab Emirates or destinations specified in Country Groups D:1, D:4, and D:5 of supplement no. 1 to part 740 of the EAR, excluding any destination also specified in Country Groups A:5 or A:6.; AT applies to entire entry -> AT Column 1.; EI applies to “software” in 5D002.a.1, a.3, .b, c.1 and c.3, for commodities or “software” controlled for EI reasons in ECCN 5A002, 5A004 or 5D002 -> Refer to § 742.15 of the EAR. Note: Encryption software is controlled because of its functional capacity, and not because of any informational value of such software; such software is not accorded the same treatment under the EAR as other “software”; and for export licensing purposes, encryption software is treated under the EAR in the same manner as a commodity included in ECCN 5A002.', license_exceptions_text = 'TSR: N/A | ENC: Yes for certain EI controlled software. See § 740.17 of the EAR for eligibility. | NAC/ACA: Yes, for 5D002.z. | ACM: Yes for 5D002.z', related_controls = '(1) After classification or self-classification in accordance with § 740.17(b) of the EAR, mass market encryption software that meets eligibility requirements is released from “EI” and “NS” controls. This software is designated as 5D992.c. (2) See also ECCNs 3D001 as it applies to “software” for commodities controlled by 3A001.z and 3A090, and 4D001 as it applies to “software” for commodities controlled by 4A003.z, 4A004.z, and 4A005.z.' WHERE eccn = '5D002' AND origin = 'hand_verified';
UPDATE eccn_entries SET title = 'Cameras, systems or equipment, and “components” therefor, as follows', control_text = 'NS applies to entire entry -> NS Column 2; NP applies to cameras controlled by 6A003.a.3 or a.4 and to plug-ins in 6A003.a.6 for cameras controlled by 6A003.a.3 or a.4 -> NP Column 1; RS applies to 6A003.b.3, 6A003.b.4.a, 6A003.b.4.c and to items controlled in 6A003.b.4.b that have a frame rate greater than 60 Hz or that incorporate a focal plane array with more than 111,000 elements, or to items in 6A003.b.4.b when being exported or reexported to be embedded in a civil product. (But see § 742.6(a)(2)(iii) and (v) for certain exemptions) -> RS Column 1; RS applies to items controlled in 6A003.b.4.b that have a frame rate of 60 Hz or less and that incorporate a focal plane array with not more than 111,000 elements if not being exported or reexported to be embedded in a civil product -> RS Column 2; AT applies to entire entry -> AT Column 1; UN applies to 6A003.b.3 and b.4 -> See § 746.1(b) for UN controls', license_exceptions_text = 'LVS: $1500, except N/A for 6A003.a.3 through a.6, b.1, b.3 and b.4. | GBS: N/A | STA: License Exception STA may not be used to ship any commodity in 6A003.b.3 or b.4 to any of the destinations listed in Country Group A:6 (See Supplement No.1 to part 740 of the EAR).', related_controls = '(1) See ECCNs 6E001 (“development”), 6E002 (“production”), and 6E201 (“use”) for technology for items controlled under this entry. (2) Also see ECCN 6A203. (3) See ECCN 0A919 for foreign made military commodities that incorporate cameras described in 6A003. (4) Section 744.9 imposes a license requirement on cameras described in 6A003 if being exported, reexported, or transferred (in-country) for use by certain military end-users or for incorporation into a commodity controlled by ECCN 0A919. (5) See USML Category XII(c) and (e) for cameras subject to the ITAR. (6) Also see ECCN 6A293.' WHERE eccn = '6A003' AND origin = 'hand_verified';
